static int plan_alter_table_default_charset_collation(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *statement,
    struct planned_alter_table_default_charset_collation *out_plan
) {
    int rc = MYLITE_OK;

    *out_plan = (struct planned_alter_table_default_charset_collation){0};
    rc = resolve_writable_table_name(database, child_at(statement, 0U), &out_plan->target);
    if (rc == MYLITE_OK && mylite_catalog_name_is_reserved(out_plan->target.table_name)) {
        set_reserved_name_error(database, "table", out_plan->target.table_name);
        rc = MYLITE_ERROR;
    }
    if (rc == MYLITE_OK) {
        rc = mylite_catalog_read_table_by_name(
            database,
            out_plan->target.schema.schema_id,
            out_plan->target.table_name,
            &out_plan->table
        );
        if (rc != MYLITE_OK) {
            set_table_does_not_exist_error(
                database,
                out_plan->target.schema.name,
                out_plan->target.table_name
            );
            rc = MYLITE_ERROR;
        }
    }
    if (rc == MYLITE_OK && out_plan->table.kind != MYLITE_CATALOG_TABLE_KIND_BASE) {
        set_unsupported_error(
            database,
            "ALTER TABLE DEFAULT CHARSET/COLLATE supports only persistent base tables"
        );
        rc = MYLITE_ERROR;
    }
    if (rc == MYLITE_OK) {
        memcpy(
            out_plan->default_charset,
            out_plan->table.default_charset,
            strlen(out_plan->table.default_charset) + 1U
        );
        memcpy(
            out_plan->default_collation,
            out_plan->table.default_collation,
            strlen(out_plan->table.default_collation) + 1U
        );
        rc = validate_alter_table_default_charset_collation_options(
            database,
            child_at(statement, 1U)
        );
    }
    if (rc == MYLITE_OK) {
        rc = apply_alter_table_default_charset_collation_options(
            database,
            child_at(statement, 1U),
            out_plan
        );
    }
    if (rc == MYLITE_OK) {
        out_plan->changes_descriptor = false;
        if (strcmp(out_plan->default_charset, out_plan->table.default_charset) != 0) {
            out_plan->changes_descriptor = true;
        }
        if (strcmp(out_plan->default_collation, out_plan->table.default_collation) != 0) {
            out_plan->changes_descriptor = true;
        }
    }

    return rc;
}

static int apply_alter_table_default_charset_collation_options(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *table_options,
    struct planned_alter_table_default_charset_collation *plan
) {
    const struct mylite_sql_ast_node *table_option = NULL;
    bool has_charset_option = false;
    bool has_collation_option = false;
    int rc = MYLITE_OK;

    if (table_options == NULL || table_options->kind != MYLITE_SQL_AST_TABLE_OPTION_LIST) {
        set_parse_error(database, NULL);
        return MYLITE_ERROR;
    }

    table_option = child_at(table_options, 0U);
    while (table_option != NULL) {
        if (table_option->kind == MYLITE_SQL_AST_TABLE_CHARSET_OPTION) {
            has_charset_option = true;
        } else if (table_option->kind == MYLITE_SQL_AST_TABLE_COLLATION_OPTION) {
            has_collation_option = true;
        }
        table_option = table_option->next_sibling;
    }
    table_option = child_at(table_options, 0U);
    while (rc == MYLITE_OK && table_option != NULL) {
        if (table_option->kind == MYLITE_SQL_AST_TABLE_CHARSET_OPTION) {
            rc = apply_table_charset_option(
                database,
                table_option,
                false,
                plan->default_charset,
                sizeof(plan->default_charset)
            );
        } else if (table_option->kind == MYLITE_SQL_AST_TABLE_COLLATION_OPTION) {
            rc = apply_table_collation_option(
                database,
                table_option,
                false,
                plan->default_collation,
                sizeof(plan->default_collation)
            );
        }
        table_option = table_option->next_sibling;
    }
    if (rc == MYLITE_OK && has_charset_option && !has_collation_option) {
        rc = copy_default_collation_for_charset(
            database,
            plan->default_charset,
            plan->default_collation,
            sizeof(plan->default_collation)
        );
    }

    return rc;
}

static int plan_alter_table_comment(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *statement,
    struct planned_alter_table_comment *out_plan
) {
    int rc = MYLITE_OK;

    *out_plan = (struct planned_alter_table_comment){0};
    rc = resolve_visible_writable_table_reference(
        database,
        child_at(statement, 0U),
        &out_plan->target,
        &out_plan->table
    );
    if (rc == MYLITE_OK && out_plan->table.kind != MYLITE_CATALOG_TABLE_KIND_BASE &&
        out_plan->table.kind != MYLITE_CATALOG_TABLE_KIND_TEMPORARY) {
        set_unsupported_error(database, "ALTER TABLE COMMENT supports only base tables");
        rc = MYLITE_ERROR;
    }
    if (rc == MYLITE_OK) {
        rc = decode_table_comment_option(
            database,
            child_at(statement, 1U),
            out_plan->target.table_name,
            out_plan->comment,
            sizeof(out_plan->comment)
        );
    }

    return rc;
}

static int plan_alter_table_order_by(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *statement,
    struct planned_alter_table_order_by *out_plan
) {
    struct select_source_context source_context = {0};
    int rc = MYLITE_OK;

    *out_plan = (struct planned_alter_table_order_by){0};
    rc = resolve_writable_table_name(database, child_at(statement, 0U), &out_plan->target);
    if (rc == MYLITE_OK && mylite_catalog_name_is_reserved(out_plan->target.table_name)) {
        set_reserved_name_error(database, "table", out_plan->target.table_name);
        rc = MYLITE_ERROR;
    }
    if (rc == MYLITE_OK) {
        rc = mylite_catalog_read_table_by_name(
            database,
            out_plan->target.schema.schema_id,
            out_plan->target.table_name,
            &out_plan->table
        );
        if (rc != MYLITE_OK) {
            set_table_does_not_exist_error(
                database,
                out_plan->target.schema.name,
                out_plan->target.table_name
            );
            rc = MYLITE_ERROR;
        }
    }
    if (rc == MYLITE_OK && out_plan->table.kind != MYLITE_CATALOG_TABLE_KIND_BASE) {
        set_unsupported_error(
            database,
            "ALTER TABLE ORDER BY supports only persistent base tables"
        );
        rc = MYLITE_ERROR;
    }
    if (rc == MYLITE_OK) {
        rc = reject_primary_key_table_alter(
            database,
            out_plan->table.table_id,
            "ALTER TABLE ORDER BY does not yet support primary-key tables"
        );
    }
    if (rc == MYLITE_OK) {
        rc = reject_secondary_index_table_alter(
            database,
            out_plan->table.table_id,
            "ALTER TABLE ORDER BY does not yet support secondary-index tables"
        );
    }
    if (rc == MYLITE_OK) {
        rc = reject_check_constraint_table_alter(
            database,
            out_plan->table.table_id,
            "ALTER TABLE ORDER BY does not yet support CHECK-constrained tables"
        );
    }
    if (rc == MYLITE_OK) {
        rc = load_table_columns(
            database,
            out_plan->table.table_id,
            &out_plan->columns,
            &out_plan->column_count
        );
    }
    if (rc == MYLITE_OK) {
        source_context.source = &out_plan->target;
        rc = plan_alter_table_order_by_items(
            database,
            child_at(statement, 1U),
            &source_context,
            out_plan
        );
    }
    if (rc != MYLITE_OK) {
        planned_alter_table_order_by_deinit(out_plan);
    }

    return rc;
}

static int plan_alter_table_order_by_items(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *order_items,
    const struct select_source_context *source_context,
    struct planned_alter_table_order_by *out_plan
) {
    size_t item_count = mylite_sql_ast_node_child_count(order_items);
    int rc = MYLITE_OK;

    if (order_items == NULL || order_items->kind != MYLITE_SQL_AST_ORDER_BY_ITEM_LIST ||
        item_count == 0U) {
        set_unsupported_error(database, "ALTER TABLE ORDER BY requires descriptor order columns");
        return MYLITE_ERROR;
    }
    if (item_count > SIZE_MAX / sizeof(*out_plan->items)) {
        set_nomem_error(database);
        return MYLITE_NOMEM;
    }

    out_plan->items = calloc(item_count, sizeof(*out_plan->items));
    if (out_plan->items == NULL) {
        set_nomem_error(database);
        return MYLITE_NOMEM;
    }
    out_plan->item_count = item_count;

    for (size_t item_index = 0U; rc == MYLITE_OK && item_index < item_count; ++item_index) {
        rc = plan_alter_table_order_by_item(
            database,
            child_at(order_items, item_index),
            source_context,
            out_plan->columns,
            out_plan->column_count,
            &out_plan->items[item_index]
        );
    }

    return rc;
}

static int plan_alter_table_order_by_item(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *item,
    const struct select_source_context *source_context,
    const struct mylite_catalog_column_descriptor *table_columns,
    size_t table_column_count,
    struct planned_alter_table_order_by_item *out_item
) {
    const struct mylite_sql_ast_node *direction = NULL;
    size_t source_index = 0U;
    int rc = MYLITE_OK;

    *out_item = (struct planned_alter_table_order_by_item){0};
    if (item == NULL || item->kind != MYLITE_SQL_AST_ORDER_BY_ITEM) {
        set_unsupported_error(database, "ALTER TABLE ORDER BY requires descriptor order columns");
        return MYLITE_ERROR;
    }

    rc = resolve_order_column(
        database,
        child_at(item, 0U),
        source_context,
        table_columns,
        table_column_count,
        &out_item->column,
        &source_index
    );
    if (rc != MYLITE_OK) {
        return rc;
    }

    out_item->direction = PLANNED_SELECT_ORDER_ASC;
    direction = child_at(item, 1U);
    if (mylite_sql_ast_node_order_direction(direction) == MYLITE_SQL_AST_ORDER_DIRECTION_DESC) {
        out_item->direction = PLANNED_SELECT_ORDER_DESC;
    }

    return MYLITE_OK;
}

static void planned_alter_table_order_by_deinit(struct planned_alter_table_order_by *plan) {
    if (plan == NULL) {
        return;
    }

    free(plan->columns);
    free(plan->items);
    *plan = (struct planned_alter_table_order_by){0};
}

static int alter_table_order_by_from_plan(
    struct mylite_db *database,
    struct planned_alter_table_order_by *plan
) {
    int rc = execute_physical_alter_table_order_by(database, plan, &plan->affected_rows);

    if (rc != MYLITE_OK) {
        if (rc == MYLITE_NOMEM) {
            set_nomem_error(database);
            return rc;
        }
        set_internal_error_if_clear(database, rc, "failed to rebuild table order");
        return rc;
    }

    return MYLITE_OK;
}

static int plan_alter_table_force(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *statement,
    struct planned_alter_table_force *out_plan
) {
    int rc = MYLITE_OK;

    *out_plan = (struct planned_alter_table_force){0};
    rc = resolve_writable_table_name(database, child_at(statement, 0U), &out_plan->target);
    if (rc == MYLITE_OK && mylite_catalog_name_is_reserved(out_plan->target.table_name)) {
        set_reserved_name_error(database, "table", out_plan->target.table_name);
        rc = MYLITE_ERROR;
    }
    if (rc == MYLITE_OK) {
        rc = mylite_catalog_read_table_by_name(
            database,
            out_plan->target.schema.schema_id,
            out_plan->target.table_name,
            &out_plan->table
        );
        if (rc != MYLITE_OK) {
            set_table_does_not_exist_error(
                database,
                out_plan->target.schema.name,
                out_plan->target.table_name
            );
            rc = MYLITE_ERROR;
        }
    }
    if (rc == MYLITE_OK && out_plan->table.kind != MYLITE_CATALOG_TABLE_KIND_BASE) {
        set_unsupported_error(database, "ALTER TABLE FORCE supports only persistent base tables");
        rc = MYLITE_ERROR;
    }
    if (rc == MYLITE_OK) {
        rc = reject_primary_key_table_alter(
            database,
            out_plan->table.table_id,
            "ALTER TABLE FORCE does not yet support primary-key tables"
        );
    }
    if (rc == MYLITE_OK) {
        rc = reject_secondary_index_table_alter(
            database,
            out_plan->table.table_id,
            "ALTER TABLE FORCE does not yet support secondary-index tables"
        );
    }
    if (rc == MYLITE_OK) {
        rc = reject_check_constraint_table_alter(
            database,
            out_plan->table.table_id,
            "ALTER TABLE FORCE does not yet support CHECK-constrained tables"
        );
    }
    if (rc == MYLITE_OK) {
        rc = load_table_columns(
            database,
            out_plan->table.table_id,
            &out_plan->columns,
            &out_plan->column_count
        );
    }
    if (rc != MYLITE_OK) {
        planned_alter_table_force_deinit(out_plan);
    }

    return rc;
}

static void planned_alter_table_force_deinit(struct planned_alter_table_force *plan) {
    if (plan == NULL) {
        return;
    }

    free(plan->columns);
    *plan = (struct planned_alter_table_force){0};
}

static int alter_table_force_from_plan(
    struct mylite_db *database,
    const struct planned_alter_table_force *plan
) {
    int rc = execute_physical_alter_table_force(database, plan);

    if (rc != MYLITE_OK) {
        if (rc == MYLITE_NOMEM) {
            set_nomem_error(database);
            return rc;
        }
        set_internal_error_if_clear(database, rc, "failed to force rebuild table");
        return rc;
    }

    return MYLITE_OK;
}

static void planned_column_from_catalog_descriptor(
    const struct mylite_catalog_column_descriptor *descriptor,
    const struct mylite_sql_ast_node *default_node,
    struct planned_column *out_column
) {
    *out_column = (struct planned_column){0};
    snprintf(out_column->name, sizeof(out_column->name), "%s", descriptor->name);
    snprintf(
        out_column->logical_type_storage,
        sizeof(out_column->logical_type_storage),
        "%s",
        descriptor->logical_type
    );
    snprintf(
        out_column->physical_type_storage,
        sizeof(out_column->physical_type_storage),
        "%s",
        descriptor->physical_type
    );
    out_column->logical_type = out_column->logical_type_storage;
    out_column->physical_type = out_column->physical_type_storage;
    out_column->is_nullable = descriptor->is_nullable;
    out_column->is_visible = descriptor->is_visible;
    out_column->is_auto_increment = descriptor->is_auto_increment;
    out_column->on_update_current_timestamp = descriptor->on_update_current_timestamp;
    out_column->default_node = default_node;
    out_column->default_kind = descriptor->default_kind;
    out_column->default_integer = descriptor->default_integer;
    snprintf(
        out_column->default_text,
        sizeof(out_column->default_text),
        "%s",
        descriptor->default_text
    );
    snprintf(
        out_column->character_set_name,
        sizeof(out_column->character_set_name),
        "%s",
        descriptor->character_set_name
    );
    snprintf(
        out_column->collation_name,
        sizeof(out_column->collation_name),
        "%s",
        descriptor->collation_name
    );
    snprintf(out_column->comment, sizeof(out_column->comment), "%s", descriptor->comment);
}

static int resolve_alter_table_column_replacement_plan(
    struct mylite_db *database,
    struct planned_alter_table_modify_column *out_plan
) {
    struct mylite_catalog_column_descriptor *columns = NULL;
    size_t column_count = 0U;
    size_t column_index = 0U;
    int rc = mylite_catalog_read_table_by_name(
        database,
        out_plan->target.schema.schema_id,
        out_plan->target.table_name,
        &out_plan->table
    );

    if (rc != MYLITE_OK) {
        set_table_does_not_exist_error(
            database,
            out_plan->target.schema.name,
            out_plan->target.table_name
        );
        return MYLITE_ERROR;
    }
    if (out_plan->table.kind != MYLITE_CATALOG_TABLE_KIND_BASE) {
        set_unsupported_error(database, out_plan->unsupported_object_message);
        return MYLITE_ERROR;
    }
    rc = reject_check_constraint_table_alter(
        database,
        out_plan->table.table_id,
        "ALTER TABLE column replacement does not yet support CHECK-constrained tables"
    );
    if (rc != MYLITE_OK) {
        return rc;
    }
    rc = reject_foreign_key_table_alter(
        database,
        out_plan->table.table_id,
        "ALTER TABLE column replacement does not yet support foreign-key constrained tables"
    );
    if (rc != MYLITE_OK) {
        return rc;
    }

    rc = load_table_columns(database, out_plan->table.table_id, &columns, &column_count);
    if (rc == MYLITE_OK) {
        rc = find_column_index(columns, column_count, out_plan->lookup_column_name, &column_index);
        if (rc != MYLITE_OK) {
            set_unknown_column_in_table_error(
                database,
                out_plan->lookup_column_name,
                out_plan->table.name
            );
            rc = MYLITE_ERROR;
        }
    }
    if (rc == MYLITE_OK && out_plan->checks_duplicate_replacement) {
        size_t replacement_index = 0U;

        if (find_column_index(columns, column_count, out_plan->column.name, &replacement_index) ==
                MYLITE_OK &&
            replacement_index != column_index) {
            set_duplicate_column_error(database, columns[replacement_index].name);
            rc = MYLITE_ERROR;
        }
    }
    if (rc == MYLITE_OK) {
        out_plan->original_column = columns[column_index];
        out_plan->column_index = column_index;
        out_plan->column_count = column_count;
        rc = resolve_alter_table_modify_column_position(database, columns, column_count, out_plan);
    }
    if (rc == MYLITE_OK) {
        rc = load_table_index_infos(
            database,
            out_plan->table.table_id,
            columns,
            column_count,
            &out_plan->indexes,
            &out_plan->index_count
        );
    }
    if (rc == MYLITE_OK) {
        rc = apply_alter_table_modify_primary_key_nullability(database, out_plan);
    }
    if (rc == MYLITE_OK) {
        rc = validate_alter_table_modify_indexes(database, out_plan);
    }
    if (rc == MYLITE_OK) {
        rc = complete_alter_table_modify_column_plan(database, columns, out_plan);
    }

    free(columns);

    return rc;
}

static int apply_alter_table_modify_primary_key_nullability(
    struct mylite_db *database,
    struct planned_alter_table_modify_column *out_plan
) {
    for (size_t index = 0U; index < out_plan->index_count; ++index) {
        const struct loaded_index_info *key = &out_plan->indexes[index];

        if (key->index.kind != MYLITE_CATALOG_INDEX_KIND_PRIMARY ||
            !loaded_index_contains_column_id(key, out_plan->original_column.column_id)) {
            continue;
        }
        if (out_plan->column.nullability == MYLITE_SQL_AST_NULLABILITY_NULL) {
            set_primary_key_part_null_error(database);
            return MYLITE_ERROR;
        }
        if (out_plan->column.nullability == MYLITE_SQL_AST_NULLABILITY_UNSPECIFIED) {
            out_plan->column.is_nullable = false;
        }
        return MYLITE_OK;
    }

    return MYLITE_OK;
}

static int validate_alter_table_modify_indexes(
    struct mylite_db *database,
    struct planned_alter_table_modify_column *plan
) {
    int rc = refresh_alter_table_modify_index_parts(plan);

    for (size_t index = 0U; rc == MYLITE_OK && index < plan->index_count; ++index) {
        const struct loaded_index_info *key = &plan->indexes[index];

        if (key->index.kind == MYLITE_CATALOG_INDEX_KIND_PRIMARY) {
            rc = validate_alter_table_modify_primary_index(database, key);
        } else if (key->index.kind == MYLITE_CATALOG_INDEX_KIND_SECONDARY) {
            rc = validate_loaded_index_part_list(
                database,
                key->parts,
                key->part_count,
                key->index.is_unique
            );
        } else if (key->index.kind == MYLITE_CATALOG_INDEX_KIND_FULLTEXT) {
            rc = validate_alter_table_modify_fulltext_index(database, key);
        } else if (key->index.kind == MYLITE_CATALOG_INDEX_KIND_SPATIAL) {
            rc = validate_alter_table_modify_spatial_index(database, key);
        }
    }

    return rc;
}

static int refresh_alter_table_modify_index_parts(struct planned_alter_table_modify_column *plan) {
    for (size_t index = 0U; index < plan->index_count; ++index) {
        struct loaded_index_info *key = &plan->indexes[index];

        for (size_t part_index = 0U; part_index < key->part_count; ++part_index) {
            struct loaded_index_part *part = &key->parts[part_index];

            if (part->index_column.column_id == plan->original_column.column_id) {
                make_modify_target_descriptor(plan, &part->column);
            }
        }
    }

    return MYLITE_OK;
}

static int validate_alter_table_modify_primary_index(
    struct mylite_db *database,
    const struct loaded_index_info *index
) {
    uint64_t total = 0U;

    if (index == NULL || index->part_count == 0U) {
        set_runtime_error(database, "invalid primary-key descriptor");
        return MYLITE_ERROR;
    }
    for (size_t part_index = 0U; part_index < index->part_count; ++part_index) {
        const struct loaded_index_part *part = &index->parts[part_index];
        uint64_t part_bytes = 0U;
        int rc = MYLITE_OK;

        if (part->column.is_nullable) {
            set_primary_key_part_null_error(database);
            return MYLITE_ERROR;
        }
        rc = column_descriptor_primary_key_part_key_bytes(database, &part->column, &part_bytes);
        if (rc != MYLITE_OK) {
            return rc;
        }
        if (total > UINT64_MAX - part_bytes) {
            set_key_too_long_error(database, innodb_max_key_length_bytes);
            return MYLITE_ERROR;
        }
        total += part_bytes;
        if (total > innodb_max_key_length_bytes) {
            set_key_too_long_error(database, innodb_max_key_length_bytes);
            return MYLITE_ERROR;
        }
    }

    return MYLITE_OK;
}

static int validate_alter_table_modify_fulltext_index(
    struct mylite_db *database,
    const struct loaded_index_info *index
) {
    if (index == NULL || index->part_count == 0U) {
        set_runtime_error(database, "invalid FULLTEXT index descriptor");
        return MYLITE_ERROR;
    }
    for (size_t part_index = 0U; part_index < index->part_count; ++part_index) {
        struct planned_column column = {0};

        planned_column_from_catalog_descriptor(&index->parts[part_index].column, NULL, &column);
        int rc = validate_fulltext_index_column(database, &column);
        if (rc != MYLITE_OK) {
            return rc;
        }
    }

    return MYLITE_OK;
}

static int validate_alter_table_modify_spatial_index(
    struct mylite_db *database,
    const struct loaded_index_info *index
) {
    if (index == NULL || index->part_count != 1U) {
        set_runtime_error(database, "invalid SPATIAL index descriptor");
        return MYLITE_ERROR;
    }

    return validate_alter_table_add_spatial_column(database, &index->parts[0].column);
}

static int resolve_alter_table_modify_column_position(
    struct mylite_db *database,
    const struct mylite_catalog_column_descriptor *columns,
    size_t column_count,
    struct planned_alter_table_modify_column *out_plan
) {
    size_t after_column_index = 0U;
    int rc = MYLITE_OK;

    out_plan->target_column_index = out_plan->column_index;
    if (!out_plan->has_position) {
        return MYLITE_OK;
    }
    if (out_plan->position_first) {
        out_plan->target_column_index = 0U;
        out_plan->changes_position = out_plan->target_column_index != out_plan->column_index;
        return MYLITE_OK;
    }

    rc = find_column_index(columns, column_count, out_plan->after_column_name, &after_column_index);
    if (rc != MYLITE_OK || after_column_index == out_plan->column_index) {
        set_unknown_column_in_table_error(
            database,
            out_plan->after_column_name,
            out_plan->table.name
        );
        return MYLITE_ERROR;
    }

    if (after_column_index < out_plan->column_index) {
        out_plan->target_column_index = after_column_index + 1U;
    } else {
        out_plan->target_column_index = after_column_index;
    }
    out_plan->changes_position = out_plan->target_column_index != out_plan->column_index;
    return MYLITE_OK;
}

static int complete_alter_table_modify_column_plan(
    struct mylite_db *database,
    const struct mylite_catalog_column_descriptor *columns,
    struct planned_alter_table_modify_column *out_plan
) {
    bool supports_char_varchar_replacement = modify_column_char_varchar_replacement_supported(
        &out_plan->original_column,
        &out_plan->column
    );
    bool supports_text_family_replacement = modify_column_text_family_replacement_supported(
        &out_plan->original_column,
        &out_plan->column
    );
    bool supports_binary_string_replacement = modify_column_binary_string_replacement_supported(
        &out_plan->original_column,
        &out_plan->column
    );
    bool supports_temporal_replacement =
        modify_column_temporal_replacement_supported(&out_plan->original_column, &out_plan->column);
    int rc = MYLITE_OK;

    if (!supports_char_varchar_replacement && !supports_text_family_replacement &&
        !supports_binary_string_replacement && !supports_temporal_replacement &&
        (column_descriptor_is_string_family(&out_plan->original_column) ||
         column_descriptor_is_binary_string_family(&out_plan->original_column) ||
         column_descriptor_is_json(&out_plan->original_column) ||
         column_descriptor_is_bit(&out_plan->original_column) ||
         column_descriptor_is_decimal(&out_plan->original_column) ||
         column_descriptor_is_approximate(&out_plan->original_column) ||
         column_descriptor_is_date(&out_plan->original_column) ||
         column_descriptor_is_time(&out_plan->original_column) ||
         column_descriptor_is_datetime(&out_plan->original_column) ||
         column_descriptor_is_timestamp(&out_plan->original_column) ||
         column_descriptor_is_year(&out_plan->original_column) ||
         column_descriptor_is_enum(&out_plan->original_column) ||
         column_descriptor_is_set(&out_plan->original_column) ||
         column_descriptor_is_spatial(&out_plan->original_column) ||
         planned_column_is_string_family(&out_plan->column) ||
         planned_column_is_binary_string_family(&out_plan->column) ||
         planned_column_is_json(&out_plan->column) || planned_column_is_bit(&out_plan->column) ||
         planned_column_is_enum(&out_plan->column) || planned_column_is_set(&out_plan->column) ||
         planned_column_is_decimal(&out_plan->column) ||
         planned_column_is_approximate(&out_plan->column) ||
         planned_column_is_date(&out_plan->column) || planned_column_is_time(&out_plan->column) ||
         planned_column_is_datetime(&out_plan->column) ||
         planned_column_is_timestamp(&out_plan->column) ||
         planned_column_is_year(&out_plan->column) ||
         planned_column_is_spatial(&out_plan->column))) {
        set_unsupported_error(database, out_plan->integer_support_message);
        return MYLITE_ERROR;
    }
    if (modify_column_definition_matches(&out_plan->original_column, &out_plan->column)) {
        if (modify_column_name_matches(&out_plan->original_column, &out_plan->column)) {
            if (out_plan->changes_position) {
                goto rebuild_column;
            }
            if (out_plan->original_column.is_visible) {
                out_plan->is_noop = true;
            } else {
                out_plan->is_metadata_only = true;
            }
            return MYLITE_OK;
        }
        if (out_plan->changes_position) {
            goto rebuild_column;
        }
        out_plan->is_metadata_only = true;
        return MYLITE_OK;
    }
    if (!out_plan->changes_position &&
        modify_column_metadata_only_replacement(&out_plan->original_column, &out_plan->column)) {
        out_plan->is_metadata_only = true;
        return MYLITE_OK;
    }

rebuild_column:
    if (!modify_column_type_matches(&out_plan->original_column, &out_plan->column)) {
        out_plan->reports_rebuild_row_count = true;
    }
    rc = choose_sqlite_rowid_alias(
        database,
        columns,
        out_plan->column_count,
        out_plan->rowid_alias_message,
        &out_plan->rowid_alias
    );
    if (rc == MYLITE_OK) {
        rc = collect_modify_column_rebuild_columns(
            database,
            columns,
            out_plan->column_count,
            out_plan
        );
    }

    return rc;
}

static bool modify_column_definition_matches(
    const struct mylite_catalog_column_descriptor *original_column,
    const struct planned_column *replacement_column
) {
    if (strcmp(original_column->logical_type, replacement_column->logical_type) != 0) {
        return false;
    }
    if (strcmp(original_column->physical_type, replacement_column->physical_type) != 0) {
        return false;
    }
    if (original_column->is_nullable != replacement_column->is_nullable) {
        return false;
    }
    if (original_column->on_update_current_timestamp !=
        replacement_column->on_update_current_timestamp) {
        return false;
    }
    if (strcmp(original_column->character_set_name, replacement_column->character_set_name) != 0) {
        return false;
    }
    if (strcmp(original_column->collation_name, replacement_column->collation_name) != 0) {
        return false;
    }
    if (strcmp(original_column->comment, replacement_column->comment) != 0) {
        return false;
    }
    if (original_column->default_kind != replacement_column->default_kind) {
        return false;
    }
    if (original_column->default_kind == MYLITE_CATALOG_COLUMN_DEFAULT_INTEGER &&
        original_column->default_integer != replacement_column->default_integer) {
        return false;
    }
    if (original_column->default_kind == MYLITE_CATALOG_COLUMN_DEFAULT_INTEGER_EXPRESSION &&
        original_column->default_integer != replacement_column->default_integer) {
        return false;
    }
    if ((original_column->default_kind == MYLITE_CATALOG_COLUMN_DEFAULT_DECIMAL ||
         original_column->default_kind == MYLITE_CATALOG_COLUMN_DEFAULT_TEXT ||
         column_default_kind_is_expression(original_column->default_kind)) &&
        strcmp(original_column->default_text, replacement_column->default_text) != 0) {
        return false;
    }

    return true;
}

static bool modify_column_type_matches(
    const struct mylite_catalog_column_descriptor *original_column,
    const struct planned_column *replacement_column
) {
    if (strcmp(original_column->logical_type, replacement_column->logical_type) != 0) {
        return false;
    }
    if (strcmp(original_column->physical_type, replacement_column->physical_type) != 0) {
        return false;
    }

    return true;
}

static bool modify_column_metadata_only_replacement(
    const struct mylite_catalog_column_descriptor *original_column,
    const struct planned_column *replacement_column
) {
    if (strcmp(original_column->physical_type, replacement_column->physical_type) != 0) {
        return false;
    }
    if (original_column->is_nullable != replacement_column->is_nullable) {
        return false;
    }
    if (!modify_column_integer_value_domain_matches(original_column, replacement_column)) {
        return false;
    }

    return true;
}

static bool modify_column_name_matches(
    const struct mylite_catalog_column_descriptor *original_column,
    const struct planned_column *replacement_column
) {
    if (strcmp(original_column->name, replacement_column->name) != 0) {
        return false;
    }

    return true;
}

static void planned_alter_table_modify_column_deinit(
    struct planned_alter_table_modify_column *plan
) {
    if (plan == NULL) {
        return;
    }

    free(plan->columns);
    loaded_index_infos_deinit(&plan->indexes, &plan->index_count);
    *plan = (struct planned_alter_table_modify_column){0};
}

static int alter_table_modify_column_from_plan(
    struct mylite_db *database,
    struct planned_alter_table_modify_column *plan
) {
    struct mylite_catalog_mutation mutation = {.active = false, .next_generation = 0U};
    int64_t validated_row_count = 0;
    int rc = MYLITE_OK;

    if (plan->is_noop) {
        return MYLITE_OK;
    }

    rc = mylite_catalog_begin_mutation(database, &mutation);
    if (rc == MYLITE_OK && !plan->is_metadata_only) {
        rc = validate_modify_column_existing_rows(database, plan, &validated_row_count);
        if (rc == MYLITE_OK && plan->reports_rebuild_row_count) {
            plan->affected_rows = validated_row_count;
        }
    }
    if (rc == MYLITE_OK) {
        rc = mylite_catalog_replace_column_in_mutation(
            database,
            &mutation,
            plan->table.table_id,
            plan->original_column.column_id,
            plan->column.name,
            plan->column.logical_type,
            plan->column.physical_type,
            plan->column.is_nullable,
            true,
            plan->column.is_auto_increment,
            plan->column.default_kind,
            plan->column.default_integer,
            plan->column.default_text,
            plan->column.on_update_current_timestamp,
            plan->column.character_set_name,
            plan->column.collation_name,
            plan->column.comment
        );
    }
    if (rc == MYLITE_OK && plan->changes_position) {
        const struct mylite_catalog_column_reorder reorder = {
            .table_id = plan->table.table_id,
            .columns = plan->columns,
            .column_count = plan->column_count,
            .metadata_replaced_column_id = plan->original_column.column_id,
        };

        rc = mylite_catalog_reorder_columns_in_mutation(database, &mutation, &reorder);
    }
    if (rc == MYLITE_OK && plan->is_metadata_only) {
        if (!modify_column_name_matches(&plan->original_column, &plan->column)) {
            struct planned_alter_table_rename_column rename_plan = {
                .target = plan->target,
                .table = plan->table,
                .column = plan->original_column,
                .is_noop = false,
            };

            memcpy(
                rename_plan.new_column_name,
                plan->column.name,
                sizeof(rename_plan.new_column_name)
            );
            rc = execute_physical_alter_table_rename_column(database, &rename_plan);
        }
    } else if (rc == MYLITE_OK) {
        rc = execute_physical_alter_table_modify_column(database, plan, &mutation);
    }
    if (rc == MYLITE_OK) {
        rc = mylite_catalog_update_table_identity_in_mutation(
            database,
            &mutation,
            plan->table.table_id,
            plan->table.schema_id,
            plan->table.name,
            NULL
        );
    }
    if (rc == MYLITE_OK) {
        rc = mylite_catalog_commit_mutation(database, &mutation);
    }
    if (rc != MYLITE_OK) {
        set_internal_error_if_clear(database, rc, plan->failure_message);
        mylite_catalog_rollback_mutation(database, &mutation);
        return rc;
    }

    if (!plan->is_metadata_only ||
        !modify_column_name_matches(&plan->original_column, &plan->column)) {
        ++database->session.sqlite_schema_generation;
    }

    return MYLITE_OK;
}

static int collect_modify_column_rebuild_columns(
    struct mylite_db *database,
    const struct mylite_catalog_column_descriptor *columns,
    size_t column_count,
    struct planned_alter_table_modify_column *out_plan
) {
    struct mylite_catalog_column_descriptor *rebuild_columns = NULL;

    if (column_count > SIZE_MAX / sizeof(*rebuild_columns)) {
        set_nomem_error(database);
        return MYLITE_NOMEM;
    }

    rebuild_columns = calloc(column_count, sizeof(*rebuild_columns));
    if (rebuild_columns == NULL) {
        set_nomem_error(database);
        return MYLITE_NOMEM;
    }

    if (!out_plan->changes_position) {
        for (size_t index = 0U; index < column_count; ++index) {
            rebuild_columns[index] = columns[index];
            if (index == out_plan->column_index) {
                make_modify_target_descriptor(out_plan, &rebuild_columns[index]);
            }
        }
    } else {
        size_t source_index = 0U;

        for (size_t index = 0U; index < column_count; ++index) {
            if (index == out_plan->target_column_index) {
                make_modify_target_descriptor(out_plan, &rebuild_columns[index]);
            } else {
                while (source_index < column_count && source_index == out_plan->column_index) {
                    ++source_index;
                }
                if (source_index >= column_count) {
                    free(rebuild_columns);
                    set_runtime_error(database, "failed to plan column reorder");
                    return MYLITE_ERROR;
                }
                rebuild_columns[index] = columns[source_index];
                ++source_index;
            }
        }
    }

    out_plan->columns = rebuild_columns;
    return MYLITE_OK;
}

static int validate_modify_column_existing_rows(
    struct mylite_db *database,
    const struct planned_alter_table_modify_column *plan,
    int64_t *out_row_count
) {
    sqlite3_stmt *statement = NULL;
    struct mylite_catalog_column_descriptor target_column = {0};
    char *sql = NULL;
    size_t row_number = 0U;
    int sqlite_rc = SQLITE_OK;
    int rc = build_alter_table_modify_validation_sql(plan, &sql);

    *out_row_count = 0;
    if (rc == MYLITE_OK) {
        rc = prepare_sqlite_statement(database, sql, &statement);
    }
    make_modify_target_descriptor(plan, &target_column);
    while (rc == MYLITE_OK && (sqlite_rc = sqlite3_step(statement)) == SQLITE_ROW) {
        int sqlite_type = sqlite3_column_type(statement, 0);

        if (row_number >= (size_t)INT64_MAX) {
            set_runtime_error(database, plan->row_count_overflow_message);
            rc = MYLITE_ERROR;
            break;
        }
        ++row_number;
        if (sqlite_type == SQLITE_NULL) {
            if (!target_column.is_nullable) {
                set_invalid_use_of_null_error(database);
                rc = MYLITE_ERROR;
            }
        } else if (sqlite_type == SQLITE_INTEGER) {
            rc = validate_existing_integer_for_column(
                database,
                (int64_t)sqlite3_column_int64(statement, 0),
                &target_column,
                row_number,
                plan->integer_support_message
            );
        } else if (
            column_descriptor_is_binary_string_family(&target_column) &&
            (sqlite_type == SQLITE_TEXT || sqlite_type == SQLITE_BLOB)
        ) {
            rc = validate_existing_binary_bytes_for_column(
                database,
                sqlite3_column_blob(statement, 0),
                sqlite3_column_bytes(statement, 0),
                &target_column,
                row_number
            );
        } else if (sqlite_type == SQLITE_TEXT) {
            rc = validate_existing_text_for_column(
                database,
                sqlite3_column_text(statement, 0),
                sqlite3_column_bytes(statement, 0),
                &target_column,
                row_number
            );
        } else {
            set_physical_sqlite_row_error(database);
            rc = MYLITE_ERROR;
        }
    }
    if (rc == MYLITE_OK && sqlite_rc != SQLITE_DONE) {
        rc = mylite_sqlite_status_to_mylite(sqlite_rc);
    }
    rc = finalize_sqlite_statement(statement, rc);
    free(sql);

    if (rc == MYLITE_OK) {
        *out_row_count = (int64_t)row_number;
    } else if (rc == MYLITE_NOMEM) {
        set_nomem_error(database);
    } else if (mylite_diagnostics_errcode(mylite_connection_diagnostics(database)) == MYLITE_OK) {
        set_physical_sqlite_row_error(database);
        rc = MYLITE_ERROR;
    }

    return rc;
}

static int validate_existing_integer_for_column(
    struct mylite_db *database,
    int64_t value,
    const struct mylite_catalog_column_descriptor *column,
    size_t row_number,
    const char *unsupported_message
) {
    struct integer_column_range range = {0};
    int rc = integer_range_for_column(database, column, unsupported_message, &range);

    if (rc != MYLITE_OK) {
        return rc;
    }
    if (value < 0) {
        const uint64_t int64_min_magnitude = (uint64_t)INT64_MAX + 1U;
        uint64_t magnitude = value == INT64_MIN ? int64_min_magnitude : (uint64_t)(-value);

        if (range.negative_abs_max == 0U || magnitude > range.negative_abs_max) {
            set_out_of_range_error(database, column->name, row_number);
            return MYLITE_ERROR;
        }
        return MYLITE_OK;
    }

    if ((uint64_t)value > range.positive_max) {
        set_out_of_range_error(database, column->name, row_number);
        return MYLITE_ERROR;
    }

    return MYLITE_OK;
}

static int validate_existing_text_for_column(
    struct mylite_db *database,
    const unsigned char *text,
    int byte_count,
    const struct mylite_catalog_column_descriptor *column,
    size_t row_number
) {
    if (text == NULL || byte_count < 0) {
        set_physical_sqlite_row_error(database);
        return MYLITE_ERROR;
    }
    if (column_descriptor_is_varchar(column)) {
        return validate_varchar_text(
            database,
            column,
            (struct varchar_text_validation){
                .text = (const char *)text,
                .text_length = (size_t)byte_count,
                .row_number = row_number,
            }
        );
    }
    if (column_descriptor_is_char(column)) {
        return validate_canonical_char_text(
            database,
            column,
            (struct varchar_text_validation){
                .text = (const char *)text,
                .text_length = (size_t)byte_count,
                .row_number = row_number,
            }
        );
    }
    if (column_descriptor_is_text_family(column)) {
        return validate_text_family_text(
            database,
            column,
            (struct varchar_text_validation){
                .text = (const char *)text,
                .text_length = (size_t)byte_count,
                .row_number = row_number,
            }
        );
    }
    if (column_descriptor_is_datetime(column)) {
        if (predicate_datetime_text_admitted(database, (const char *)text, (size_t)byte_count)) {
            return MYLITE_OK;
        }
        set_incorrect_datetime_value_error(database, (const char *)text, column->name, row_number);
        return MYLITE_ERROR;
    }
    if (column_descriptor_is_timestamp(column)) {
        if (predicate_timestamp_text_admitted(database, (const char *)text, (size_t)byte_count)) {
            return MYLITE_OK;
        }
        set_incorrect_datetime_value_error(database, (const char *)text, column->name, row_number);
        return MYLITE_ERROR;
    }

    set_physical_sqlite_row_error(database);
    return MYLITE_ERROR;
}

static int validate_existing_binary_bytes_for_column(
    struct mylite_db *database,
    const void *bytes,
    int byte_count,
    const struct mylite_catalog_column_descriptor *column,
    size_t row_number
) {
    char *copy = NULL;
    size_t copy_length = 0U;
    int rc = MYLITE_OK;

    if ((bytes == NULL && byte_count != 0) || byte_count < 0) {
        set_physical_sqlite_row_error(database);
        return MYLITE_ERROR;
    }
    copy_length = (size_t)byte_count;
    copy = malloc(copy_length + 1U);
    if (copy == NULL) {
        set_nomem_error(database);
        return MYLITE_NOMEM;
    }
    if (copy_length != 0U) {
        memcpy(copy, bytes, copy_length);
    }
    copy[copy_length] = '\0';
    rc = convert_binary_bytes_for_column(database, column, row_number, false, &copy, &copy_length);
    free(copy);
    return rc;
}

static void make_modify_target_descriptor(
    const struct planned_alter_table_modify_column *plan,
    struct mylite_catalog_column_descriptor *out_column
) {
    *out_column = plan->original_column;
    memcpy(out_column->name, plan->column.name, sizeof(out_column->name));
    snprintf(
        out_column->logical_type,
        sizeof(out_column->logical_type),
        "%s",
        plan->column.logical_type
    );
    snprintf(
        out_column->physical_type,
        sizeof(out_column->physical_type),
        "%s",
        plan->column.physical_type
    );
    out_column->is_nullable = plan->column.is_nullable;
    out_column->on_update_current_timestamp = plan->column.on_update_current_timestamp;
    out_column->default_kind = plan->column.default_kind;
    out_column->default_integer = plan->column.default_integer;
    snprintf(
        out_column->default_text,
        sizeof(out_column->default_text),
        "%s",
        plan->column.default_text
    );
    snprintf(
        out_column->character_set_name,
        sizeof(out_column->character_set_name),
        "%s",
        plan->column.character_set_name
    );
    snprintf(
        out_column->collation_name,
        sizeof(out_column->collation_name),
        "%s",
        plan->column.collation_name
    );
}

static int execute_physical_alter_table_modify_column(
    struct mylite_db *database,
    const struct planned_alter_table_modify_column *plan,
    const struct mylite_catalog_mutation *mutation
) {
    char temporary_physical_name[MYLITE_CATALOG_PHYSICAL_NAME_CAPACITY];
    char *sql = NULL;
    int rc = build_modify_temporary_physical_name(
        plan,
        mutation,
        temporary_physical_name,
        sizeof(temporary_physical_name)
    );

    if (rc == MYLITE_OK) {
        rc = build_alter_table_modify_create_sql(plan, temporary_physical_name, &sql);
    }
    if (rc == MYLITE_OK) {
        rc = execute_sqlite_schema_sql(database, sql);
    }
    free(sql);
    sql = NULL;

    if (rc == MYLITE_OK) {
        if (alter_table_modify_needs_binary_copy_materialization(plan)) {
            rc = execute_physical_alter_table_modify_copy_rows(
                database,
                plan,
                temporary_physical_name
            );
        } else {
            rc = build_alter_table_modify_copy_sql(plan, temporary_physical_name, &sql);
            if (rc == MYLITE_OK) {
                rc = execute_sqlite_schema_sql(database, sql);
            }
        }
    }
    free(sql);
    sql = NULL;

    if (rc == MYLITE_OK) {
        rc = execute_physical_drop_table(database, plan->table.physical_name);
    }
    if (rc == MYLITE_OK) {
        rc = build_alter_table_rename_physical_table_sql(
            temporary_physical_name,
            plan->table.physical_name,
            &sql
        );
    }
    if (rc == MYLITE_OK) {
        rc = execute_sqlite_schema_sql(database, sql);
    }
    free(sql);
    sql = NULL;

    if (rc == MYLITE_OK) {
        rc = build_alter_table_modify_indexes_sql(plan, &sql);
    }
    if (rc == MYLITE_OK && sql != NULL) {
        rc = execute_sqlite_schema_sql(database, sql);
    }
    free(sql);

    return rc;
}

static int execute_physical_alter_table_order_by(
    struct mylite_db *database,
    const struct planned_alter_table_order_by *plan,
    int64_t *out_affected_rows
) {
    sqlite3_stmt *statement = NULL;
    char temporary_physical_name[MYLITE_CATALOG_PHYSICAL_NAME_CAPACITY];
    char *sql = NULL;
    bool transaction_started = false;
    bool copy_failed = false;
    int64_t affected_rows = 0;
    int sqlite_rc = SQLITE_OK;
    int rc = build_alter_table_order_temporary_physical_name(
        plan,
        database->session.sqlite_schema_generation + 1U,
        temporary_physical_name,
        sizeof(temporary_physical_name)
    );

    *out_affected_rows = 0;
    if (rc == MYLITE_OK) {
        rc = execute_sqlite_control_sql(database, "BEGIN IMMEDIATE");
    }
    if (rc == MYLITE_OK) {
        transaction_started = true;
        rc = build_alter_table_order_create_sql(plan, temporary_physical_name, &sql);
    }
    if (rc == MYLITE_OK) {
        rc = execute_sqlite_schema_sql(database, sql);
    }
    free(sql);
    sql = NULL;

    if (rc == MYLITE_OK) {
        rc = build_alter_table_order_copy_sql(plan, temporary_physical_name, &sql);
    }
    if (rc == MYLITE_OK) {
        rc = prepare_sqlite_statement(database, sql, &statement);
    }
    if (rc == MYLITE_OK) {
        sqlite_rc = sqlite3_step(statement);
        if (sqlite_rc == SQLITE_DONE) {
            affected_rows = (int64_t)sqlite3_changes64(database->sqlite);
        } else {
            rc = mylite_sqlite_status_to_mylite(sqlite_rc);
        }
    }
    rc = finalize_sqlite_statement(statement, rc);
    statement = NULL;
    if (rc != MYLITE_OK) {
        copy_failed = true;
    }
    free(sql);
    sql = NULL;

    if (rc == MYLITE_OK) {
        rc = execute_physical_drop_table(database, plan->table.physical_name);
    }
    if (rc == MYLITE_OK) {
        rc = build_alter_table_rename_physical_table_sql(
            temporary_physical_name,
            plan->table.physical_name,
            &sql
        );
    }
    if (rc == MYLITE_OK) {
        rc = execute_sqlite_schema_sql(database, sql);
    }
    free(sql);
    sql = NULL;

    if (rc == MYLITE_OK) {
        rc = execute_sqlite_control_sql(database, "COMMIT");
        if (rc == MYLITE_OK) {
            transaction_started = false;
        }
    }
    if (rc != MYLITE_OK && transaction_started) {
        (void)execute_sqlite_control_sql(database, "ROLLBACK");
    }
    if (rc != MYLITE_OK && rc != MYLITE_NOMEM && copy_failed) {
        set_physical_sqlite_row_error(database);
    }
    if (rc == MYLITE_OK) {
        ++database->session.sqlite_schema_generation;
        *out_affected_rows = affected_rows;
    }

    return rc;
}

static int execute_physical_alter_table_force(
    struct mylite_db *database,
    const struct planned_alter_table_force *plan
) {
    sqlite3_stmt *statement = NULL;
    char temporary_physical_name[MYLITE_CATALOG_PHYSICAL_NAME_CAPACITY];
    char *sql = NULL;
    bool transaction_started = false;
    bool copy_failed = false;
    int sqlite_rc = SQLITE_OK;
    int rc = build_alter_table_force_temporary_physical_name(
        plan,
        database->session.sqlite_schema_generation + 1U,
        temporary_physical_name,
        sizeof(temporary_physical_name)
    );

    if (rc == MYLITE_OK) {
        rc = execute_sqlite_control_sql(database, "BEGIN IMMEDIATE");
    }
    if (rc == MYLITE_OK) {
        transaction_started = true;
        rc = build_alter_table_force_create_sql(plan, temporary_physical_name, &sql);
    }
    if (rc == MYLITE_OK) {
        rc = execute_sqlite_schema_sql(database, sql);
    }
    free(sql);
    sql = NULL;

    if (rc == MYLITE_OK) {
        rc = build_alter_table_force_copy_sql(plan, temporary_physical_name, &sql);
    }
    if (rc == MYLITE_OK) {
        rc = prepare_sqlite_statement(database, sql, &statement);
    }
    if (rc == MYLITE_OK) {
        sqlite_rc = sqlite3_step(statement);
        if (sqlite_rc != SQLITE_DONE) {
            rc = mylite_sqlite_status_to_mylite(sqlite_rc);
        }
    }
    rc = finalize_sqlite_statement(statement, rc);
    statement = NULL;
    if (rc != MYLITE_OK) {
        copy_failed = true;
    }
    free(sql);
    sql = NULL;

    if (rc == MYLITE_OK) {
        rc = execute_physical_drop_table(database, plan->table.physical_name);
    }
    if (rc == MYLITE_OK) {
        rc = build_alter_table_rename_physical_table_sql(
            temporary_physical_name,
            plan->table.physical_name,
            &sql
        );
    }
    if (rc == MYLITE_OK) {
        rc = execute_sqlite_schema_sql(database, sql);
    }
    free(sql);
    sql = NULL;

    if (rc == MYLITE_OK) {
        rc = execute_sqlite_control_sql(database, "COMMIT");
        if (rc == MYLITE_OK) {
            transaction_started = false;
        }
    }
    if (rc != MYLITE_OK && transaction_started) {
        (void)execute_sqlite_control_sql(database, "ROLLBACK");
    }
    if (rc != MYLITE_OK && rc != MYLITE_NOMEM && copy_failed) {
        set_physical_sqlite_row_error(database);
    }
    if (rc == MYLITE_OK) {
        ++database->session.sqlite_schema_generation;
    }

    return rc;
}

static int build_alter_table_check_temporary_physical_name(
    const struct planned_alter_table_check_constraint *plan,
    uint64_t sqlite_schema_generation,
    char *destination,
    size_t destination_size
) {
    int written = 0;

    if (plan == NULL || destination == NULL || destination_size == 0U) {
        return MYLITE_MISUSE;
    }

    written = snprintf(
        destination,
        destination_size,
        "_mylite_user_table_%" PRId64 "_check_%" PRIu64,
        plan->table.table_id,
        sqlite_schema_generation
    );
    if (written < 0 || (size_t)written >= destination_size) {
        return MYLITE_NOMEM;
    }

    return MYLITE_OK;
}

static int build_alter_table_check_create_sql(
    const struct planned_alter_table_check_constraint *plan,
    const char *temporary_physical_name,
    char **out_sql
) {
    return build_create_table_definition_sql(
        &plan->rebuild,
        temporary_physical_name,
        false,
        out_sql
    );
}

static int build_alter_table_check_copy_sql(
    const struct planned_alter_table_check_constraint *plan,
    const char *temporary_physical_name,
    char **out_sql
) {
    struct dynamic_string string;
    int rc = MYLITE_OK;

    *out_sql = NULL;
    dynamic_string_init(&string);

    rc = dynamic_string_append(&string, "INSERT INTO ");
    if (rc == MYLITE_OK) {
        rc = dynamic_string_append_quoted_identifier(&string, temporary_physical_name);
    }
    if (rc == MYLITE_OK) {
        rc = dynamic_string_append(&string, " (");
    }
    if (rc == MYLITE_OK) {
        rc = append_alter_table_check_column_list(&string, plan);
    }
    if (rc == MYLITE_OK) {
        rc = dynamic_string_append(&string, ") SELECT ");
    }
    if (rc == MYLITE_OK) {
        rc = append_alter_table_check_column_list(&string, plan);
    }
    if (rc == MYLITE_OK) {
        rc = dynamic_string_append(&string, " FROM ");
    }
    if (rc == MYLITE_OK) {
        rc = dynamic_string_append_quoted_identifier(&string, plan->table.physical_name);
    }
    if (rc == MYLITE_OK) {
        *out_sql = dynamic_string_take(&string);
        if (*out_sql == NULL) {
            rc = MYLITE_NOMEM;
        }
    }

    dynamic_string_deinit(&string);
    return rc;
}

static int append_alter_table_check_column_list(
    struct dynamic_string *string,
    const struct planned_alter_table_check_constraint *plan
) {
    int rc = MYLITE_OK;

    for (size_t column_index = 0U; rc == MYLITE_OK && column_index < plan->rebuild.column_count;
         ++column_index) {
        if (column_index != 0U) {
            rc = dynamic_string_append(string, ", ");
        }
        if (rc == MYLITE_OK) {
            rc = dynamic_string_append_quoted_identifier(
                string,
                plan->rebuild.columns[column_index].name
            );
        }
    }

    return rc;
}

static int rename_table_from_plan_with_policy(
    struct mylite_db *database,
    const struct planned_rename_table *plan,
    bool allow_same_object_noop,
    const char *unsupported_object_message
) {
    struct mylite_catalog_mutation mutation = {.active = false, .next_generation = 0U};
    struct mylite_catalog_table_descriptor source = {0};
    int rc = MYLITE_OK;

    if (allow_same_object_noop) {
        rc = mylite_catalog_read_table_by_name(
            database,
            plan->source.schema.schema_id,
            plan->source.table_name,
            &source
        );
        if (rc != MYLITE_OK) {
            set_table_does_not_exist_error(
                database,
                plan->source.schema.name,
                plan->source.table_name
            );
            return MYLITE_ERROR;
        }
        if (source.kind != MYLITE_CATALOG_TABLE_KIND_BASE) {
            set_unsupported_error(database, unsupported_object_message);
            return MYLITE_ERROR;
        }
        if (source.schema_id == plan->target.schema.schema_id &&
            text_equals_ascii_case_insensitive(source.name, plan->target.table_name)) {
            return MYLITE_OK;
        }
    }

    rc = mylite_catalog_begin_mutation(database, &mutation);
    if (rc == MYLITE_OK) {
        rc = rename_table_pair_in_mutation(
            database,
            &mutation,
            plan,
            allow_same_object_noop,
            unsupported_object_message
        );
    }
    if (rc == MYLITE_OK) {
        rc = mylite_catalog_commit_mutation(database, &mutation);
    }
    if (rc != MYLITE_OK) {
        set_internal_error_if_clear(database, rc, "failed to rename table descriptor");
        mylite_catalog_rollback_mutation(database, &mutation);
        return rc;
    }

    return MYLITE_OK;
}

static int rename_table_pair_in_mutation(
    struct mylite_db *database,
    const struct mylite_catalog_mutation *mutation,
    const struct planned_rename_table *plan,
    bool allow_same_object_noop,
    const char *unsupported_object_message
) {
    struct mylite_catalog_table_descriptor source = {0};
    struct mylite_catalog_table_descriptor target = {0};
    bool found = false;
    int rc = mylite_catalog_read_table_by_name(
        database,
        plan->source.schema.schema_id,
        plan->source.table_name,
        &source
    );

    if (rc != MYLITE_OK) {
        set_table_does_not_exist_error(database, plan->source.schema.name, plan->source.table_name);
        return MYLITE_ERROR;
    }
    if (source.kind != MYLITE_CATALOG_TABLE_KIND_BASE) {
        set_unsupported_error(database, unsupported_object_message);
        return MYLITE_ERROR;
    }
    if (allow_same_object_noop && source.schema_id == plan->target.schema.schema_id &&
        text_equals_ascii_case_insensitive(source.name, plan->target.table_name)) {
        return MYLITE_OK;
    }

    rc = mylite_catalog_try_read_table_by_name(
        database,
        plan->target.schema.schema_id,
        plan->target.table_name,
        &target,
        &found
    );
    if (rc != MYLITE_OK) {
        set_internal_error_if_clear(database, rc, "failed to read target table descriptor");
        return rc;
    }
    if (found) {
        set_table_exists_error(database, plan->target.table_name);
        return MYLITE_ERROR;
    }
    rc = reject_rename_table_check_constraint_collisions(database, &source, plan);
    if (rc != MYLITE_OK) {
        return rc;
    }

    rc = mylite_catalog_update_table_identity_in_mutation(
        database,
        mutation,
        source.table_id,
        plan->target.schema.schema_id,
        plan->target.table_name,
        NULL
    );
    if (rc == MYLITE_OK) {
        rc = mylite_catalog_rename_generated_check_constraints_in_mutation(
            database,
            mutation,
            source.table_id,
            plan->target.table_name
        );
    }

    return rc;
}

static int reject_rename_table_check_constraint_collisions(
    struct mylite_db *database,
    const struct mylite_catalog_table_descriptor *source,
    const struct planned_rename_table *plan
) {
    struct loaded_check_constraint_info *checks = NULL;
    size_t check_count = 0U;
    char check_name[MYLITE_CATALOG_IDENTIFIER_CAPACITY];
    int rc = load_table_check_constraint_infos(database, source->table_id, &checks, &check_count);

    for (size_t index = 0U; rc == MYLITE_OK && index < check_count; ++index) {
        rc = build_renamed_check_constraint_name(
            database,
            plan,
            &checks[index].check_constraint,
            check_name,
            sizeof(check_name)
        );
        for (size_t previous = 0U; rc == MYLITE_OK && previous < index; ++previous) {
            char previous_name[MYLITE_CATALOG_IDENTIFIER_CAPACITY];

            rc = build_renamed_check_constraint_name(
                database,
                plan,
                &checks[previous].check_constraint,
                previous_name,
                sizeof(previous_name)
            );
            if (rc == MYLITE_OK && text_equals_ascii_case_insensitive(check_name, previous_name)) {
                set_duplicate_check_constraint_error(database, check_name);
                rc = MYLITE_ERROR;
            }
        }
        if (rc == MYLITE_OK) {
            rc = reject_rename_table_check_constraint_schema_collision(
                database,
                source,
                plan,
                check_name
            );
        }
    }

    loaded_check_constraint_infos_deinit(&checks, &check_count);
    return rc;
}

static int build_renamed_check_constraint_name(
    struct mylite_db *database,
    const struct planned_rename_table *plan,
    const struct mylite_catalog_check_constraint_descriptor *check_constraint,
    char *destination,
    size_t destination_size
) {
    int written = 0;

    if (!check_constraint->name_is_generated) {
        written = snprintf(destination, destination_size, "%s", check_constraint->name);
    } else {
        written = snprintf(
            destination,
            destination_size,
            "%s_chk_%" PRId64,
            plan->target.table_name,
            check_constraint->generated_ordinal
        );
    }
    if (written < 0 || (size_t)written >= destination_size) {
        set_runtime_error(database, "renamed CHECK constraint name is too long");
        return MYLITE_ERROR;
    }

    return MYLITE_OK;
}

static int reject_rename_table_check_constraint_schema_collision(
    struct mylite_db *database,
    const struct mylite_catalog_table_descriptor *source,
    const struct planned_rename_table *plan,
    const char *check_constraint_name
) {
    struct check_constraint_name_collision_context context = {
        .name = check_constraint_name,
        .excluded_table_id = source->table_id,
        .found = false,
    };
    int rc = mylite_catalog_for_each_check_constraint_in_schema(
        database,
        plan->target.schema.schema_id,
        reject_rename_table_check_constraint_schema_collision_callback,
        &context
    );

    if (rc != MYLITE_OK) {
        set_internal_error_if_clear(database, rc, "failed to read CHECK constraint descriptors");
        return rc;
    }
    if (context.found) {
        set_duplicate_check_constraint_error(database, check_constraint_name);
        return MYLITE_ERROR;
    }

    return MYLITE_OK;
}

static int reject_rename_table_check_constraint_schema_collision_callback(
    const struct mylite_catalog_check_constraint_descriptor *check_constraint,
    void *user_data
) {
    struct check_constraint_name_collision_context *context = user_data;

    if (check_constraint == NULL || context == NULL || context->name == NULL) {
        return MYLITE_MISUSE;
    }
    if (check_constraint->table_id != context->excluded_table_id &&
        text_equals_ascii_case_insensitive(check_constraint->name, context->name)) {
        context->found = true;
    }

    return MYLITE_OK;
}

static int plan_insert(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *statement,
    struct planned_insert *out_plan
) {
    const struct mylite_sql_ast_node *column_list = child_at(statement, 1U);
    const struct mylite_sql_ast_node *row_list = child_at(statement, 2U);
    size_t *target_indexes = NULL;
    size_t target_count = 0U;
    struct primary_key_info primary_key = primary_key_info_init();
    int rc = MYLITE_OK;

    *out_plan = (struct planned_insert){0};
    out_plan->ignore_errors =
        child_with_kind(statement, MYLITE_SQL_AST_INSERT_IGNORE_MODIFIER) != NULL;
    out_plan->replace_existing_rows = statement->kind == MYLITE_SQL_AST_REPLACE_VALUES_STATEMENT;
    rc = resolve_visible_writable_table_reference(
        database,
        child_at(statement, 0U),
        &out_plan->target,
        &out_plan->table
    );
    if (rc == MYLITE_OK) {
        rc = load_table_columns(
            database,
            out_plan->table.table_id,
            &out_plan->columns,
            &out_plan->column_count
        );
    }
    if (rc == MYLITE_OK) {
        rc = load_primary_key_info(
            database,
            out_plan->table.table_id,
            out_plan->columns,
            out_plan->column_count,
            &primary_key
        );
    }
    if (rc == MYLITE_OK && primary_key.has_primary_key) {
        out_plan->has_primary_key = true;
        if (primary_key.part_count == 1U) {
            out_plan->primary_key_column_index = primary_key.parts[0].column_index;
        }
    }
    if (rc == MYLITE_OK) {
        rc = load_table_index_infos(
            database,
            out_plan->table.table_id,
            out_plan->columns,
            out_plan->column_count,
            &out_plan->indexes,
            &out_plan->index_count
        );
    }
    if (rc == MYLITE_OK) {
        rc = load_insert_target_foreign_key_infos(database, out_plan);
    }
    if (rc == MYLITE_OK) {
        rc = initialize_insert_auto_increment_plan(database, out_plan);
    }
    if (rc == MYLITE_OK) {
        rc = collect_insert_target_indexes(
            database,
            column_list,
            out_plan,
            row_list,
            &target_indexes,
            &target_count
        );
    }
    if (rc == MYLITE_OK) {
        rc = check_insert_target_duplicate(
            database,
            out_plan->columns,
            target_indexes,
            target_count
        );
    }
    if (rc == MYLITE_OK) {
        rc = validate_insert_row_shapes(database, row_list, target_count);
    }
    if (rc == MYLITE_OK) {
        rc = plan_insert_rows(database, row_list, target_indexes, target_count, out_plan);
    }
    if (rc == MYLITE_OK) {
        rc = check_insert_omitted_columns(database, out_plan, target_indexes, target_count);
    }
    if (rc == MYLITE_OK) {
        rc = plan_insert_auto_increment_values(database, out_plan);
    }
    if (rc == MYLITE_OK) {
        rc = plan_insert_string_key_values(database, out_plan);
    }
    if (rc == MYLITE_OK) {
        rc = plan_insert_duplicate_update(database, statement, out_plan);
    }

    free(target_indexes);
    primary_key_info_deinit(&primary_key);
    if (rc != MYLITE_OK) {
        planned_insert_deinit(out_plan);
    }

    return rc;
}

static int plan_insert_set(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *statement,
    struct planned_insert *out_plan
) {
    const struct mylite_sql_ast_node *assignment_list = child_at(statement, 1U);
    size_t *target_indexes = NULL;
    size_t target_count = 0U;
    struct primary_key_info primary_key = primary_key_info_init();
    int rc = MYLITE_OK;

    *out_plan = (struct planned_insert){0};
    out_plan->ignore_errors =
        child_with_kind(statement, MYLITE_SQL_AST_INSERT_IGNORE_MODIFIER) != NULL;
    out_plan->replace_existing_rows = statement->kind == MYLITE_SQL_AST_REPLACE_SET_STATEMENT;
    rc = resolve_visible_writable_table_reference(
        database,
        child_at(statement, 0U),
        &out_plan->target,
        &out_plan->table
    );
    if (rc == MYLITE_OK) {
        rc = load_table_columns(
            database,
            out_plan->table.table_id,
            &out_plan->columns,
            &out_plan->column_count
        );
    }
    if (rc == MYLITE_OK) {
        rc = load_primary_key_info(
            database,
            out_plan->table.table_id,
            out_plan->columns,
            out_plan->column_count,
            &primary_key
        );
    }
    if (rc == MYLITE_OK && primary_key.has_primary_key) {
        out_plan->has_primary_key = true;
        if (primary_key.part_count == 1U) {
            out_plan->primary_key_column_index = primary_key.parts[0].column_index;
        }
    }
    if (rc == MYLITE_OK) {
        rc = load_table_index_infos(
            database,
            out_plan->table.table_id,
            out_plan->columns,
            out_plan->column_count,
            &out_plan->indexes,
            &out_plan->index_count
        );
    }
    if (rc == MYLITE_OK) {
        rc = load_insert_target_foreign_key_infos(database, out_plan);
    }
    if (rc == MYLITE_OK) {
        rc = initialize_insert_auto_increment_plan(database, out_plan);
    }
    if (rc == MYLITE_OK) {
        rc = collect_insert_set_target_indexes(
            database,
            assignment_list,
            out_plan,
            statement->kind == MYLITE_SQL_AST_REPLACE_SET_STATEMENT
                ? "REPLACE ... SET supports only unqualified assignment columns"
                : "INSERT ... SET supports only unqualified assignment columns",
            &target_indexes,
            &target_count
        );
    }
    if (rc == MYLITE_OK) {
        rc = check_insert_target_duplicate(
            database,
            out_plan->columns,
            target_indexes,
            target_count
        );
    }
    if (rc == MYLITE_OK) {
        rc = plan_insert_set_row(database, assignment_list, target_indexes, target_count, out_plan);
    }
    if (rc == MYLITE_OK) {
        rc = check_insert_omitted_columns(database, out_plan, target_indexes, target_count);
    }
    if (rc == MYLITE_OK) {
        rc = plan_insert_auto_increment_values(database, out_plan);
    }
    if (rc == MYLITE_OK) {
        rc = plan_insert_string_key_values(database, out_plan);
    }
    if (rc == MYLITE_OK) {
        rc = plan_insert_duplicate_update(database, statement, out_plan);
    }

    free(target_indexes);
    primary_key_info_deinit(&primary_key);
    if (rc != MYLITE_OK) {
        planned_insert_deinit(out_plan);
    }

    return rc;
}

static int load_insert_target_foreign_key_infos(
    struct mylite_db *database,
    struct planned_insert *plan
) {
    return load_table_foreign_key_infos(
        database,
        plan->table.table_id,
        plan->columns,
        plan->column_count,
        &plan->foreign_keys,
        &plan->foreign_key_count
    );
}

static int initialize_insert_auto_increment_plan(
    struct mylite_db *database,
    struct planned_insert *plan
) {
    size_t auto_increment_count = 0U;

    if (plan == NULL) {
        set_runtime_error(database, "invalid auto-increment insert plan");
        return MYLITE_ERROR;
    }

    plan->auto_increment_next =
        plan->table.auto_increment_next > 0 ? plan->table.auto_increment_next : 1;
    plan->auto_increment_next_after_statement = plan->auto_increment_next;
    plan->no_auto_value_on_zero =
        session_sql_mode_has(&database->session, MYLITE_SESSION_SQL_MODE_NO_AUTO_VALUE_ON_ZERO);
    for (size_t column_index = 0U; column_index < plan->column_count; ++column_index) {
        if (!column_descriptor_is_auto_increment(&plan->columns[column_index])) {
            continue;
        }
        ++auto_increment_count;
        plan->has_auto_increment = true;
        plan->auto_increment_column_index = column_index;
    }
    if (auto_increment_count == 0U) {
        return MYLITE_OK;
    }
    if (auto_increment_count > 1U || !insert_auto_increment_column_is_indexed(plan)) {
        set_unsupported_error(database, "INSERT supports only indexed AUTO_INCREMENT tables");
        return MYLITE_ERROR;
    }

    return MYLITE_OK;
}

static int initialize_insert_auto_increment_range(
    struct mylite_db *database,
    struct planned_insert *plan
) {
    if (plan == NULL) {
        set_runtime_error(database, "invalid auto-increment insert plan");
        return MYLITE_ERROR;
    }
    if (!plan->has_auto_increment) {
        return MYLITE_OK;
    }
    if (plan->auto_increment_column_index >= plan->column_count) {
        set_runtime_error(database, "invalid auto-increment column index");
        return MYLITE_ERROR;
    }

    return integer_range_for_column(
        database,
        &plan->columns[plan->auto_increment_column_index],
        "AUTO_INCREMENT supports only baseline integer columns",
        &plan->auto_increment_range
    );
}

static bool insert_auto_increment_column_is_indexed(const struct planned_insert *plan) {
    if (plan->has_primary_key &&
        plan->auto_increment_column_index == plan->primary_key_column_index) {
        return true;
    }

    for (size_t index = 0U; index < plan->index_count; ++index) {
        if (plan->indexes[index].index.kind == MYLITE_CATALOG_INDEX_KIND_PRIMARY ||
            plan->indexes[index].part_count == 0U) {
            continue;
        }
        if (plan->indexes[index].parts[0].column_index == plan->auto_increment_column_index) {
            return true;
        }
    }

    return false;
}

static int plan_insert_auto_increment_values(
    struct mylite_db *database,
    struct planned_insert *plan
) {
    struct insert_auto_increment_mode_counts mode_counts = {0};
    int64_t next_value = 0;
    int rc = MYLITE_OK;

    if (plan == NULL || !plan->has_auto_increment) {
        return MYLITE_OK;
    }

    rc = initialize_insert_auto_increment_range(database, plan);
    if (rc != MYLITE_OK) {
        return rc;
    }

    rc = count_insert_auto_increment_modes(plan, &mode_counts);
    if (rc != MYLITE_OK) {
        return rc;
    }
    if (plan->row_count > 1U && mode_counts.generated_count != 0U &&
        mode_counts.explicit_count != 0U) {
        set_unsupported_error(
            database,
            "mixed explicit and generated AUTO_INCREMENT values are not supported"
        );
        return MYLITE_ERROR;
    }

    next_value = plan->auto_increment_next;
    for (size_t row_index = 0U; row_index < plan->row_count; ++row_index) {
        rc = plan_insert_auto_increment_row_value(
            database,
            plan,
            &plan->auto_increment_range,
            row_index,
            &next_value
        );
        if (rc != MYLITE_OK) {
            return rc;
        }
    }

    plan->auto_increment_next_after_statement = next_value;
    return MYLITE_OK;
}

static int plan_insert_string_key_values(
    struct mylite_db *database,
    const struct planned_insert *plan
) {
    for (size_t index = 0U; index < plan->index_count; ++index) {
        const struct loaded_index_info *key = &plan->indexes[index];

        if (!key->index.is_unique) {
            continue;
        }
        for (size_t part_index = 0U; part_index < key->part_count; ++part_index) {
            const struct loaded_index_part *part = &key->parts[part_index];

            if (!loaded_index_part_requires_string_key_validation(part)) {
                continue;
            }
            if (part->column_index >= plan->column_count) {
                set_runtime_error(database, "invalid string key descriptor");
                return MYLITE_ERROR;
            }
            for (size_t row_index = 0U; row_index < plan->row_count; ++row_index) {
                int rc = validate_string_key_value(
                    database,
                    &plan->rows[row_index].values[part->column_index]
                );

                if (rc != MYLITE_OK) {
                    return rc;
                }
            }
        }
    }

    return MYLITE_OK;
}

static int plan_insert_duplicate_update(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *statement,
    struct planned_insert *plan
) {
    const struct mylite_sql_ast_node *clause =
        child_with_kind(statement, MYLITE_SQL_AST_INSERT_DUPLICATE_UPDATE_CLAUSE);
    const struct mylite_sql_ast_node *assignment_list = NULL;
    size_t assignment_count = 0U;
    int rc = MYLITE_OK;

    if (clause == NULL) {
        return MYLITE_OK;
    }
    if (plan->ignore_errors) {
        set_unsupported_error(
            database,
            "INSERT IGNORE ... ON DUPLICATE KEY UPDATE is not supported"
        );
        return MYLITE_ERROR;
    }

    assignment_list = child_at(clause, 0U);
    if (assignment_list == NULL ||
        assignment_list->kind != MYLITE_SQL_AST_INSERT_DUPLICATE_ASSIGNMENT_LIST) {
        set_parse_error(database, NULL);
        return MYLITE_ERROR;
    }

    assignment_count = mylite_sql_ast_node_child_count(assignment_list);
    if (assignment_count == 0U) {
        set_parse_error(database, NULL);
        return MYLITE_ERROR;
    }

    plan->duplicate_update = (struct planned_insert_duplicate_update){
        .has_clause = true,
        .assignment_count = assignment_count,
    };

    plan->duplicate_update.assignments =
        calloc(assignment_count, sizeof(*plan->duplicate_update.assignments));
    if (plan->duplicate_update.assignments == NULL) {
        set_nomem_error(database);
        return MYLITE_NOMEM;
    }

    for (size_t index = 0U; rc == MYLITE_OK && index < assignment_count; ++index) {
        rc = plan_insert_duplicate_assignment(
            database,
            child_at(assignment_list, index),
            plan,
            index
        );
    }
    if (rc == MYLITE_OK) {
        rc = plan_insert_duplicate_update_key(database, plan);
    }

    return rc;
}

static int plan_insert_duplicate_assignment(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *assignment,
    struct planned_insert *plan,
    size_t assignment_index
) {
    struct planned_insert_duplicate_update_assignment *duplicate_assignment = NULL;
    const struct mylite_sql_ast_node *target = NULL;
    const struct mylite_sql_ast_node *value = NULL;
    char column_name[MYLITE_CATALOG_IDENTIFIER_CAPACITY];
    int rc = MYLITE_OK;

    if (plan == NULL || assignment_index >= plan->duplicate_update.assignment_count ||
        plan->duplicate_update.assignments == NULL) {
        set_runtime_error(database, "invalid insert duplicate assignment plan");
        return MYLITE_ERROR;
    }
    duplicate_assignment = &plan->duplicate_update.assignments[assignment_index];
    duplicate_assignment->value_kind = PLANNED_INSERT_DUPLICATE_UPDATE_VALUE_LITERAL;

    if (assignment == NULL || assignment->kind != MYLITE_SQL_AST_INSERT_DUPLICATE_ASSIGNMENT) {
        set_parse_error(database, NULL);
        return MYLITE_ERROR;
    }

    target = child_at(assignment, 0U);
    if (target == NULL || target->kind != MYLITE_SQL_AST_IDENTIFIER) {
        set_unsupported_error(
            database,
            "INSERT ... ON DUPLICATE KEY UPDATE supports only unqualified assignment columns"
        );
        return MYLITE_ERROR;
    }
    rc = copy_identifier_text(target, column_name, sizeof(column_name), database);
    if (rc == MYLITE_OK) {
        rc = find_column_index(
            plan->columns,
            plan->column_count,
            column_name,
            &duplicate_assignment->assignment_column_index
        );
        if (rc != MYLITE_OK) {
            set_unknown_column_error(database, column_name);
            return MYLITE_ERROR;
        }
    }
    for (size_t index = 0U; rc == MYLITE_OK && index < assignment_index; ++index) {
        if (plan->duplicate_update.assignments[index].assignment_column_index ==
            duplicate_assignment->assignment_column_index) {
            set_unsupported_error(
                database,
                "INSERT ... ON DUPLICATE KEY UPDATE does not support duplicate assignment targets"
            );
            return MYLITE_ERROR;
        }
    }

    value = child_at(assignment, 1U);
    if (rc == MYLITE_OK && value == NULL) {
        set_parse_error(database, NULL);
        rc = MYLITE_ERROR;
    }
    if (rc == MYLITE_OK && value->kind == MYLITE_SQL_AST_INSERT_VALUES_REFERENCE) {
        rc = plan_insert_duplicate_values_reference(database, value, plan, duplicate_assignment);
    } else if (rc == MYLITE_OK) {
        duplicate_assignment->assignment_value_node = value;
        duplicate_assignment->value_kind = PLANNED_INSERT_DUPLICATE_UPDATE_VALUE_LITERAL;
    }
    const struct mylite_sql_ast_node *default_value =
        unwrap_parenthesized_expression(duplicate_assignment->assignment_value_node);

    if (rc == MYLITE_OK && default_value != NULL &&
        default_value->kind == MYLITE_SQL_AST_DEFAULT_FUNCTION) {
        struct select_source_context source_context = {.source = &plan->target};

        rc = validate_default_function_source_value(
            database,
            default_value,
            &source_context,
            plan->columns,
            plan->column_count
        );
    }

    return rc;
}

static int plan_insert_duplicate_values_reference(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *value_node,
    struct planned_insert *plan,
    struct planned_insert_duplicate_update_assignment *duplicate_assignment
) {
    const struct mylite_sql_ast_node *column = child_at(value_node, 0U);
    char column_name[MYLITE_CATALOG_IDENTIFIER_CAPACITY];
    int rc = MYLITE_OK;

    if (column == NULL || column->kind != MYLITE_SQL_AST_IDENTIFIER) {
        set_unsupported_error(
            database,
            "VALUES() in ON DUPLICATE KEY UPDATE supports only unqualified columns"
        );
        return MYLITE_ERROR;
    }
    rc = copy_identifier_text(column, column_name, sizeof(column_name), database);
    if (rc == MYLITE_OK) {
        rc = find_column_index(
            plan->columns,
            plan->column_count,
            column_name,
            &duplicate_assignment->values_column_index
        );
        if (rc != MYLITE_OK) {
            set_unknown_column_error(database, column_name);
            return MYLITE_ERROR;
        }
    }
    if (rc == MYLITE_OK && duplicate_assignment->values_column_index !=
                               duplicate_assignment->assignment_column_index) {
        set_unsupported_error(
            database,
            "VALUES() in ON DUPLICATE KEY UPDATE supports only the assignment column"
        );
        return MYLITE_ERROR;
    }
    if (rc == MYLITE_OK && !insert_select_source_target_types_are_compatible(
                               &plan->columns[duplicate_assignment->values_column_index],
                               &plan->columns[duplicate_assignment->assignment_column_index]
                           )) {
        set_unsupported_error(
            database,
            "INSERT ... ON DUPLICATE KEY UPDATE does not support implicit VALUES() conversion"
        );
        return MYLITE_ERROR;
    }

    duplicate_assignment->assignment_value_node = value_node;
    duplicate_assignment->value_kind = PLANNED_INSERT_DUPLICATE_UPDATE_VALUE_VALUES_REFERENCE;
    return rc;
}

static int plan_insert_duplicate_update_key(
    struct mylite_db *database,
    struct planned_insert *plan
) {
    for (size_t index = 0U; index < plan->index_count; ++index) {
        const struct loaded_index_info *candidate = &plan->indexes[index];

        if (!candidate->index.is_unique) {
            continue;
        }
        if (candidate->part_count == 0U) {
            set_unsupported_error(
                database,
                "INSERT ... ON DUPLICATE KEY UPDATE supports only descriptor key parts"
            );
            return MYLITE_ERROR;
        }
        if (!plan->duplicate_update.has_key) {
            plan->duplicate_update.has_key = true;
            plan->duplicate_update.key_index = index;
        }
    }
    if (insert_duplicate_assignment_targets_auto_increment(plan)) {
        set_unsupported_error(
            database,
            "INSERT ... ON DUPLICATE KEY UPDATE does not support auto-increment assignments"
        );
        return MYLITE_ERROR;
    }
    if (insert_duplicate_assignment_targets_key(plan)) {
        return reject_insert_duplicate_parent_foreign_key_assignments(database, plan);
    }

    return MYLITE_OK;
}

static int reject_insert_duplicate_parent_foreign_key_assignments(
    struct mylite_db *database,
    const struct planned_insert *plan
) {
    struct loaded_foreign_key_info *foreign_keys = NULL;
    size_t foreign_key_count = 0U;
    int rc = load_parent_foreign_key_infos(
        database,
        plan->table.table_id,
        &foreign_keys,
        &foreign_key_count
    );

    for (size_t index = 0U; rc == MYLITE_OK && index < foreign_key_count; ++index) {
        const struct loaded_foreign_key_info *foreign_key = &foreign_keys[index];

        for (size_t part_index = 0U; part_index < foreign_key->part_count; ++part_index) {
            if (insert_duplicate_assignment_targets_column_id(
                    plan,
                    foreign_key->parts[part_index].parent_column.column_id
                )) {
                set_unsupported_error(
                    database,
                    "INSERT ... ON DUPLICATE KEY UPDATE does not support parent foreign-key "
                    "key assignments"
                );
                rc = MYLITE_ERROR;
                break;
            }
        }
    }

    loaded_foreign_key_infos_deinit(&foreign_keys, &foreign_key_count);
    return rc;
}

static bool insert_duplicate_assignment_targets_key(const struct planned_insert *plan) {
    if (plan == NULL) {
        return false;
    }

    for (size_t index = 0U; index < plan->index_count; ++index) {
        const struct loaded_index_info *key = &plan->indexes[index];

        if (!key->index.is_unique) {
            continue;
        }
        for (size_t part_index = 0U; part_index < key->part_count; ++part_index) {
            for (size_t assignment_index = 0U;
                 assignment_index < plan->duplicate_update.assignment_count;
                 ++assignment_index) {
                if (key->parts[part_index].column_index ==
                    plan->duplicate_update.assignments[assignment_index].assignment_column_index) {
                    return true;
                }
            }
        }
    }

    return false;
}

static bool insert_duplicate_assignment_targets_auto_increment(const struct planned_insert *plan) {
    if (plan == NULL || !plan->has_auto_increment) {
        return false;
    }

    for (size_t index = 0U; index < plan->duplicate_update.assignment_count; ++index) {
        if (plan->duplicate_update.assignments[index].assignment_column_index ==
            plan->auto_increment_column_index) {
            return true;
        }
    }

    return false;
}

static bool insert_duplicate_assignment_targets_column_id(
    const struct planned_insert *plan,
    int64_t column_id
) {
    if (plan == NULL || column_id <= 0) {
        return false;
    }

    for (size_t index = 0U; index < plan->duplicate_update.assignment_count; ++index) {
        size_t column_index = plan->duplicate_update.assignments[index].assignment_column_index;

        if (column_index < plan->column_count &&
            plan->columns[column_index].column_id == column_id) {
            return true;
        }
    }

    return false;
}

static int count_insert_auto_increment_modes(
    const struct planned_insert *plan,
    struct insert_auto_increment_mode_counts *out_counts
) {
    int rc = MYLITE_OK;

    *out_counts = (struct insert_auto_increment_mode_counts){0};
    for (size_t row_index = 0U; row_index < plan->row_count; ++row_index) {
        bool generated = false;

        rc = generated_auto_increment_value_for_row(plan, row_index, &generated);
        if (rc != MYLITE_OK) {
            return rc;
        }
        if (generated) {
            ++out_counts->generated_count;
        } else {
            ++out_counts->explicit_count;
        }
    }

    return MYLITE_OK;
}

static int plan_insert_auto_increment_row_value(
    struct mylite_db *database,
    struct planned_insert *plan,
    const struct integer_column_range *range,
    size_t row_index,
    int64_t *next_value
) {
    struct planned_value *value = &plan->rows[row_index].values[plan->auto_increment_column_index];
    bool generated = false;
    int rc = generated_auto_increment_value_for_row(plan, row_index, &generated);

    if (rc != MYLITE_OK) {
        return rc;
    }
    if (generated) {
        int64_t generated_value = 0;

        rc = generated_auto_increment_value_for_lower_bound(
            database,
            *next_value,
            range,
            &generated_value
        );
        if (rc != MYLITE_OK) {
            return rc;
        }
        if (generated_value <= 0 || (uint64_t)generated_value > range->positive_max) {
            set_failed_read_auto_increment_error(database);
            return MYLITE_ERROR;
        }
        rc = assign_generated_auto_increment_value(database, plan, row_index, generated_value);
        if (rc == MYLITE_OK) {
            plan->rows[row_index].generated_auto_increment = true;
        }
        if (rc == MYLITE_OK && !plan->generated_auto_increment) {
            plan->first_generated_auto_increment = generated_value;
            plan->generated_auto_increment = true;
        }
        if (rc == MYLITE_OK) {
            rc = next_auto_increment_after_generated_value(
                database,
                generated_value,
                range,
                next_value
            );
        }
    } else if (!value->is_text && value->integer > 0) {
        rc = next_auto_increment_after_explicit_insert_value(
            *next_value,
            value->integer,
            range,
            next_value
        );
    }
    if (rc != MYLITE_OK) {
        set_unsupported_error(database, "AUTO_INCREMENT counter is out of range");
        return MYLITE_ERROR;
    }

    return MYLITE_OK;
}

static int generated_auto_increment_value_for_row(
    const struct planned_insert *plan,
    size_t row_index,
    bool *out_generated
) {
    const struct planned_value *value = NULL;

    if (plan == NULL || out_generated == NULL || row_index >= plan->row_count ||
        plan->auto_increment_column_index >= plan->column_count ||
        plan->rows[row_index].values == NULL) {
        return MYLITE_ERROR;
    }

    value = &plan->rows[row_index].values[plan->auto_increment_column_index];
    *out_generated = (value->is_null || (!plan->no_auto_value_on_zero && !value->is_text &&
                                         value->integer == 0)) != 0;
    return MYLITE_OK;
}

static int assign_generated_auto_increment_value(
    struct mylite_db *database,
    struct planned_insert *plan,
    size_t row_index,
    int64_t generated_value
) {
    struct planned_value *value = NULL;

    if (plan == NULL || row_index >= plan->row_count ||
        plan->auto_increment_column_index >= plan->column_count ||
        plan->rows[row_index].values == NULL || generated_value <= 0) {
        set_runtime_error(database, "invalid generated auto-increment value");
        return MYLITE_ERROR;
    }

    value = &plan->rows[row_index].values[plan->auto_increment_column_index];
    planned_value_deinit(value);
    *value = (struct planned_value){
        .is_null = false,
        .is_text = false,
        .integer = generated_value,
    };
    return MYLITE_OK;
}

static int generated_auto_increment_value_for_lower_bound(
    struct mylite_db *database,
    int64_t lower_bound,
    const struct integer_column_range *range,
    int64_t *out_value
) {
    uint64_t increment = 1U;
    uint64_t offset = 1U;
    uint64_t candidate = 0U;

    if (out_value == NULL || range == NULL || lower_bound <= 0) {
        return MYLITE_ERROR;
    }
    *out_value = 0;
    increment = database->session.auto_increment_increment;
    offset = database->session.auto_increment_offset;
    if (offset > increment) {
        set_unsupported_error(
            database,
            "AUTO_INCREMENT allocation with offset greater than increment is not supported"
        );
        return MYLITE_ERROR;
    }

    if ((uint64_t)lower_bound <= offset) {
        candidate = offset;
    } else {
        uint64_t delta = (uint64_t)lower_bound - offset;
        uint64_t steps = delta / increment;

        if (delta % increment != 0U) {
            ++steps;
        }
        if (steps > (UINT64_MAX - offset) / increment) {
            return MYLITE_ERROR;
        }
        candidate = offset + (steps * increment);
    }
    if (candidate > (uint64_t)INT64_MAX) {
        return MYLITE_ERROR;
    }

    *out_value = (int64_t)candidate;
    return MYLITE_OK;
}

static int next_auto_increment_after_generated_value(
    const struct mylite_db *database,
    int64_t value,
    const struct integer_column_range *range,
    int64_t *out_next
) {
    uint64_t increment = 1U;

    if (out_next == NULL || database == NULL || range == NULL || value <= 0 ||
        (uint64_t)value > range->positive_max) {
        return MYLITE_ERROR;
    }
    if ((uint64_t)value == range->positive_max) {
        *out_next = value;
        return MYLITE_OK;
    }

    increment = database->session.auto_increment_increment;
    if (range->positive_max - (uint64_t)value < increment) {
        if (range->positive_max > (uint64_t)INT64_MAX) {
            return MYLITE_ERROR;
        }
        *out_next = (int64_t)range->positive_max;
        return MYLITE_OK;
    }
    *out_next = value + (int64_t)increment;
    return MYLITE_OK;
}

static int next_auto_increment_after_explicit_insert_value(
    int64_t current_next,
    int64_t value,
    const struct integer_column_range *range,
    int64_t *out_next
) {
    if (out_next == NULL || range == NULL || current_next <= 0 || value <= 0) {
        return MYLITE_ERROR;
    }
    *out_next = current_next;
    if (value < current_next) {
        return MYLITE_OK;
    }
    if ((uint64_t)value > range->positive_max) {
        return MYLITE_ERROR;
    }
    if ((uint64_t)value == range->positive_max) {
        *out_next = value;
        return MYLITE_OK;
    }
    *out_next = value + 1;
    return MYLITE_OK;
}

static int next_auto_increment_after_update_value(
    struct mylite_db *database,
    int64_t current_next,
    int64_t value,
    const struct integer_column_range *range,
    int64_t *out_next
) {
    int64_t lower_bound = 0;

    if (out_next == NULL || range == NULL || current_next <= 0 || value <= 0) {
        return MYLITE_ERROR;
    }
    *out_next = current_next;
    if (value < current_next) {
        return MYLITE_OK;
    }
    if ((uint64_t)value > range->positive_max) {
        return MYLITE_ERROR;
    }
    if ((uint64_t)value == range->positive_max) {
        *out_next = value;
        return MYLITE_OK;
    }
    lower_bound = value + 1;
    return generated_auto_increment_value_for_lower_bound(database, lower_bound, range, out_next);
}

static void planned_insert_deinit(struct planned_insert *plan) {
    if (plan == NULL) {
        return;
    }

    if (plan->rows != NULL) {
        for (size_t row_index = 0U; row_index < plan->row_count; ++row_index) {
            for (size_t column_index = 0U;
                 column_index < plan->column_count && plan->rows[row_index].values != NULL;
                 ++column_index) {
                planned_value_deinit(&plan->rows[row_index].values[column_index]);
            }
            free(plan->rows[row_index].values);
        }
    }
    free(plan->rows);
    free(plan->duplicate_update.assignments);
    loaded_index_infos_deinit(&plan->indexes, &plan->index_count);
    loaded_foreign_key_infos_deinit(&plan->foreign_keys, &plan->foreign_key_count);
    free(plan->columns);
    *plan = (struct planned_insert){0};
}

static void planned_value_deinit(struct planned_value *value) {
    if (value == NULL) {
        return;
    }

    free(value->text);
    *value = (struct planned_value){
        .is_null = false,
        .is_text = false,
        .integer = 0,
        .text = NULL,
        .text_length = 0U,
    };
}

static int execute_insert_from_plan(
    struct mylite_db *database,
    const struct planned_insert *plan,
    mylite_result *result
) {
    sqlite3_stmt *statement = NULL;
    char *sql = NULL;
    struct insert_execution_counters counters = {0};
    struct mylite_statement_transaction transaction = {0};
    int rc = build_insert_sql(plan, &sql);

    if (plan->has_auto_increment) {
        counters.auto_increment_next_after_rows = plan->auto_increment_next;
    }
    if (rc == MYLITE_OK) {
        rc = begin_statement_transaction(database, &transaction);
    }
    if (rc == MYLITE_OK) {
        rc = prepare_sqlite_statement(database, sql, &statement);
    }
    if (rc == MYLITE_OK) {
        rc = execute_insert_plan_rows(database, statement, plan, &counters);
    }
    rc = finalize_sqlite_statement(statement, rc);
    statement = NULL;
    if (rc == MYLITE_OK && plan->has_auto_increment &&
        counters.auto_increment_next_after_rows != plan->auto_increment_next) {
        rc = update_table_auto_increment_next(
            database,
            &plan->table,
            counters.auto_increment_next_after_rows
        );
    }
    if (rc == MYLITE_OK) {
        rc = touch_persistent_table_updated_time(
            database,
            &plan->table,
            counters.affected_rows,
            false
        );
    }
    if (rc == MYLITE_OK) {
        rc = validate_child_foreign_keys_after_write(database, plan->table.table_id);
    }
    if (rc == MYLITE_OK) {
        rc = commit_statement_transaction(database, &transaction);
    }
    if (rc != MYLITE_OK) {
        rollback_statement_transaction(database, &transaction);
    }
    free(sql);

    if (rc != MYLITE_OK) {
        if (rc == MYLITE_NOMEM) {
            set_nomem_error(database);
            return rc;
        }
        if (mylite_diagnostics_errcode(mylite_connection_diagnostics(database)) != MYLITE_OK) {
            return rc;
        }
        set_physical_sqlite_row_error(database);
        return MYLITE_ERROR;
    }

    mylite_result_set_affected_rows(result, counters.affected_rows);
    if (counters.inserted_generated_auto_increment) {
        database->session.last_insert_id =
            (uint64_t)counters.first_inserted_generated_auto_increment;
    }

    return MYLITE_OK;
}

static int execute_insert_plan_rows(
    struct mylite_db *database,
    sqlite3_stmt *statement,
    const struct planned_insert *plan,
    struct insert_execution_counters *counters
) {
    int rc = MYLITE_OK;

    for (size_t row_index = 0U; rc == MYLITE_OK && row_index < plan->row_count; ++row_index) {
        bool skip_row = false;

        if (plan->ignore_errors && plan->foreign_key_count != 0U) {
            rc = validate_insert_ignore_row_foreign_keys(database, plan, row_index, &skip_row);
        }
        if (rc == MYLITE_OK && skip_row) {
            continue;
        }
        if (rc == MYLITE_OK) {
            rc = execute_insert_plan_row_with_retries(
                database,
                statement,
                plan,
                row_index,
                counters
            );
        }
    }

    return rc;
}

static int execute_insert_plan_row_with_retries(
    struct mylite_db *database,
    sqlite3_stmt *statement,
    const struct planned_insert *plan,
    size_t row_index,
    struct insert_execution_counters *counters
) {
    size_t replace_attempt_count = 0U;
    bool row_complete = false;
    int rc = MYLITE_OK;

    while (rc == MYLITE_OK && !row_complete) {
        int sqlite_step_rc = SQLITE_OK;

        rc = execute_insert_plan_row(statement, plan, row_index, &sqlite_step_rc);
        if (rc == MYLITE_OK) {
            row_complete = true;
            rc = finish_successful_insert_plan_row(database, plan, row_index, counters);
        } else if (sqlite_status_is_constraint(sqlite_step_rc)) {
            rc = handle_insert_plan_constraint(
                database,
                sqlite_step_rc,
                statement,
                plan,
                row_index,
                &replace_attempt_count,
                counters,
                &row_complete
            );
        }
    }

    return rc;
}

static int finish_successful_insert_plan_row(
    struct mylite_db *database,
    const struct planned_insert *plan,
    size_t row_index,
    struct insert_execution_counters *counters
) {
    ++counters->affected_rows;
    record_inserted_generated_auto_increment(plan, row_index, counters);
    if (!plan->has_auto_increment) {
        return MYLITE_OK;
    }

    return advance_auto_increment_after_insert_row(
        database,
        plan,
        row_index,
        &counters->auto_increment_next_after_rows
    );
}

static int handle_insert_plan_constraint(
    struct mylite_db *database,
    int sqlite_step_rc,
    sqlite3_stmt *statement,
    const struct planned_insert *plan,
    size_t row_index,
    size_t *replace_attempt_count,
    struct insert_execution_counters *counters,
    bool *out_row_complete
) {
    int rc = MYLITE_OK;

    *out_row_complete = false;
    if (sqlite_status_is_constraint(sqlite_step_rc)) {
        bool was_check_violation = false;

        rc = handle_check_constraint_violation(
            database,
            plan->table.table_id,
            plan->ignore_errors,
            &was_check_violation
        );
        if (rc != MYLITE_OK || was_check_violation) {
            if (rc == MYLITE_OK && plan->ignore_errors) {
                rc = reset_insert_statement_after_constraint(statement);
                *out_row_complete = rc == MYLITE_OK;
            }
            return rc;
        }
    }
    if (plan->duplicate_update.has_clause) {
        rc = handle_insert_duplicate_key_update(
            database,
            sqlite_step_rc,
            statement,
            plan,
            row_index,
            counters
        );
        *out_row_complete = rc == MYLITE_OK;
        if (rc == MYLITE_OK && plan->has_auto_increment) {
            rc = advance_auto_increment_after_duplicate_attempt(
                database,
                plan,
                row_index,
                &counters->auto_increment_next_after_rows
            );
        }
        return rc;
    }
    if (plan->replace_existing_rows) {
        return handle_replace_insert_constraint(
            database,
            sqlite_step_rc,
            statement,
            plan,
            row_index,
            replace_attempt_count,
            counters
        );
    }

    rc = handle_insert_unique_key_conflict(database, sqlite_step_rc, statement, plan, row_index);
    *out_row_complete = rc == MYLITE_OK;
    return rc;
}

static int handle_replace_insert_constraint(
    struct mylite_db *database,
    int sqlite_step_rc,
    sqlite3_stmt *statement,
    const struct planned_insert *plan,
    size_t row_index,
    size_t *replace_attempt_count,
    struct insert_execution_counters *counters
) {
    int rc = MYLITE_OK;

    if (*replace_attempt_count >= plan->index_count) {
        rc = reset_insert_statement_after_constraint(statement);
        if (rc == MYLITE_OK) {
            set_runtime_error(database, "REPLACE conflict retry limit exceeded");
            rc = MYLITE_ERROR;
        }
        return rc;
    }

    ++(*replace_attempt_count);
    return handle_replace_unique_key_conflict(
        database,
        sqlite_step_rc,
        statement,
        plan,
        row_index,
        counters
    );
}

static int validate_insert_ignore_row_foreign_keys(
    struct mylite_db *database,
    const struct planned_insert *plan,
    size_t row_index,
    bool *out_skip_row
) {
    int rc = MYLITE_OK;

    *out_skip_row = false;
    if (!foreign_key_checks_system_variable_value(database, false)) {
        return MYLITE_OK;
    }
    for (size_t index = 0U; rc == MYLITE_OK && index < plan->foreign_key_count; ++index) {
        bool violates = false;

        rc = validate_insert_ignore_row_foreign_key(
            database,
            plan,
            &plan->foreign_keys[index],
            row_index,
            &violates
        );
        if (rc == MYLITE_OK && violates) {
            rc = append_no_referenced_row_warning(database);
            *out_skip_row = rc == MYLITE_OK;
            break;
        }
    }

    return rc;
}

static int validate_insert_ignore_row_foreign_key(
    struct mylite_db *database,
    const struct planned_insert *plan,
    const struct loaded_foreign_key_info *foreign_key,
    size_t row_index,
    bool *out_violates
) {
    struct loaded_index_part *parent_parts = NULL;
    struct planned_value *parent_values = NULL;
    struct loaded_index_info parent_index = {0};
    bool parent_exists = false;
    int rc = MYLITE_OK;

    *out_violates = false;
    if (foreign_key->part_count == 0U || row_index >= plan->row_count) {
        set_runtime_error(database, "invalid foreign-key insert descriptor");
        return MYLITE_ERROR;
    }
    if (foreign_key->part_count > SIZE_MAX / sizeof(*parent_parts) ||
        foreign_key->part_count > SIZE_MAX / sizeof(*parent_values)) {
        set_nomem_error(database);
        return MYLITE_NOMEM;
    }

    parent_parts = calloc(foreign_key->part_count, sizeof(*parent_parts));
    parent_values = calloc(foreign_key->part_count, sizeof(*parent_values));
    if (parent_parts == NULL || parent_values == NULL) {
        free(parent_parts);
        free(parent_values);
        set_nomem_error(database);
        return MYLITE_NOMEM;
    }
    for (size_t part_index = 0U; rc == MYLITE_OK && part_index < foreign_key->part_count;
         ++part_index) {
        const struct loaded_foreign_key_part *foreign_key_part = &foreign_key->parts[part_index];
        const struct planned_value *child_value = NULL;
        size_t child_column_index = 0U;

        rc = find_column_index_by_id(
            plan->columns,
            plan->column_count,
            &child_column_index,
            foreign_key_part->foreign_key_column.child_column_id
        );
        if (rc != MYLITE_OK) {
            set_runtime_error(database, "foreign-key child column descriptor is stale");
            rc = MYLITE_ERROR;
            break;
        }

        child_value = &plan->rows[row_index].values[child_column_index];
        if (child_value->is_null) {
            free(parent_parts);
            free(parent_values);
            return MYLITE_OK;
        }
        parent_parts[part_index] = (struct loaded_index_part){
            .index_column =
                {
                    .column_id = foreign_key_part->foreign_key_column.parent_column_id,
                    .ordinal_position = (int64_t)part_index + 1,
                    .has_prefix_length = false,
                    .prefix_length = 0,
                    .sort_direction = MYLITE_CATALOG_INDEX_SORT_DIRECTION_ASC,
                },
            .column = foreign_key_part->parent_column,
            .column_index = part_index,
        };
        parent_values[part_index] = *child_value;
    }
    parent_index = (struct loaded_index_info){
        .index = foreign_key->parent_index,
        .parts = parent_parts,
        .part_count = foreign_key->part_count,
    };

    if (rc == MYLITE_OK) {
        rc = unique_key_tuple_exists(
            database,
            foreign_key->parent_table.physical_name,
            &parent_index,
            parent_values,
            foreign_key->part_count,
            &parent_exists
        );
    }
    free(parent_parts);
    free(parent_values);
    if (rc == MYLITE_OK && !parent_exists) {
        *out_violates = true;
    }
    return rc;
}

static int execute_insert_plan_row(
    sqlite3_stmt *statement,
    const struct planned_insert *plan,
    size_t row_index,
    int *out_sqlite_step_rc
) {
    int rc = bind_insert_row(statement, plan, row_index);

    if (rc == MYLITE_OK) {
        rc = step_insert_row(statement, out_sqlite_step_rc);
    }

    return rc;
}

static int advance_auto_increment_after_insert_row(
    const struct mylite_db *database,
    const struct planned_insert *plan,
    size_t row_index,
    int64_t *auto_increment_next_after_rows
) {
    const struct planned_value *auto_value =
        &plan->rows[row_index].values[plan->auto_increment_column_index];

    if (auto_value->is_null || auto_value->is_text || auto_value->integer <= 0) {
        return MYLITE_OK;
    }

    if (plan->rows[row_index].generated_auto_increment) {
        return next_auto_increment_after_generated_value(
            database,
            auto_value->integer,
            &plan->auto_increment_range,
            auto_increment_next_after_rows
        );
    }

    return next_auto_increment_after_explicit_insert_value(
        *auto_increment_next_after_rows,
        auto_value->integer,
        &plan->auto_increment_range,
        auto_increment_next_after_rows
    );
}

static int advance_auto_increment_after_duplicate_attempt(
    const struct mylite_db *database,
    const struct planned_insert *plan,
    size_t row_index,
    int64_t *auto_increment_next_after_rows
) {
    if (row_index >= plan->row_count || !plan->rows[row_index].generated_auto_increment) {
        return MYLITE_OK;
    }

    return advance_auto_increment_after_insert_row(
        database,
        plan,
        row_index,
        auto_increment_next_after_rows
    );
}

static void record_inserted_generated_auto_increment(
    const struct planned_insert *plan,
    size_t row_index,
    struct insert_execution_counters *counters
) {
    const struct planned_value *auto_value = NULL;

    if (!plan->has_auto_increment || row_index >= plan->row_count ||
        !plan->rows[row_index].generated_auto_increment ||
        counters->inserted_generated_auto_increment) {
        return;
    }

    auto_value = &plan->rows[row_index].values[plan->auto_increment_column_index];
    counters->first_inserted_generated_auto_increment = auto_value->integer;
    counters->inserted_generated_auto_increment = true;
}

static int handle_insert_unique_key_conflict(
    struct mylite_db *database,
    int sqlite_step_rc,
    sqlite3_stmt *statement,
    const struct planned_insert *plan,
    size_t row_index
) {
    char value_text[MYLITE_DIAGNOSTIC_MESSAGE_CAPACITY] = "";
    const struct loaded_index_info *conflicting_index = NULL;
    int rc = find_insert_unique_key_conflict(
        database,
        sqlite_step_rc,
        plan,
        row_index,
        &conflicting_index,
        value_text,
        sizeof(value_text)
    );

    if (rc != MYLITE_OK) {
        return rc;
    }
    if (conflicting_index == NULL) {
        return mylite_sqlite_status_to_mylite(sqlite_step_rc);
    }
    if (!plan->ignore_errors) {
        set_duplicate_key_error(
            database,
            plan->target.table_name,
            conflicting_index->index.name,
            value_text
        );
        return MYLITE_ERROR;
    }

    rc = append_duplicate_key_warning(
        database,
        plan->target.table_name,
        conflicting_index->index.name,
        value_text
    );
    if (rc == MYLITE_OK) {
        int reset_rc = sqlite3_reset(statement);

        if (reset_rc != SQLITE_OK && !sqlite_status_is_constraint(reset_rc)) {
            rc = mylite_sqlite_status_to_mylite(reset_rc);
        }
    }

    return rc;
}

static int handle_insert_duplicate_key_update(
    struct mylite_db *database,
    int sqlite_step_rc,
    sqlite3_stmt *insert_statement,
    const struct planned_insert *plan,
    size_t row_index,
    struct insert_execution_counters *counters
) {
    char value_text[MYLITE_DIAGNOSTIC_MESSAGE_CAPACITY] = "";
    const struct loaded_index_info *conflicting_index = NULL;
    int rc = find_insert_unique_key_conflict(
        database,
        sqlite_step_rc,
        plan,
        row_index,
        &conflicting_index,
        value_text,
        sizeof(value_text)
    );

    if (rc != MYLITE_OK) {
        return rc;
    }
    if (conflicting_index == NULL) {
        return mylite_sqlite_status_to_mylite(sqlite_step_rc);
    }

    rc = reset_insert_statement_after_constraint(insert_statement);
    if (rc == MYLITE_OK) {
        rc = apply_insert_duplicate_key_update(
            database,
            plan,
            row_index,
            conflicting_index,
            counters
        );
    }

    return rc;
}

static int handle_replace_unique_key_conflict(
    struct mylite_db *database,
    int sqlite_step_rc,
    sqlite3_stmt *insert_statement,
    const struct planned_insert *plan,
    size_t row_index,
    struct insert_execution_counters *counters
) {
    char value_text[MYLITE_DIAGNOSTIC_MESSAGE_CAPACITY] = "";
    sqlite3_int64 deleted_rows = 0;
    const struct loaded_index_info *conflicting_index = NULL;
    bool exact_replacement = false;
    int rc = find_insert_unique_key_conflict(
        database,
        sqlite_step_rc,
        plan,
        row_index,
        &conflicting_index,
        value_text,
        sizeof(value_text)
    );

    if (rc != MYLITE_OK) {
        return rc;
    }
    if (conflicting_index == NULL) {
        return mylite_sqlite_status_to_mylite(sqlite_step_rc);
    }

    rc = reset_insert_statement_after_constraint(insert_statement);
    if (rc == MYLITE_OK) {
        rc = replace_conflicting_row_matches_plan(
            database,
            plan,
            row_index,
            conflicting_index,
            &exact_replacement
        );
    }
    if (rc == MYLITE_OK) {
        rc = delete_replace_conflicting_row(
            database,
            plan,
            conflicting_index,
            row_index,
            &deleted_rows
        );
    }
    if (rc == MYLITE_OK) {
        rc = validate_parent_foreign_keys_after_write(database, plan->table.table_id);
    }
    if (rc == MYLITE_OK && !exact_replacement) {
        counters->affected_rows += (int64_t)deleted_rows;
    }

    return rc;
}

static int replace_conflicting_row_matches_plan(
    struct mylite_db *database,
    const struct planned_insert *plan,
    size_t row_index,
    const struct loaded_index_info *conflicting_index,
    bool *out_matches
) {
    sqlite3_stmt *statement = NULL;
    char *sql = NULL;
    int sqlite_rc = SQLITE_OK;
    int rc = MYLITE_OK;

    *out_matches = false;
    rc = build_replace_conflicting_row_select_sql(plan, conflicting_index, &sql);
    if (rc == MYLITE_OK) {
        rc = prepare_sqlite_statement(database, sql, &statement);
    }
    if (rc == MYLITE_OK) {
        rc = bind_unique_key_tuple_parameters(
            statement,
            conflicting_index,
            plan->rows[row_index].values,
            plan->column_count
        );
    }
    if (rc == MYLITE_OK) {
        sqlite_rc = sqlite3_step(statement);
        if (sqlite_rc == SQLITE_ROW) {
            rc = compare_replace_conflicting_row(statement, plan, row_index, out_matches);
        } else if (sqlite_rc == SQLITE_DONE) {
            set_runtime_error(database, "REPLACE conflicting row disappeared before delete");
            rc = MYLITE_ERROR;
        } else {
            rc = mylite_sqlite_status_to_mylite(sqlite_rc);
        }
    }
    rc = finalize_sqlite_statement(statement, rc);
    free(sql);

    return rc;
}

static int build_replace_conflicting_row_select_sql(
    const struct planned_insert *plan,
    const struct loaded_index_info *conflicting_index,
    char **out_sql
) {
    struct dynamic_string string;
    int rc = MYLITE_OK;

    *out_sql = NULL;
    dynamic_string_init(&string);

    if (conflicting_index == NULL || conflicting_index->part_count == 0U) {
        dynamic_string_deinit(&string);
        return MYLITE_ERROR;
    }

    rc = dynamic_string_append(&string, "SELECT ");
    if (rc == MYLITE_OK) {
        rc = append_insert_column_names(&string, plan);
    }
    if (rc == MYLITE_OK) {
        rc = dynamic_string_append(&string, " FROM ");
    }
    if (rc == MYLITE_OK) {
        rc = dynamic_string_append_quoted_identifier(&string, plan->table.physical_name);
    }
    if (rc == MYLITE_OK) {
        rc = dynamic_string_append(&string, " WHERE ");
    }
    for (size_t part_index = 0U; rc == MYLITE_OK && part_index < conflicting_index->part_count;
         ++part_index) {
        if (part_index != 0U) {
            rc = dynamic_string_append(&string, " AND ");
        }
        if (rc == MYLITE_OK) {
            rc = append_loaded_key_part_sql(&string, &conflicting_index->parts[part_index], NULL);
        }
        if (rc == MYLITE_OK) {
            rc = dynamic_string_append(&string, " = ");
        }
        if (rc == MYLITE_OK) {
            rc = append_loaded_key_part_parameter_sql(
                &string,
                &conflicting_index->parts[part_index],
                part_index + 1U
            );
        }
    }
    if (rc == MYLITE_OK) {
        rc = dynamic_string_append(&string, " LIMIT 1");
    }
    if (rc == MYLITE_OK) {
        *out_sql = dynamic_string_take(&string);
        if (*out_sql == NULL) {
            rc = MYLITE_NOMEM;
        }
    }

    dynamic_string_deinit(&string);
    return rc;
}

static int compare_replace_conflicting_row(
    sqlite3_stmt *statement,
    const struct planned_insert *plan,
    size_t row_index,
    bool *out_matches
) {
    *out_matches = false;
    if (row_index >= plan->row_count) {
        return MYLITE_ERROR;
    }
    for (size_t column_index = 0U; column_index < plan->column_count; ++column_index) {
        if (column_index >= (size_t)INT_MAX) {
            return MYLITE_ERROR;
        }
        if (!sqlite_column_matches_planned_value(
                statement,
                (int)column_index,
                &plan->rows[row_index].values[column_index]
            )) {
            return MYLITE_OK;
        }
    }

    *out_matches = true;
    return MYLITE_OK;
}

static bool sqlite_column_matches_planned_value(
    sqlite3_stmt *statement,
    int column_index,
    const struct planned_value *value
) {
    int sqlite_type = sqlite3_column_type(statement, column_index);

    if (value == NULL) {
        return false;
    }
    if (value->is_null) {
        return sqlite_type == SQLITE_NULL;
    }
    if (sqlite_type == SQLITE_NULL) {
        return false;
    }
    if (value->is_blob) {
        int byte_count = sqlite3_column_bytes(statement, column_index);
        const void *bytes = sqlite3_column_blob(statement, column_index);

        if (byte_count < 0 || (size_t)byte_count != value->text_length) {
            return false;
        }
        if (value->text_length != 0U && (bytes == NULL || value->text == NULL)) {
            return false;
        }
        if (value->text_length == 0U) {
            return true;
        }
        return memcmp(bytes, value->text, value->text_length) == 0;
    }
    if (value->is_text) {
        int byte_count = sqlite3_column_bytes(statement, column_index);
        const unsigned char *text = sqlite3_column_text(statement, column_index);

        if (byte_count < 0 || (size_t)byte_count != value->text_length) {
            return false;
        }
        if (value->text_length != 0U && (text == NULL || value->text == NULL)) {
            return false;
        }
        if (value->text_length == 0U) {
            return true;
        }
        return memcmp(text, value->text, value->text_length) == 0;
    }
    if (value->is_real) {
        return sqlite3_column_double(statement, column_index) == value->real;
    }

    return sqlite3_column_int64(statement, column_index) == (sqlite3_int64)value->integer;
}

static int delete_replace_conflicting_row(
    struct mylite_db *database,
    const struct planned_insert *plan,
    const struct loaded_index_info *conflicting_index,
    size_t row_index,
    sqlite3_int64 *out_deleted_rows
) {
    sqlite3_stmt *statement = NULL;
    char *sql = NULL;
    int sqlite_rc = SQLITE_OK;
    int rc = MYLITE_OK;

    *out_deleted_rows = 0;
    rc = build_replace_conflicting_row_delete_sql(plan, conflicting_index, &sql);
    if (rc == MYLITE_OK) {
        rc = prepare_sqlite_statement(database, sql, &statement);
    }
    if (rc == MYLITE_OK) {
        rc = bind_unique_key_tuple_parameters(
            statement,
            conflicting_index,
            plan->rows[row_index].values,
            plan->column_count
        );
    }
    if (rc == MYLITE_OK) {
        sqlite_rc = sqlite3_step(statement);
        if (sqlite_rc == SQLITE_DONE) {
            *out_deleted_rows = sqlite3_changes64(database->sqlite);
            if (*out_deleted_rows <= 0) {
                set_runtime_error(database, "REPLACE failed to delete conflicting row");
                rc = MYLITE_ERROR;
            }
        } else {
            rc = mylite_sqlite_status_to_mylite(sqlite_rc);
        }
    }
    rc = finalize_sqlite_statement(statement, rc);
    free(sql);

    return rc;
}

static int build_replace_conflicting_row_delete_sql(
    const struct planned_insert *plan,
    const struct loaded_index_info *conflicting_index,
    char **out_sql
) {
    struct dynamic_string string;
    int rc = MYLITE_OK;

    *out_sql = NULL;
    dynamic_string_init(&string);

    if (conflicting_index == NULL || conflicting_index->part_count == 0U) {
        dynamic_string_deinit(&string);
        return MYLITE_ERROR;
    }

    rc = dynamic_string_append(&string, "DELETE FROM ");
    if (rc == MYLITE_OK) {
        rc = dynamic_string_append_quoted_identifier(&string, plan->table.physical_name);
    }
    if (rc == MYLITE_OK) {
        rc = dynamic_string_append(&string, " WHERE ");
    }
    for (size_t part_index = 0U; rc == MYLITE_OK && part_index < conflicting_index->part_count;
         ++part_index) {
        if (part_index != 0U) {
            rc = dynamic_string_append(&string, " AND ");
        }
        if (rc == MYLITE_OK) {
            rc = append_loaded_key_part_sql(&string, &conflicting_index->parts[part_index], NULL);
        }
        if (rc == MYLITE_OK) {
            rc = dynamic_string_append(&string, " = ");
        }
        if (rc == MYLITE_OK) {
            rc = append_loaded_key_part_parameter_sql(
                &string,
                &conflicting_index->parts[part_index],
                part_index + 1U
            );
        }
    }
    if (rc == MYLITE_OK) {
        *out_sql = dynamic_string_take(&string);
        if (*out_sql == NULL) {
            rc = MYLITE_NOMEM;
        }
    }

    dynamic_string_deinit(&string);
    return rc;
}

static int plan_insert_select(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *statement,
    struct planned_insert_select *out_plan
) {
    const struct mylite_sql_ast_node *column_list = child_at(statement, 1U);
    const struct mylite_sql_ast_node *source_statement = child_at(statement, 2U);
    struct primary_key_info primary_key = primary_key_info_init();
    bool ignore = child_with_kind(statement, MYLITE_SQL_AST_INSERT_IGNORE_MODIFIER) != NULL;
    enum planned_insert_select_source_kind source_kind =
        insert_select_source_kind(source_statement);
    int rc = MYLITE_OK;

    *out_plan = (struct planned_insert_select){0};
    out_plan->target.ignore_errors = ignore;
    out_plan->target.replace_existing_rows =
        statement->kind == MYLITE_SQL_AST_REPLACE_SELECT_STATEMENT;
    out_plan->source_kind = source_kind;
    if (source_kind == PLANNED_INSERT_SELECT_SOURCE_ROW_SCALAR &&
        statement->kind == MYLITE_SQL_AST_REPLACE_SELECT_STATEMENT) {
        set_unsupported_error(database, "REPLACE ... SELECT does not support row-scalar sources");
        primary_key_info_deinit(&primary_key);
        return MYLITE_ERROR;
    }
    if (source_kind == PLANNED_INSERT_SELECT_SOURCE_COMPOUND &&
        statement->kind == MYLITE_SQL_AST_REPLACE_SELECT_STATEMENT) {
        set_unsupported_error(database, "REPLACE ... SELECT does not support UNION sources");
        primary_key_info_deinit(&primary_key);
        return MYLITE_ERROR;
    }
    rc = plan_insert_select_target(database, statement, out_plan, &primary_key);
    if (rc == MYLITE_OK && statement->kind == MYLITE_SQL_AST_INSERT_SELECT_STATEMENT) {
        rc = initialize_insert_auto_increment_plan(database, &out_plan->target);
    }
    if (rc == MYLITE_OK && statement->kind == MYLITE_SQL_AST_INSERT_SELECT_STATEMENT) {
        rc = initialize_insert_auto_increment_range(database, &out_plan->target);
    }
    if (rc == MYLITE_OK && source_kind == PLANNED_INSERT_SELECT_SOURCE_TABLE &&
        statement->kind == MYLITE_SQL_AST_REPLACE_SELECT_STATEMENT) {
        rc = reject_insert_select_key_bearing_target(database, statement, out_plan, &primary_key);
    }
    if (rc == MYLITE_OK) {
        rc = collect_insert_target_indexes(
            database,
            column_list,
            &out_plan->target,
            NULL,
            &out_plan->target_indexes,
            &out_plan->target_count
        );
    }
    if (rc == MYLITE_OK) {
        rc = check_insert_target_duplicate(
            database,
            out_plan->target.columns,
            out_plan->target_indexes,
            out_plan->target_count
        );
    }
    if (rc == MYLITE_OK && ignore && source_kind == PLANNED_INSERT_SELECT_SOURCE_ROW_SCALAR) {
        set_unsupported_error(
            database,
            "INSERT IGNORE ... SELECT does not support row-scalar sources"
        );
        rc = MYLITE_ERROR;
    }
    if (rc == MYLITE_OK && ignore && source_kind == PLANNED_INSERT_SELECT_SOURCE_COMPOUND) {
        set_unsupported_error(database, "INSERT IGNORE ... SELECT does not support UNION sources");
        rc = MYLITE_ERROR;
    }
    if (rc == MYLITE_OK && ignore && source_kind == PLANNED_INSERT_SELECT_SOURCE_TABLE &&
        out_plan->target.has_auto_increment) {
        set_unsupported_error(
            database,
            "INSERT IGNORE ... SELECT does not support AUTO_INCREMENT targets"
        );
        rc = MYLITE_ERROR;
    }
    if (rc == MYLITE_OK) {
        rc = plan_insert_select_source(database, statement, source_kind, out_plan);
    }

    primary_key_info_deinit(&primary_key);
    return rc;
}

static enum planned_insert_select_source_kind insert_select_source_kind(
    const struct mylite_sql_ast_node *source_statement
) {
    if (source_statement != NULL &&
        source_statement->kind == MYLITE_SQL_AST_COMPOUND_SELECT_STATEMENT) {
        return PLANNED_INSERT_SELECT_SOURCE_COMPOUND;
    }
    if (insert_select_source_is_row_scalar(source_statement)) {
        return PLANNED_INSERT_SELECT_SOURCE_ROW_SCALAR;
    }

    return PLANNED_INSERT_SELECT_SOURCE_TABLE;
}

static bool insert_select_source_is_row_scalar(const struct mylite_sql_ast_node *select_statement) {
    const struct mylite_sql_ast_node *from_clause = NULL;

    if (select_statement == NULL || select_statement->kind != MYLITE_SQL_AST_SELECT_STATEMENT) {
        return false;
    }

    from_clause = child_at(select_statement, 1U);
    return (from_clause == NULL || from_clause->kind == MYLITE_SQL_AST_FROM_DUAL) != 0;
}

static int plan_insert_select_target(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *statement,
    struct planned_insert_select *out_plan,
    struct primary_key_info *primary_key
) {
    int rc = resolve_visible_writable_table_reference(
        database,
        child_at(statement, 0U),
        &out_plan->target.target,
        &out_plan->target.table
    );

    if (rc == MYLITE_OK) {
        rc = load_table_columns(
            database,
            out_plan->target.table.table_id,
            &out_plan->target.columns,
            &out_plan->target.column_count
        );
    }
    if (rc == MYLITE_OK) {
        rc = load_primary_key_info(
            database,
            out_plan->target.table.table_id,
            out_plan->target.columns,
            out_plan->target.column_count,
            primary_key
        );
    }
    if (rc == MYLITE_OK) {
        apply_insert_select_primary_key_info(primary_key, &out_plan->target);
        rc = load_table_index_infos(
            database,
            out_plan->target.table.table_id,
            out_plan->target.columns,
            out_plan->target.column_count,
            &out_plan->target.indexes,
            &out_plan->target.index_count
        );
    }
    if (rc == MYLITE_OK) {
        rc = load_insert_target_foreign_key_infos(database, &out_plan->target);
    }

    return rc;
}

static void apply_insert_select_primary_key_info(
    const struct primary_key_info *primary_key,
    struct planned_insert *target
) {
    if (!primary_key->has_primary_key) {
        return;
    }

    target->has_primary_key = true;
    if (primary_key->part_count == 1U) {
        target->primary_key_column_index = primary_key->parts[0].column_index;
    }
}

static int plan_insert_select_source(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *statement,
    enum planned_insert_select_source_kind source_kind,
    struct planned_insert_select *out_plan
) {
    const struct mylite_sql_ast_node *select_statement = child_at(statement, 2U);

    if (source_kind == PLANNED_INSERT_SELECT_SOURCE_ROW_SCALAR) {
        return plan_insert_select_row_scalar_source(database, select_statement, out_plan);
    }
    if (source_kind == PLANNED_INSERT_SELECT_SOURCE_COMPOUND) {
        return plan_insert_select_compound_source(database, statement, out_plan);
    }

    return plan_insert_select_table_source(database, statement, out_plan);
}

static int plan_insert_select_row_scalar_source(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *select_statement,
    struct planned_insert_select *out_plan
) {
    int rc = plan_row_scalar_select(database, select_statement, &out_plan->row_source);

    if (rc == MYLITE_OK && out_plan->row_source.item_count != out_plan->target_count) {
        set_column_count_mismatch_error(database, 1U);
        rc = MYLITE_ERROR;
    }

    return rc;
}

static int plan_insert_select_table_source(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *statement,
    struct planned_insert_select *out_plan
) {
    int rc = plan_select(database, child_at(statement, 2U), &out_plan->source);

    if (rc == MYLITE_OK && out_plan->source.calc_found_rows) {
        if (statement->kind == MYLITE_SQL_AST_REPLACE_SELECT_STATEMENT) {
            set_unsupported_error(
                database,
                "REPLACE ... SELECT does not support SQL_CALC_FOUND_ROWS"
            );
        } else {
            set_unsupported_error(
                database,
                "INSERT ... SELECT does not support SQL_CALC_FOUND_ROWS"
            );
        }
        rc = MYLITE_ERROR;
    }
    if (rc == MYLITE_OK && out_plan->source.source_count > 0U) {
        if (statement->kind == MYLITE_SQL_AST_REPLACE_SELECT_STATEMENT) {
            set_unsupported_error(database, "REPLACE ... SELECT does not support joined SELECT");
        } else {
            set_unsupported_error(database, "INSERT ... SELECT does not support joined SELECT");
        }
        rc = MYLITE_ERROR;
    }
    if (rc == MYLITE_OK && out_plan->source.column_count != out_plan->target_count) {
        set_column_count_mismatch_error(database, 1U);
        rc = MYLITE_ERROR;
    }

    return rc;
}

static int plan_insert_select_compound_source(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *statement,
    struct planned_insert_select *out_plan
) {
    const struct mylite_sql_ast_node *compound_statement = child_at(statement, 2U);
    const struct mylite_sql_ast_node *terms = child_at(compound_statement, 1U);
    const struct mylite_sql_ast_node *term = NULL;
    size_t branch_count = mylite_sql_ast_node_child_count(terms);
    size_t first_column_count = 0U;
    int rc = MYLITE_OK;

    if (compound_statement == NULL ||
        compound_statement->kind != MYLITE_SQL_AST_COMPOUND_SELECT_STATEMENT ||
        branch_count == SIZE_MAX) {
        set_parse_error(database, NULL);
        return MYLITE_ERROR;
    }
    ++branch_count;
    out_plan->compound_source.branches =
        calloc(branch_count, sizeof(*out_plan->compound_source.branches));
    if (out_plan->compound_source.branches == NULL) {
        set_nomem_error(database);
        return MYLITE_NOMEM;
    }
    out_plan->compound_source.branch_count = branch_count;

    rc = plan_insert_select_compound_branch(
        database,
        child_at(compound_statement, 0U),
        MYLITE_SQL_AST_UNION_MODIFIER_DISTINCT,
        &out_plan->compound_source.branches[0],
        &first_column_count
    );

    term = child_at(terms, 0U);
    for (size_t branch_index = 1U; rc == MYLITE_OK && branch_index < branch_count; ++branch_index) {
        size_t branch_column_count = 0U;

        rc = plan_insert_select_compound_branch(
            database,
            child_at(term, 0U),
            mylite_sql_ast_node_union_modifier(term),
            &out_plan->compound_source.branches[branch_index],
            &branch_column_count
        );
        if (rc == MYLITE_OK && branch_column_count != first_column_count) {
            set_union_column_count_mismatch_error(database);
            rc = MYLITE_ERROR;
        }
        term = term->next_sibling;
    }
    if (rc == MYLITE_OK && first_column_count != out_plan->target_count) {
        set_column_count_mismatch_error(database, 1U);
        rc = MYLITE_ERROR;
    }
    if (rc == MYLITE_OK) {
        rc = validate_insert_select_compound_target_compatibility(database, out_plan);
    }

    if (rc != MYLITE_OK) {
        planned_insert_select_compound_source_deinit(&out_plan->compound_source);
    }

    return rc;
}

static int plan_insert_select_compound_branch(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *branch_statement,
    enum mylite_sql_ast_union_modifier modifier,
    struct planned_insert_select_compound_branch *out_branch,
    size_t *out_column_count
) {
    int rc = reject_compound_select_branch_shape(database, branch_statement);

    *out_branch = (struct planned_insert_select_compound_branch){.modifier = modifier};
    *out_column_count = 0U;
    if (rc != MYLITE_OK) {
        return rc;
    }
    if (insert_select_source_is_row_scalar(branch_statement)) {
        out_branch->kind = PLANNED_INSERT_SELECT_COMPOUND_BRANCH_ROW_SCALAR;
        return plan_insert_select_compound_row_scalar_branch(
            database,
            branch_statement,
            out_branch,
            out_column_count
        );
    }

    out_branch->kind = PLANNED_INSERT_SELECT_COMPOUND_BRANCH_TABLE;
    return plan_insert_select_compound_table_branch(
        database,
        branch_statement,
        out_branch,
        out_column_count
    );
}

static int plan_insert_select_compound_table_branch(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *branch_statement,
    struct planned_insert_select_compound_branch *out_branch,
    size_t *out_column_count
) {
    int rc = plan_select(database, branch_statement, &out_branch->source);

    if (rc == MYLITE_OK && out_branch->source.source_count > 0U) {
        set_unsupported_error(database, "INSERT ... SELECT UNION does not support joined SELECT");
        rc = MYLITE_ERROR;
    }
    if (rc == MYLITE_OK) {
        *out_column_count = out_branch->source.column_count;
    }
    if (rc != MYLITE_OK) {
        planned_select_deinit(&out_branch->source);
    }

    return rc;
}

static int plan_insert_select_compound_row_scalar_branch(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *branch_statement,
    struct planned_insert_select_compound_branch *out_branch,
    size_t *out_column_count
) {
    int rc = plan_row_scalar_select(database, branch_statement, &out_branch->row_source);

    if (rc == MYLITE_OK) {
        *out_column_count = out_branch->row_source.item_count;
    }
    if (rc != MYLITE_OK) {
        planned_row_scalar_select_deinit(&out_branch->row_source);
    }

    return rc;
}

static int validate_insert_select_compound_branch_target_compatibility(
    struct mylite_db *database,
    const struct planned_insert_select *plan,
    const struct planned_select *source
) {
    for (size_t target_position = 0U; target_position < plan->target_count; ++target_position) {
        size_t column_index = plan->target_indexes[target_position];

        if (!insert_select_source_target_types_are_compatible(
                &source->columns[target_position],
                &plan->target.columns[column_index]
            )) {
            set_unsupported_error(
                database,
                insert_select_implicit_conversion_message(&plan->target.columns[column_index])
            );
            return MYLITE_ERROR;
        }
    }

    return MYLITE_OK;
}

static int validate_insert_select_compound_target_compatibility(
    struct mylite_db *database,
    const struct planned_insert_select *plan
) {
    int rc = MYLITE_OK;

    for (size_t branch_index = 0U;
         rc == MYLITE_OK && branch_index < plan->compound_source.branch_count;
         ++branch_index) {
        const struct planned_insert_select_compound_branch *branch =
            &plan->compound_source.branches[branch_index];

        if (branch->kind == PLANNED_INSERT_SELECT_COMPOUND_BRANCH_TABLE) {
            rc = validate_insert_select_compound_branch_target_compatibility(
                database,
                plan,
                &branch->source
            );
        }
    }

    return rc;
}

static void planned_insert_select_compound_source_deinit(
    struct planned_insert_select_compound_source *source
) {
    if (source == NULL) {
        return;
    }
    for (size_t branch_index = 0U; branch_index < source->branch_count; ++branch_index) {
        planned_select_deinit(&source->branches[branch_index].source);
        planned_row_scalar_select_deinit(&source->branches[branch_index].row_source);
    }
    free(source->branches);
    *source = (struct planned_insert_select_compound_source){0};
}

static int reject_insert_select_key_bearing_target(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *statement,
    struct planned_insert_select *out_plan,
    const struct primary_key_info *primary_key
) {
    if (primary_key->has_primary_key) {
        out_plan->target.has_primary_key = true;
        if (primary_key->part_count == 1U) {
            out_plan->target.primary_key_column_index = primary_key->parts[0].column_index;
        }
        if (statement->kind == MYLITE_SQL_AST_REPLACE_SELECT_STATEMENT) {
            set_unsupported_error(
                database,
                "REPLACE ... SELECT into primary-key tables is not supported"
            );
        } else {
            set_unsupported_error(
                database,
                "INSERT ... SELECT into primary-key tables is not supported"
            );
        }
        return MYLITE_ERROR;
    }

    if (!table_has_unique_secondary_index((struct loaded_index_info_span){
            .indexes = out_plan->target.indexes,
            .count = out_plan->target.index_count,
        })) {
        if (out_plan->target.foreign_key_count == 0U) {
            return MYLITE_OK;
        }
        if (statement->kind == MYLITE_SQL_AST_REPLACE_SELECT_STATEMENT) {
            set_unsupported_error(
                database,
                "REPLACE ... SELECT into foreign-key child tables is not supported"
            );
        } else {
            set_unsupported_error(
                database,
                "INSERT ... SELECT into foreign-key child tables is not supported"
            );
        }
        return MYLITE_ERROR;
    }

    if (statement->kind == MYLITE_SQL_AST_REPLACE_SELECT_STATEMENT) {
        set_unsupported_error(
            database,
            "REPLACE ... SELECT into unique-index tables is not supported"
        );
    } else {
        set_unsupported_error(
            database,
            "INSERT ... SELECT into unique-index tables is not supported"
        );
    }
    return MYLITE_ERROR;
}

static void planned_insert_select_deinit(struct planned_insert_select *plan) {
    if (plan == NULL) {
        return;
    }

    planned_select_deinit(&plan->source);
    planned_row_scalar_select_deinit(&plan->row_source);
    planned_insert_select_compound_source_deinit(&plan->compound_source);
    planned_insert_deinit(&plan->target);
    free(plan->target_indexes);
    *plan = (struct planned_insert_select){0};
}

static int execute_insert_select_from_plan(
    struct mylite_db *database,
    const struct planned_insert_select *plan,
    mylite_result *result
) {
    if (plan->source_kind == PLANNED_INSERT_SELECT_SOURCE_ROW_SCALAR) {
        return execute_insert_select_row_scalar_from_plan(database, plan, result);
    }

    return execute_insert_select_table_from_plan(database, plan, result);
}

static int execute_insert_select_table_from_plan(
    struct mylite_db *database,
    const struct planned_insert_select *plan,
    mylite_result *result
) {
    struct insert_select_table_execution execution = {0};
    int rc = prepare_insert_select_table_execution(database, plan, &execution);

    if (rc == MYLITE_OK) {
        rc = execute_insert_select_table(database, plan, &execution);
    }
    if (rc == MYLITE_OK) {
        rc = finish_insert_select_table_result(database, &execution, result);
    }
    cleanup_insert_select_table_execution(database, &execution, rc);

    return normalize_insert_select_table_result(database, rc);
}

static int prepare_insert_select_table_execution(
    struct mylite_db *database,
    const struct planned_insert_select *plan,
    struct insert_select_table_execution *execution
) {
    int rc = build_insert_select_temp_table_name(
        database,
        execution->temporary_table_name,
        sizeof(execution->temporary_table_name)
    );

    if (rc == MYLITE_OK) {
        rc = build_insert_select_materialize_sql(
            plan,
            execution->temporary_table_name,
            &execution->materialize_sql
        );
    }
    if (rc == MYLITE_OK) {
        rc = build_insert_select_validation_sql(
            plan,
            execution->temporary_table_name,
            &execution->validation_sql
        );
    }
    if (rc == MYLITE_OK) {
        rc = build_insert_sql(&plan->target, &execution->insert_sql);
    }
    if (rc == MYLITE_OK) {
        rc = build_drop_temp_table_sql(execution->temporary_table_name, &execution->drop_sql);
    }

    return rc;
}

static int execute_insert_select_table(
    struct mylite_db *database,
    const struct planned_insert_select *plan,
    struct insert_select_table_execution *execution
) {
    int rc = begin_statement_transaction(database, &execution->transaction);

    if (rc == MYLITE_OK) {
        rc = execute_sqlite_control_sql(database, execution->drop_sql);
    }
    if (rc == MYLITE_OK) {
        rc = execute_insert_select_materialize(
            database,
            execution->materialize_sql,
            plan,
            &execution->temporary_table_created
        );
    }
    if (rc == MYLITE_OK) {
        rc = validate_insert_select_table_rows(database, plan, execution);
    }
    if (rc == MYLITE_OK) {
        rc = execute_insert_select_insert(
            database,
            execution->validation_sql,
            execution->insert_sql,
            plan,
            &execution->counters
        );
    }
    if (rc == MYLITE_OK) {
        rc = finish_insert_select_table_side_effects(database, plan, execution);
    }
    if (rc == MYLITE_OK) {
        rc = execute_sqlite_control_sql(database, execution->drop_sql);
    }
    if (rc == MYLITE_OK) {
        execution->temporary_table_created = false;
        rc = commit_statement_transaction(database, &execution->transaction);
    }
    if (rc != MYLITE_OK) {
        rollback_statement_transaction(database, &execution->transaction);
    }

    return rc;
}

static int validate_insert_select_table_rows(
    struct mylite_db *database,
    const struct planned_insert_select *plan,
    const struct insert_select_table_execution *execution
) {
    sqlite3_stmt *validation_statement = NULL;
    int rc = prepare_sqlite_statement(database, execution->validation_sql, &validation_statement);

    if (rc == MYLITE_OK) {
        rc = validate_insert_select_rows(database, validation_statement, plan);
    }

    return finalize_sqlite_statement(validation_statement, rc);
}

static int finish_insert_select_table_side_effects(
    struct mylite_db *database,
    const struct planned_insert_select *plan,
    struct insert_select_table_execution *execution
) {
    int rc = MYLITE_OK;

    if (plan->target.has_auto_increment &&
        execution->counters.auto_increment_next_after_rows != plan->target.auto_increment_next) {
        rc = update_table_auto_increment_next(
            database,
            &plan->target.table,
            execution->counters.auto_increment_next_after_rows
        );
    }
    if (rc == MYLITE_OK) {
        rc = touch_persistent_table_updated_time(
            database,
            &plan->target.table,
            execution->counters.affected_rows,
            false
        );
    }
    if (rc == MYLITE_OK) {
        rc = validate_child_foreign_keys_after_write(database, plan->target.table.table_id);
    }

    return rc;
}

static void cleanup_insert_select_table_execution(
    struct mylite_db *database,
    struct insert_select_table_execution *execution,
    int rc
) {
    if (rc != MYLITE_OK && execution->temporary_table_created) {
        (void)execute_sqlite_control_sql(database, execution->drop_sql);
    }
    free(execution->materialize_sql);
    free(execution->validation_sql);
    free(execution->insert_sql);
    free(execution->drop_sql);
    *execution = (struct insert_select_table_execution){0};
}

static int normalize_insert_select_table_result(struct mylite_db *database, int rc) {
    if (rc == MYLITE_OK) {
        return MYLITE_OK;
    }
    if (rc == MYLITE_NOMEM) {
        set_nomem_error(database);
        return rc;
    }
    if (mylite_diagnostics_errcode(mylite_connection_diagnostics(database)) != MYLITE_OK) {
        return rc;
    }

    set_physical_sqlite_row_error(database);
    return MYLITE_ERROR;
}

static int finish_insert_select_table_result(
    struct mylite_db *database,
    const struct insert_select_table_execution *execution,
    mylite_result *result
) {
    mylite_result_set_affected_rows(result, execution->counters.affected_rows);
    if (execution->counters.inserted_generated_auto_increment) {
        database->session.last_insert_id =
            (uint64_t)execution->counters.first_inserted_generated_auto_increment;
    }

    return MYLITE_OK;
}

static int execute_insert_select_row_scalar_from_plan(
    struct mylite_db *database,
    const struct planned_insert_select *plan,
    mylite_result *result
) {
    sqlite3_stmt *statement = NULL;
    struct planned_insert_row row = {0};
    char *sql = NULL;
    bool has_row = false;
    int rc = prepare_insert_select_row_scalar_source(database, plan, &statement, &sql, &has_row);

    if (rc == MYLITE_OK && has_row) {
        rc = materialize_insert_select_row_scalar_row(database, statement, plan, &row);
    }
    rc = finalize_sqlite_statement(statement, rc);
    free(sql);
    if (rc == MYLITE_OK) {
        rc = finish_insert_select_row_scalar_result(database, plan, has_row, &row, result);
    }

    planned_insert_row_deinit(&row, plan->target.column_count);
    return normalize_insert_select_row_scalar_result(database, rc);
}

static int prepare_insert_select_row_scalar_source(
    struct mylite_db *database,
    const struct planned_insert_select *plan,
    sqlite3_stmt **out_statement,
    char **out_sql,
    bool *out_has_row
) {
    int sqlite_rc = SQLITE_OK;
    int rc = MYLITE_OK;

    *out_statement = NULL;
    *out_sql = NULL;
    *out_has_row = false;

    rc = build_row_scalar_select_sql(&plan->row_source, out_sql);
    if (rc == MYLITE_OK) {
        rc = prepare_sqlite_statement(database, *out_sql, out_statement);
    }
    if (rc == MYLITE_OK) {
        rc = bind_row_scalar_select_parameters(*out_statement, &plan->row_source);
    }
    if (rc != MYLITE_OK) {
        return rc;
    }

    sqlite_rc = sqlite3_step(*out_statement);
    if (sqlite_rc == SQLITE_ROW) {
        *out_has_row = true;
        return MYLITE_OK;
    }
    if (sqlite_rc == SQLITE_DONE) {
        return MYLITE_OK;
    }

    return mylite_sqlite_status_to_mylite(sqlite_rc);
}

static int materialize_insert_select_row_scalar_row(
    struct mylite_db *database,
    sqlite3_stmt *statement,
    const struct planned_insert_select *plan,
    struct planned_insert_row *row
) {
    int sqlite_rc = SQLITE_OK;
    int rc = MYLITE_OK;

    if (plan->target.column_count > SIZE_MAX / sizeof(*row->values)) {
        set_nomem_error(database);
        return MYLITE_NOMEM;
    }
    row->values = calloc(plan->target.column_count, sizeof(*row->values));
    if (row->values == NULL) {
        set_nomem_error(database);
        return MYLITE_NOMEM;
    }

    rc = check_insert_omitted_columns(
        database,
        &plan->target,
        plan->target_indexes,
        plan->target_count
    );
    if (rc == MYLITE_OK) {
        rc = validate_insert_select_row_scalar_row(database, statement, plan, 1U);
    }
    if (rc == MYLITE_OK) {
        rc = materialize_insert_select_row_values(database, statement, plan, 1U, row->values);
    }

    if (rc != MYLITE_OK) {
        return rc;
    }
    sqlite_rc = sqlite3_step(statement);
    if (sqlite_rc == SQLITE_ROW) {
        set_unsupported_error(
            database,
            "INSERT ... SELECT row-scalar source returned too many rows"
        );
        return MYLITE_ERROR;
    }
    if (sqlite_rc != SQLITE_DONE) {
        return mylite_sqlite_status_to_mylite(sqlite_rc);
    }

    return MYLITE_OK;
}

static int finish_insert_select_row_scalar_result(
    struct mylite_db *database,
    const struct planned_insert_select *plan,
    bool has_row,
    struct planned_insert_row *row,
    mylite_result *result
) {
    if (has_row) {
        return execute_insert_select_row_scalar_insert(database, plan, row, result);
    }

    mylite_result_set_affected_rows(result, 0);
    return MYLITE_OK;
}

static void planned_insert_row_deinit(struct planned_insert_row *row, size_t column_count) {
    if (row == NULL || row->values == NULL) {
        return;
    }

    for (size_t column_index = 0U; column_index < column_count; ++column_index) {
        planned_value_deinit(&row->values[column_index]);
    }
    free(row->values);
    *row = (struct planned_insert_row){0};
}

static int normalize_insert_select_row_scalar_result(struct mylite_db *database, int rc) {
    if (rc == MYLITE_OK) {
        return MYLITE_OK;
    }
    if (rc == MYLITE_NOMEM) {
        set_nomem_error(database);
        return rc;
    }
    if (mylite_diagnostics_errcode(mylite_connection_diagnostics(database)) != MYLITE_OK) {
        return rc;
    }

    set_physical_sqlite_row_error(database);
    return MYLITE_ERROR;
}

static int validate_insert_select_row_scalar_row(
    struct mylite_db *database,
    sqlite3_stmt *statement,
    const struct planned_insert_select *plan,
    size_t row_number
) {
    if (plan->target_count > (size_t)INT_MAX) {
        return MYLITE_ERROR;
    }
    for (size_t target_position = 0U; target_position < plan->target_count; ++target_position) {
        size_t column_index = plan->target_indexes[target_position];
        const struct mylite_catalog_column_descriptor *target_column =
            &plan->target.columns[column_index];
        int rc = MYLITE_OK;

        if (column_descriptor_is_auto_increment(target_column) &&
            sqlite3_column_type(statement, (int)target_position) == SQLITE_NULL) {
            continue;
        }
        rc = validate_insert_select_value(
            database,
            statement,
            (int)target_position,
            NULL,
            target_column,
            row_number
        );

        if (rc != MYLITE_OK) {
            return rc;
        }
    }

    return MYLITE_OK;
}

static int execute_insert_select_row_scalar_insert(
    struct mylite_db *database,
    const struct planned_insert_select *plan,
    struct planned_insert_row *row,
    mylite_result *result
) {
    struct planned_insert row_plan = plan->target;
    int rc = MYLITE_OK;

    row_plan.rows = row;
    row_plan.row_count = 1U;
    rc = plan_insert_auto_increment_values(database, &row_plan);
    if (rc == MYLITE_OK) {
        rc = plan_insert_string_key_values(database, &row_plan);
    }
    if (rc == MYLITE_OK) {
        rc = execute_insert_from_plan(database, &row_plan, result);
    }

    return rc;
}

static int execute_insert_select_materialize(
    struct mylite_db *database,
    const char *materialize_sql,
    const struct planned_insert_select *plan,
    bool *out_temporary_table_created
) {
    sqlite3_stmt *statement = NULL;
    int sqlite_rc = SQLITE_OK;
    int rc = MYLITE_OK;

    *out_temporary_table_created = false;
    rc = prepare_sqlite_statement(database, materialize_sql, &statement);
    if (rc == MYLITE_OK) {
        rc = bind_insert_select_materialize_parameters(statement, plan);
    }
    if (rc == MYLITE_OK) {
        sqlite_rc = sqlite3_step(statement);
        if (sqlite_rc == SQLITE_DONE) {
            *out_temporary_table_created = true;
        } else {
            rc = mylite_sqlite_status_to_mylite(sqlite_rc);
        }
    }

    return finalize_sqlite_statement(statement, rc);
}

static int execute_insert_select_insert(
    struct mylite_db *database,
    const char *validation_sql,
    const char *insert_sql,
    const struct planned_insert_select *plan,
    struct insert_execution_counters *counters
) {
    struct insert_select_execution_statements statements = {0};
    int rc = MYLITE_OK;

    *counters = (struct insert_execution_counters){0};
    if (plan->target.has_auto_increment) {
        counters->auto_increment_next_after_rows = plan->target.auto_increment_next;
    }
    rc = prepare_sqlite_statement(database, validation_sql, &statements.select_statement);
    if (rc == MYLITE_OK) {
        rc = prepare_sqlite_statement(database, insert_sql, &statements.insert_statement);
    }
    if (rc == MYLITE_OK) {
        rc = execute_insert_select_insert_rows(database, &statements, plan, counters);
    }
    rc = finalize_sqlite_statement(statements.insert_statement, rc);
    statements.insert_statement = NULL;

    return finalize_sqlite_statement(statements.select_statement, rc);
}

static int execute_insert_select_insert_rows(
    struct mylite_db *database,
    struct insert_select_execution_statements *statements,
    const struct planned_insert_select *plan,
    struct insert_execution_counters *counters
) {
    size_t row_number = 0U;
    int sqlite_rc = SQLITE_OK;
    int rc = MYLITE_OK;

    while ((sqlite_rc = sqlite3_step(statements->select_statement)) == SQLITE_ROW) {
        if (row_number == SIZE_MAX) {
            set_unsupported_error(database, "INSERT ... SELECT selected too many rows");
            return MYLITE_ERROR;
        }
        ++row_number;
        rc = execute_insert_select_insert_row(database, statements, plan, row_number, counters);
        if (rc != MYLITE_OK) {
            return rc;
        }
    }
    if (sqlite_rc != SQLITE_DONE) {
        return mylite_sqlite_status_to_mylite(sqlite_rc);
    }

    return MYLITE_OK;
}

static int execute_insert_select_insert_row(
    struct mylite_db *database,
    struct insert_select_execution_statements *statements,
    const struct planned_insert_select *plan,
    size_t row_number,
    struct insert_execution_counters *counters
) {
    struct planned_insert row_plan = plan->target;
    struct planned_insert_row row = {0};
    int rc = MYLITE_OK;

    row.values = calloc(plan->target.column_count, sizeof(*row.values));
    if (row.values == NULL) {
        set_nomem_error(database);
        return MYLITE_NOMEM;
    }

    rc = materialize_insert_select_row_values(
        database,
        statements->select_statement,
        plan,
        row_number,
        row.values
    );
    if (rc == MYLITE_OK) {
        row_plan.rows = &row;
        row_plan.row_count = 1U;
        rc = plan_insert_select_auto_increment_row_value(database, &row_plan, counters);
    }
    if (rc == MYLITE_OK) {
        rc = plan_insert_string_key_values(database, &row_plan);
    }
    if (rc == MYLITE_OK) {
        rc = execute_insert_plan_rows(database, statements->insert_statement, &row_plan, counters);
    }
    for (size_t column_index = 0U; column_index < plan->target.column_count; ++column_index) {
        planned_value_deinit(&row.values[column_index]);
    }
    free(row.values);

    return rc;
}

static int plan_insert_select_auto_increment_row_value(
    struct mylite_db *database,
    struct planned_insert *row_plan,
    struct insert_execution_counters *counters
) {
    int64_t next_value = 0;

    if (row_plan == NULL || counters == NULL || !row_plan->has_auto_increment) {
        return MYLITE_OK;
    }

    next_value = counters->auto_increment_next_after_rows;
    return plan_insert_auto_increment_row_value(
        database,
        row_plan,
        &row_plan->auto_increment_range,
        0U,
        &next_value
    );
}

static int materialize_insert_select_row_values(
    struct mylite_db *database,
    sqlite3_stmt *select_statement,
    const struct planned_insert_select *plan,
    size_t row_number,
    struct planned_value *values
) {
    int rc = MYLITE_OK;

    for (size_t column_index = 0U; rc == MYLITE_OK && column_index < plan->target.column_count;
         ++column_index) {
        size_t target_position = 0U;

        if (find_insert_select_target_position(plan, column_index, &target_position)) {
            if (target_position >= (size_t)INT_MAX) {
                return MYLITE_ERROR;
            }
            rc = materialize_insert_select_selected_value(
                database,
                select_statement,
                (int)target_position,
                &plan->target.columns[column_index],
                row_number,
                &values[column_index]
            );
        } else {
            rc = materialize_insert_select_omitted_value(
                database,
                &plan->target.columns[column_index],
                &values[column_index]
            );
        }
    }

    return rc;
}

static int materialize_insert_select_selected_value(
    struct mylite_db *database,
    sqlite3_stmt *statement,
    int selected_column_index,
    const struct mylite_catalog_column_descriptor *target_column,
    size_t row_number,
    struct planned_value *out_value
) {
    if (sqlite3_column_type(statement, selected_column_index) == SQLITE_NULL) {
        *out_value = (struct planned_value){.is_null = true};
        return MYLITE_OK;
    }
    if (column_descriptor_is_binary_string_family(target_column)) {
        return materialize_sqlite_binary_string_value(
            database,
            statement,
            selected_column_index,
            target_column,
            row_number,
            out_value
        );
    }
    if (column_descriptor_is_bit(target_column)) {
        return materialize_sqlite_bit_value(
            database,
            statement,
            selected_column_index,
            target_column,
            row_number,
            out_value
        );
    }

    return materialize_insert_select_raw_value(
        database,
        statement,
        selected_column_index,
        out_value
    );
}

static int materialize_sqlite_binary_string_value(
    struct mylite_db *database,
    sqlite3_stmt *statement,
    int selected_column_index,
    const struct mylite_catalog_column_descriptor *target_column,
    size_t row_number,
    struct planned_value *out_value
) {
    const void *bytes = sqlite3_column_blob(statement, selected_column_index);
    int byte_count = sqlite3_column_bytes(statement, selected_column_index);
    char *copy = NULL;
    size_t copy_length = 0U;
    int rc = MYLITE_OK;

    if ((bytes == NULL && byte_count != 0) || byte_count < 0) {
        set_physical_sqlite_row_error(database);
        return MYLITE_ERROR;
    }
    copy_length = (size_t)byte_count;
    copy = malloc(copy_length + 1U);
    if (copy == NULL) {
        set_nomem_error(database);
        return MYLITE_NOMEM;
    }
    if (copy_length != 0U) {
        memcpy(copy, bytes, copy_length);
    }
    copy[copy_length] = '\0';
    rc = convert_binary_bytes_for_column(
        database,
        target_column,
        row_number,
        false,
        &copy,
        &copy_length
    );
    if (rc != MYLITE_OK) {
        free(copy);
        return rc;
    }

    return assign_blob_value(database, copy, copy_length, out_value);
}

static int materialize_sqlite_bit_value(
    struct mylite_db *database,
    sqlite3_stmt *statement,
    int selected_column_index,
    const struct mylite_catalog_column_descriptor *target_column,
    size_t row_number,
    struct planned_value *out_value
) {
    const void *bytes = sqlite3_column_blob(statement, selected_column_index);
    int byte_count = sqlite3_column_bytes(statement, selected_column_index);
    int rc = validate_insert_select_bit_value(
        database,
        statement,
        selected_column_index,
        target_column,
        row_number
    );

    if (rc != MYLITE_OK) {
        return rc;
    }
    return copy_blob_value(database, bytes, (size_t)byte_count, out_value);
}

static int materialize_insert_select_raw_value(
    struct mylite_db *database,
    sqlite3_stmt *statement,
    int selected_column_index,
    struct planned_value *out_value
) {
    int sqlite_type = sqlite3_column_type(statement, selected_column_index);

    switch (sqlite_type) {
    case SQLITE_INTEGER:
        *out_value = (struct planned_value){
            .is_null = false,
            .is_text = false,
            .integer = (int64_t)sqlite3_column_int64(statement, selected_column_index),
        };
        return MYLITE_OK;
    case SQLITE_FLOAT:
        *out_value = (struct planned_value){
            .is_null = false,
            .is_text = false,
            .is_real = true,
            .real = sqlite3_column_double(statement, selected_column_index),
        };
        return MYLITE_OK;
    case SQLITE_TEXT: {
        const unsigned char *text = sqlite3_column_text(statement, selected_column_index);
        int byte_count = sqlite3_column_bytes(statement, selected_column_index);
        char *copy = NULL;

        if (text == NULL || byte_count < 0) {
            set_physical_sqlite_row_error(database);
            return MYLITE_ERROR;
        }
        copy = malloc((size_t)byte_count + 1U);
        if (copy == NULL) {
            set_nomem_error(database);
            return MYLITE_NOMEM;
        }
        memcpy(copy, text, (size_t)byte_count);
        copy[(size_t)byte_count] = '\0';
        return assign_text_value(database, copy, (size_t)byte_count, out_value);
    }
    case SQLITE_BLOB: {
        const void *bytes = sqlite3_column_blob(statement, selected_column_index);
        int byte_count = sqlite3_column_bytes(statement, selected_column_index);

        if ((bytes == NULL && byte_count != 0) || byte_count < 0) {
            set_physical_sqlite_row_error(database);
            return MYLITE_ERROR;
        }
        return copy_blob_value(database, bytes, (size_t)byte_count, out_value);
    }
    case SQLITE_NULL:
        *out_value = (struct planned_value){.is_null = true};
        return MYLITE_OK;
    default:
        set_physical_sqlite_row_error(database);
        return MYLITE_ERROR;
    }
}

static int materialize_insert_select_omitted_value(
    struct mylite_db *database,
    const struct mylite_catalog_column_descriptor *target_column,
    struct planned_value *out_value
) {
    if (column_descriptor_is_auto_increment(target_column)) {
        *out_value = (struct planned_value){.is_null = true};
        return MYLITE_OK;
    }

    return materialize_dml_default_value(database, target_column, false, out_value);
}

static int validate_insert_select_rows(
    struct mylite_db *database,
    sqlite3_stmt *statement,
    const struct planned_insert_select *plan
) {
    bool checked_omitted_columns = false;
    size_t row_number = 0U;
    int sqlite_rc = SQLITE_OK;
    int rc = MYLITE_OK;

    while ((sqlite_rc = sqlite3_step(statement)) == SQLITE_ROW) {
        if (!checked_omitted_columns) {
            rc = check_insert_omitted_columns(
                database,
                &plan->target,
                plan->target_indexes,
                plan->target_count
            );
            checked_omitted_columns = true;
        }
        if (rc == MYLITE_OK && row_number == SIZE_MAX) {
            set_unsupported_error(database, "INSERT ... SELECT selected too many rows");
            rc = MYLITE_ERROR;
        }
        if (rc == MYLITE_OK) {
            ++row_number;
            rc = validate_insert_select_row(database, statement, plan, row_number);
        }
        if (rc != MYLITE_OK) {
            return rc;
        }
    }
    if (sqlite_rc != SQLITE_DONE) {
        return mylite_sqlite_status_to_mylite(sqlite_rc);
    }

    return MYLITE_OK;
}

static int validate_insert_select_row(
    struct mylite_db *database,
    sqlite3_stmt *statement,
    const struct planned_insert_select *plan,
    size_t row_number
) {
    if (plan->target_count > (size_t)INT_MAX) {
        return MYLITE_ERROR;
    }
    for (size_t target_position = 0U; target_position < plan->target_count; ++target_position) {
        size_t column_index = plan->target_indexes[target_position];
        int rc = MYLITE_OK;

        if (column_descriptor_is_auto_increment(&plan->target.columns[column_index]) &&
            sqlite3_column_type(statement, (int)target_position) == SQLITE_NULL) {
            continue;
        }
        const struct mylite_catalog_column_descriptor *source_column =
            plan->source_kind == PLANNED_INSERT_SELECT_SOURCE_TABLE
                ? &plan->source.columns[target_position]
                : NULL;

        rc = validate_insert_select_value(
            database,
            statement,
            (int)target_position,
            source_column,
            &plan->target.columns[column_index],
            row_number
        );

        if (rc != MYLITE_OK) {
            return rc;
        }
    }

    return MYLITE_OK;
}

static int validate_insert_select_value(
    struct mylite_db *database,
    sqlite3_stmt *statement,
    int selected_column_index,
    const struct mylite_catalog_column_descriptor *source_column,
    const struct mylite_catalog_column_descriptor *target_column,
    size_t row_number
) {
    int sqlite_type = sqlite3_column_type(statement, selected_column_index);

    if (source_column != NULL &&
        !insert_select_source_target_types_are_compatible(source_column, target_column)) {
        set_unsupported_error(database, insert_select_implicit_conversion_message(target_column));
        return MYLITE_ERROR;
    }
    if (sqlite_type == SQLITE_NULL) {
        if (!target_column->is_nullable) {
            if (column_descriptor_is_spatial(target_column)) {
                set_spatial_bad_null_error(database, target_column->name);
                return MYLITE_ERROR;
            }
            set_bad_null_error(database, target_column->name);
            return MYLITE_ERROR;
        }
        return MYLITE_OK;
    }
    if (column_descriptor_is_string_family(target_column)) {
        return validate_insert_select_string_value(
            database,
            statement,
            selected_column_index,
            target_column,
            row_number
        );
    }
    if (column_descriptor_is_json(target_column)) {
        (void)row_number;
        return validate_insert_select_json_value(
            database,
            statement,
            selected_column_index,
            target_column
        );
    }
    if (column_descriptor_is_binary_string_family(target_column)) {
        return validate_insert_select_binary_string_value(
            database,
            statement,
            selected_column_index,
            target_column,
            row_number
        );
    }
    if (column_descriptor_is_bit(target_column)) {
        return validate_insert_select_bit_value(
            database,
            statement,
            selected_column_index,
            target_column,
            row_number
        );
    }
    if (column_descriptor_is_year(target_column)) {
        return validate_insert_select_year_value(
            database,
            statement,
            selected_column_index,
            target_column,
            row_number
        );
    }
    if (column_descriptor_is_decimal(target_column)) {
        return validate_insert_select_decimal_value(
            database,
            statement,
            selected_column_index,
            target_column,
            row_number
        );
    }
    if (column_descriptor_is_approximate(target_column)) {
        return validate_insert_select_approximate_value(
            database,
            statement,
            selected_column_index,
            target_column,
            row_number
        );
    }
    if (column_descriptor_is_date(target_column)) {
        return validate_insert_select_date_value(
            database,
            statement,
            selected_column_index,
            target_column,
            row_number
        );
    }
    if (column_descriptor_is_time(target_column)) {
        return validate_insert_select_time_value(
            database,
            statement,
            selected_column_index,
            target_column,
            row_number
        );
    }
    if (column_descriptor_is_datetime(target_column)) {
        return validate_insert_select_datetime_value(
            database,
            statement,
            selected_column_index,
            target_column,
            row_number
        );
    }
    if (column_descriptor_is_timestamp(target_column)) {
        return validate_insert_select_timestamp_value(
            database,
            statement,
            selected_column_index,
            target_column,
            row_number
        );
    }

    return validate_insert_select_integer_value(
        database,
        statement,
        selected_column_index,
        target_column,
        row_number
    );
}

static bool insert_select_source_target_types_are_compatible(
    const struct mylite_catalog_column_descriptor *source_column,
    const struct mylite_catalog_column_descriptor *target_column
) {
    if (source_column == NULL || target_column == NULL) {
        return false;
    }
    if (column_descriptor_is_string_family(target_column)) {
        return column_descriptor_is_string_family(source_column);
    }
    if (column_descriptor_is_json(target_column)) {
        return column_descriptor_is_json(source_column);
    }
    if (column_descriptor_is_enum(target_column)) {
        return false;
    }
    if (column_descriptor_is_set(target_column)) {
        return false;
    }
    if (column_descriptor_is_binary_string_family(target_column)) {
        return column_descriptor_is_binary_string_family(source_column);
    }
    if (column_descriptor_is_bit(target_column)) {
        return (column_descriptor_is_bit(source_column) &&
                strcmp(source_column->logical_type, target_column->logical_type) == 0) != 0;
    }
    if (column_descriptor_is_year(target_column)) {
        return column_descriptor_is_year(source_column);
    }
    if (column_descriptor_is_decimal(target_column)) {
        return column_descriptor_is_decimal(source_column);
    }
    if (column_descriptor_is_approximate(target_column)) {
        return (column_descriptor_is_approximate(source_column) &&
                strcmp(source_column->logical_type, target_column->logical_type) == 0) != 0;
    }
    if (column_descriptor_is_date(target_column)) {
        return column_descriptor_is_date(source_column);
    }
    if (column_descriptor_is_time(target_column)) {
        return column_descriptor_is_time(source_column);
    }
    if (column_descriptor_is_datetime(target_column)) {
        return column_descriptor_is_datetime(source_column);
    }
    if (column_descriptor_is_timestamp(target_column)) {
        return column_descriptor_is_timestamp(source_column);
    }

    return (source_column->physical_type[0] != '\0' &&
            strcmp(source_column->physical_type, "INTEGER") == 0) != 0;
}

static const char *insert_select_implicit_conversion_message(
    const struct mylite_catalog_column_descriptor *target_column
) {
    if (column_descriptor_is_string_family(target_column)) {
        return "INSERT ... SELECT does not support implicit string conversion";
    }
    if (column_descriptor_is_json(target_column)) {
        return "INSERT ... SELECT does not support implicit JSON conversion";
    }
    if (column_descriptor_is_enum(target_column)) {
        return "INSERT ... SELECT does not support implicit ENUM conversion";
    }
    if (column_descriptor_is_set(target_column)) {
        return "INSERT ... SELECT does not support implicit SET conversion";
    }
    if (column_descriptor_is_binary_string_family(target_column)) {
        return "INSERT ... SELECT does not support implicit binary string conversion";
    }
    if (column_descriptor_is_bit(target_column)) {
        return "INSERT ... SELECT does not support implicit BIT conversion";
    }
    if (column_descriptor_is_year(target_column)) {
        return "INSERT ... SELECT does not support implicit YEAR conversion";
    }
    if (column_descriptor_is_decimal(target_column)) {
        return "INSERT ... SELECT does not support implicit DECIMAL conversion";
    }
    if (column_descriptor_is_approximate(target_column)) {
        return "INSERT ... SELECT does not support implicit FLOAT or DOUBLE conversion";
    }
    if (column_descriptor_is_date(target_column)) {
        return "INSERT ... SELECT does not support implicit DATE conversion";
    }
    if (column_descriptor_is_time(target_column)) {
        return "INSERT ... SELECT does not support implicit TIME conversion";
    }
    if (column_descriptor_is_datetime(target_column)) {
        return "INSERT ... SELECT does not support implicit DATETIME conversion";
    }
    if (column_descriptor_is_timestamp(target_column)) {
        return "INSERT ... SELECT does not support implicit TIMESTAMP conversion";
    }

    return "INSERT ... SELECT does not support implicit integer conversion";
}

static int validate_insert_select_string_value(
    struct mylite_db *database,
    sqlite3_stmt *statement,
    int selected_column_index,
    const struct mylite_catalog_column_descriptor *target_column,
    size_t row_number
) {
    const unsigned char *text = NULL;
    int byte_count = 0;

    if (sqlite3_column_type(statement, selected_column_index) != SQLITE_TEXT) {
        set_unsupported_error(
            database,
            "INSERT ... SELECT does not support implicit string conversion"
        );
        return MYLITE_ERROR;
    }
    text = sqlite3_column_text(statement, selected_column_index);
    byte_count = sqlite3_column_bytes(statement, selected_column_index);
    if (text == NULL || byte_count < 0) {
        set_physical_sqlite_row_error(database);
        return MYLITE_ERROR;
    }
    if (column_descriptor_is_char(target_column)) {
        return validate_canonical_char_text(
            database,
            target_column,
            (struct varchar_text_validation){
                .text = (const char *)text,
                .text_length = (size_t)byte_count,
                .row_number = row_number,
            }
        );
    }
    if (column_descriptor_is_varchar(target_column)) {
        return validate_varchar_text(
            database,
            target_column,
            (struct varchar_text_validation){
                .text = (const char *)text,
                .text_length = (size_t)byte_count,
                .row_number = row_number,
            }
        );
    }
    return validate_text_family_text(
        database,
        target_column,
        (struct varchar_text_validation){
            .text = (const char *)text,
            .text_length = (size_t)byte_count,
            .row_number = row_number,
        }
    );
}

static int validate_insert_select_json_value(
    struct mylite_db *database,
    sqlite3_stmt *statement,
    int selected_column_index,
    const struct mylite_catalog_column_descriptor *target_column
) {
    const unsigned char *text = NULL;
    int byte_count = 0;
    char *normalized = NULL;
    size_t normalized_length = 0U;
    struct mylite_json_normalize_result result = {0};
    int rc = MYLITE_OK;

    if (sqlite3_column_type(statement, selected_column_index) != SQLITE_TEXT) {
        set_unsupported_error(
            database,
            "INSERT ... SELECT does not support implicit JSON conversion"
        );
        return MYLITE_ERROR;
    }
    text = sqlite3_column_text(statement, selected_column_index);
    byte_count = sqlite3_column_bytes(statement, selected_column_index);
    if (text == NULL || byte_count < 0) {
        set_physical_sqlite_row_error(database);
        return MYLITE_ERROR;
    }
    rc = mylite_json_normalize(
        (const char *)text,
        (size_t)byte_count,
        &normalized,
        &normalized_length,
        &result
    );
    if (rc == MYLITE_NOMEM) {
        set_nomem_error(database);
        return rc;
    }
    if (rc != MYLITE_OK) {
        if (result.status == MYLITE_JSON_NORMALIZE_UNSUPPORTED) {
            set_unsupported_error(database, "INSERT ... SELECT does not support this JSON value");
        } else {
            set_invalid_json_text_error(database, result.position, target_column->name);
        }
        return MYLITE_ERROR;
    }
    free(normalized);
    (void)normalized_length;
    return MYLITE_OK;
}

static int validate_insert_select_binary_string_value(
    struct mylite_db *database,
    sqlite3_stmt *statement,
    int selected_column_index,
    const struct mylite_catalog_column_descriptor *target_column,
    size_t row_number
) {
    const void *bytes = NULL;
    int byte_count = 0;
    char *copy = NULL;
    size_t copy_length = 0U;
    int rc = MYLITE_OK;

    if (sqlite3_column_type(statement, selected_column_index) != SQLITE_BLOB) {
        set_unsupported_error(
            database,
            "INSERT ... SELECT does not support implicit binary string conversion"
        );
        return MYLITE_ERROR;
    }
    bytes = sqlite3_column_blob(statement, selected_column_index);
    byte_count = sqlite3_column_bytes(statement, selected_column_index);
    if ((bytes == NULL && byte_count != 0) || byte_count < 0) {
        set_physical_sqlite_row_error(database);
        return MYLITE_ERROR;
    }
    copy_length = (size_t)byte_count;
    copy = malloc(copy_length + 1U);
    if (copy == NULL) {
        set_nomem_error(database);
        return MYLITE_NOMEM;
    }
    if (copy_length != 0U) {
        memcpy(copy, bytes, copy_length);
    }
    copy[copy_length] = '\0';
    rc = convert_binary_bytes_for_column(
        database,
        target_column,
        row_number,
        false,
        &copy,
        &copy_length
    );
    free(copy);
    return rc;
}

static int validate_insert_select_bit_value(
    struct mylite_db *database,
    sqlite3_stmt *statement,
    int selected_column_index,
    const struct mylite_catalog_column_descriptor *target_column,
    size_t row_number
) {
    const void *bytes = NULL;
    int byte_count = 0;
    uint64_t width = 0U;
    size_t expected_byte_count = 0U;
    unsigned char unused_mask = 0U;
    int rc = bit_width_for_logical_type(target_column->logical_type, &width);

    if (rc != MYLITE_OK || sqlite3_column_type(statement, selected_column_index) != SQLITE_BLOB) {
        set_unsupported_error(
            database,
            "INSERT ... SELECT does not support implicit BIT conversion"
        );
        return MYLITE_ERROR;
    }
    bytes = sqlite3_column_blob(statement, selected_column_index);
    byte_count = sqlite3_column_bytes(statement, selected_column_index);
    if ((bytes == NULL && byte_count != 0) || byte_count < 0) {
        set_physical_sqlite_row_error(database);
        return MYLITE_ERROR;
    }
    expected_byte_count = bit_byte_width(width);
    if ((size_t)byte_count != expected_byte_count) {
        set_data_too_long_error(database, target_column->name, row_number);
        return MYLITE_ERROR;
    }
    if ((width % byte_bit_count) != 0U && expected_byte_count > 0U) {
        unused_mask = (unsigned char)(byte_all_bits_mask << (width % byte_bit_count));
        if ((((const unsigned char *)bytes)[0] & unused_mask) != 0U) {
            set_data_too_long_error(database, target_column->name, row_number);
            return MYLITE_ERROR;
        }
    }
    return MYLITE_OK;
}

