static int append_parent_delete_target_sql(
    struct dynamic_string *string,
    const struct planned_delete *plan,
    size_t *next_parameter,
    bool *out_has_condition
) {
    int rc = MYLITE_OK;

    *out_has_condition = false;
    if (plan->is_joined) {
        rc = append_joined_parent_delete_target_sql(string, plan, next_parameter);
        *out_has_condition = rc == MYLITE_OK;
        return rc;
    }
    if (plan->limit.has_limit) {
        rc = dynamic_string_append(string, " WHERE ");
        if (rc == MYLITE_OK) {
            rc = append_foreign_key_column_reference(string, "p", plan->rowid_alias);
        }
        if (rc == MYLITE_OK) {
            rc = dynamic_string_append(string, " IN (SELECT ");
        }
        if (rc == MYLITE_OK) {
            rc = dynamic_string_append_quoted_identifier(string, plan->rowid_alias);
        }
        if (rc == MYLITE_OK) {
            rc = dynamic_string_append(string, " FROM ");
        }
        if (rc == MYLITE_OK) {
            rc = dynamic_string_append_quoted_identifier(string, plan->table.physical_name);
        }
        if (rc == MYLITE_OK) {
            rc = append_select_predicate_sql(string, &plan->predicate, next_parameter);
        }
        if (rc == MYLITE_OK) {
            rc = append_select_order_sql(string, &plan->order);
        }
        if (rc == MYLITE_OK) {
            rc = append_select_limit_sql(string, &plan->limit, next_parameter);
        }
        if (rc == MYLITE_OK) {
            rc = dynamic_string_append_char(string, ')');
        }
        *out_has_condition = rc == MYLITE_OK;
        return rc;
    }
    if (planned_select_predicate_has_expression(&plan->predicate)) {
        rc = append_select_predicate_sql(string, &plan->predicate, next_parameter);
        *out_has_condition = rc == MYLITE_OK;
    }
    return rc;
}

static int append_joined_parent_delete_target_sql(
    struct dynamic_string *string,
    const struct planned_delete *plan,
    size_t *next_parameter
) {
    int rc = dynamic_string_append(string, " WHERE ");

    if (rc == MYLITE_OK) {
        rc = append_foreign_key_column_reference(string, "p", plan->rowid_alias);
    }
    if (rc == MYLITE_OK) {
        rc = dynamic_string_append(string, " IN (");
    }
    if (rc == MYLITE_OK) {
        rc = append_joined_delete_rowid_subquery_sql(string, plan, next_parameter);
    }
    if (rc == MYLITE_OK) {
        rc = dynamic_string_append_char(string, ')');
    }

    return rc;
}

static int append_parent_child_match_sql(
    struct dynamic_string *string,
    bool has_parent_condition,
    const struct loaded_foreign_key_info *foreign_key
) {
    const char *prefix = " WHERE ";
    int rc = MYLITE_OK;

    if (has_parent_condition) {
        prefix = " AND ";
    }
    rc = dynamic_string_append(string, prefix);

    if (rc == MYLITE_OK) {
        rc = append_foreign_key_parent_match_checks(string, foreign_key);
    }
    return rc;
}

static int resolve_writable_table_name(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *node,
    struct table_name_resolution *out_resolution
) {
    int rc = reject_information_schema_write_target(database, node);

    if (rc != MYLITE_OK) {
        return rc;
    }

    return resolve_table_name(database, node, out_resolution);
}

static int resolve_table_name(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *node,
    struct table_name_resolution *out_resolution
) {
    char parts[table_name_part_capacity][MYLITE_CATALOG_IDENTIFIER_CAPACITY];
    size_t part_count = 0U;
    int rc = MYLITE_OK;

    *out_resolution = (struct table_name_resolution){0};
    rc = collect_identifier_parts(
        database == NULL ? NULL : node,
        parts,
        table_name_part_capacity,
        &part_count,
        database
    );
    if (rc != MYLITE_OK) {
        return rc;
    }
    if (part_count == 1U) {
        rc = resolve_selected_schema(database, &out_resolution->schema);
        if (rc == MYLITE_OK) {
            memcpy(out_resolution->table_name, parts[0], sizeof(out_resolution->table_name));
        }
        return rc;
    }
    if (part_count == 2U) {
        if (mylite_catalog_name_is_reserved(parts[0])) {
            set_reserved_name_error(database, "database", parts[0]);
            return MYLITE_ERROR;
        }
        rc = resolve_schema_name(database, parts[0], &out_resolution->schema);
        if (rc == MYLITE_OK) {
            memcpy(out_resolution->table_name, parts[1], sizeof(out_resolution->table_name));
        }
        return rc;
    }

    set_parse_error(database, NULL);

    return MYLITE_ERROR;
}

static int resolve_visible_writable_table_reference(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *node,
    struct table_name_resolution *out_resolution,
    struct mylite_catalog_table_descriptor *out_table
) {
    int rc = reject_information_schema_write_target(database, node);

    if (rc != MYLITE_OK) {
        return rc;
    }

    return resolve_visible_table_reference(database, node, out_resolution, out_table);
}

static int resolve_visible_table_reference(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *node,
    struct table_name_resolution *out_resolution,
    struct mylite_catalog_table_descriptor *out_table
) {
    bool missing_schema = false;
    int rc =
        resolve_table_name_allow_missing_schema(database, node, out_resolution, &missing_schema);

    if (rc == MYLITE_OK && mylite_catalog_name_is_reserved(out_resolution->table_name)) {
        set_reserved_name_error(database, "table", out_resolution->table_name);
        rc = MYLITE_ERROR;
    }
    if (rc == MYLITE_OK) {
        rc = resolve_readable_table(database, out_resolution, missing_schema, out_table);
    }
    return rc;
}

static int resolve_writable_table_name_allow_missing_schema(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *node,
    struct table_name_resolution *out_resolution,
    bool *out_missing_schema
) {
    int rc = reject_information_schema_write_target(database, node);

    if (rc != MYLITE_OK) {
        return rc;
    }

    return resolve_table_name_allow_missing_schema(
        database,
        node,
        out_resolution,
        out_missing_schema
    );
}

static int resolve_table_name_allow_missing_schema(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *node,
    struct table_name_resolution *out_resolution,
    bool *out_missing_schema
) {
    char parts[table_name_part_capacity][MYLITE_CATALOG_IDENTIFIER_CAPACITY];
    size_t part_count = 0U;
    int rc = MYLITE_OK;

    *out_resolution = (struct table_name_resolution){0};
    *out_missing_schema = false;
    rc = collect_identifier_parts(
        database == NULL ? NULL : node,
        parts,
        table_name_part_capacity,
        &part_count,
        database
    );
    if (rc != MYLITE_OK) {
        return rc;
    }
    if (part_count == 1U) {
        rc = resolve_selected_schema(database, &out_resolution->schema);
        if (rc == MYLITE_OK) {
            memcpy(out_resolution->table_name, parts[0], sizeof(out_resolution->table_name));
        }
        return rc;
    }
    if (part_count == 2U) {
        bool schema_found = false;

        if (mylite_catalog_name_is_reserved(parts[0])) {
            set_reserved_name_error(database, "database", parts[0]);
            return MYLITE_ERROR;
        }
        rc = mylite_catalog_try_read_schema_by_name(
            database,
            parts[0],
            &out_resolution->schema,
            &schema_found
        );
        memcpy(out_resolution->table_name, parts[1], sizeof(out_resolution->table_name));
        if (rc != MYLITE_OK) {
            set_internal_error_if_clear(database, rc, "failed to read schema descriptor");
            return rc;
        }
        if (!schema_found) {
            memcpy(out_resolution->schema.name, parts[0], sizeof(out_resolution->schema.name));
            *out_missing_schema = true;
        }
        return MYLITE_OK;
    }

    set_parse_error(database, NULL);
    return MYLITE_ERROR;
}

static int resolve_readable_table(
    struct mylite_db *database,
    const struct table_name_resolution *resolution,
    bool missing_schema,
    struct mylite_catalog_table_descriptor *out_table
) {
    bool found_temporary = false;
    int rc = mylite_temporary_catalog_try_read_table_by_name(
        &database->session.temporary_catalog,
        resolution->schema.name,
        resolution->table_name,
        out_table,
        &found_temporary
    );

    if (rc != MYLITE_OK) {
        set_internal_error_if_clear(database, rc, "failed to read temporary table descriptor");
        return rc;
    }
    if (found_temporary) {
        return MYLITE_OK;
    }
    if (missing_schema) {
        set_unknown_database_error(database, resolution->schema.name);
        return MYLITE_ERROR;
    }

    rc = mylite_catalog_read_table_by_name(
        database,
        resolution->schema.schema_id,
        resolution->table_name,
        out_table
    );
    if (rc != MYLITE_OK) {
        set_table_does_not_exist_error(database, resolution->schema.name, resolution->table_name);
        return MYLITE_ERROR;
    }
    if (out_table->kind != MYLITE_CATALOG_TABLE_KIND_BASE) {
        set_unsupported_error(database, "statement supports only persistent base tables");
        return MYLITE_ERROR;
    }

    return MYLITE_OK;
}

static int resolve_show_columns_table_name(
    struct mylite_db *database,
    struct show_columns_target_nodes nodes,
    struct table_name_resolution *out_resolution,
    bool *out_missing_schema
) {
    char schema_name[MYLITE_CATALOG_IDENTIFIER_CAPACITY];
    int rc = MYLITE_OK;

    *out_resolution = (struct table_name_resolution){0};
    *out_missing_schema = false;
    if (nodes.schema == NULL) {
        rc = resolve_table_name_allow_missing_schema(
            database,
            nodes.table,
            out_resolution,
            out_missing_schema
        );
    } else {
        bool schema_found = false;

        rc = copy_identifier_text(nodes.schema, schema_name, sizeof(schema_name), database);
        if (rc == MYLITE_OK && mylite_catalog_name_is_reserved(schema_name)) {
            set_reserved_name_error(database, "database", schema_name);
            rc = MYLITE_ERROR;
        }
        if (rc == MYLITE_OK) {
            rc = mylite_catalog_try_read_schema_by_name(
                database,
                schema_name,
                &out_resolution->schema,
                &schema_found
            );
            if (rc != MYLITE_OK) {
                set_internal_error_if_clear(database, rc, "failed to read schema descriptor");
                return rc;
            }
            if (!schema_found) {
                memcpy(
                    out_resolution->schema.name,
                    schema_name,
                    sizeof(out_resolution->schema.name)
                );
                *out_missing_schema = true;
            }
        }
        if (rc == MYLITE_OK) {
            rc = copy_show_columns_explicit_table_name(
                database,
                nodes.table,
                out_resolution->table_name,
                sizeof(out_resolution->table_name)
            );
        }
    }
    if (rc == MYLITE_OK && mylite_catalog_name_is_reserved(out_resolution->table_name)) {
        set_reserved_name_error(database, "table", out_resolution->table_name);
        rc = MYLITE_ERROR;
    }

    return rc;
}

static int copy_show_columns_explicit_table_name(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *table_node,
    char *destination,
    size_t destination_size
) {
    char parts[table_name_part_capacity][MYLITE_CATALOG_IDENTIFIER_CAPACITY];
    size_t part_count = 0U;
    int rc = MYLITE_OK;

    if (destination == NULL || destination_size < MYLITE_CATALOG_IDENTIFIER_CAPACITY) {
        set_parse_error(database, NULL);
        return MYLITE_ERROR;
    }

    rc = collect_identifier_parts(
        table_node,
        parts,
        table_name_part_capacity,
        &part_count,
        database
    );
    if (rc != MYLITE_OK) {
        return rc;
    }
    if (part_count == 0U || part_count > 2U) {
        set_parse_error(database, NULL);
        return MYLITE_ERROR;
    }

    memcpy(destination, parts[part_count - 1U], MYLITE_CATALOG_IDENTIFIER_CAPACITY);
    return MYLITE_OK;
}

static int resolve_writable_truncate_table_name(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *node,
    struct table_name_resolution *out_resolution
) {
    int rc = reject_information_schema_write_target(database, node);

    if (rc != MYLITE_OK) {
        return rc;
    }

    return resolve_truncate_table_name(database, node, out_resolution);
}

static int resolve_truncate_table_name(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *node,
    struct table_name_resolution *out_resolution
) {
    char parts[table_name_part_capacity][MYLITE_CATALOG_IDENTIFIER_CAPACITY];
    size_t part_count = 0U;
    int rc = MYLITE_OK;

    *out_resolution = (struct table_name_resolution){0};
    rc = collect_identifier_parts(
        database == NULL ? NULL : node,
        parts,
        table_name_part_capacity,
        &part_count,
        database
    );
    if (rc != MYLITE_OK) {
        return rc;
    }
    if (part_count == 1U) {
        rc = resolve_selected_schema(database, &out_resolution->schema);
        if (rc == MYLITE_OK) {
            memcpy(out_resolution->table_name, parts[0], sizeof(out_resolution->table_name));
        }
        return rc;
    }
    if (part_count == 2U) {
        if (mylite_catalog_name_is_reserved(parts[0])) {
            set_reserved_name_error(database, "database", parts[0]);
            return MYLITE_ERROR;
        }
        rc = mylite_catalog_read_schema_by_name(database, parts[0], &out_resolution->schema);
        if (rc != MYLITE_OK) {
            memcpy(out_resolution->schema.name, parts[0], sizeof(out_resolution->schema.name));
            set_table_does_not_exist_error(database, parts[0], parts[1]);
            return MYLITE_ERROR;
        }
        memcpy(out_resolution->table_name, parts[1], sizeof(out_resolution->table_name));
        return MYLITE_OK;
    }

    set_parse_error(database, NULL);

    return MYLITE_ERROR;
}

static int reject_information_schema_write_target(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *node
) {
    char parts[table_name_part_capacity][MYLITE_CATALOG_IDENTIFIER_CAPACITY];
    size_t part_count = 0U;
    int rc = collect_identifier_parts(
        database == NULL ? NULL : node,
        parts,
        table_name_part_capacity,
        &part_count,
        database
    );

    if (rc != MYLITE_OK) {
        return rc;
    }
    if ((part_count == 2U && schema_name_is_information_schema(parts[0])) ||
        (part_count == 1U && selected_schema_is_information_schema(database))) {
        set_database_access_denied_error(database, "information_schema");
        return MYLITE_ERROR;
    }

    return MYLITE_OK;
}

static int reject_information_schema_schema_write_name(
    struct mylite_db *database,
    const char *schema_name
) {
    if (schema_name_is_information_schema(schema_name)) {
        set_database_access_denied_error(database, "information_schema");
        return MYLITE_ERROR;
    }

    return MYLITE_OK;
}

static bool selected_schema_is_information_schema(const struct mylite_db *database) {
    if (database == NULL || !database->session.has_selected_schema) {
        return false;
    }

    return schema_name_is_information_schema(database->session.selected_schema);
}

static bool schema_name_is_information_schema(const char *schema_name) {
    return text_equals_ascii_case_insensitive(schema_name, "information_schema");
}

static int require_selected_schema_for_unqualified_table_name(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *node
) {
    char parts[table_name_part_capacity][MYLITE_CATALOG_IDENTIFIER_CAPACITY];
    size_t part_count = 0U;
    int rc = collect_identifier_parts(
        database == NULL ? NULL : node,
        parts,
        table_name_part_capacity,
        &part_count,
        database
    );

    if (rc != MYLITE_OK) {
        return rc;
    }
    if (part_count == 1U && (database == NULL || !database->session.has_selected_schema)) {
        set_no_database_error(database);
        return MYLITE_ERROR;
    }

    return MYLITE_OK;
}

static int resolve_schema_name(
    struct mylite_db *database,
    const char *schema_name,
    struct mylite_catalog_schema_descriptor *out_schema
) {
    int rc = mylite_catalog_read_schema_by_name(database, schema_name, out_schema);

    if (rc != MYLITE_OK) {
        set_unknown_database_error(database, schema_name);
        return MYLITE_ERROR;
    }

    return MYLITE_OK;
}

static int resolve_selected_schema(
    struct mylite_db *database,
    struct mylite_catalog_schema_descriptor *out_schema
) {
    if (database == NULL || !database->session.has_selected_schema) {
        set_no_database_error(database);
        return MYLITE_ERROR;
    }

    return resolve_schema_name(database, database->session.selected_schema, out_schema);
}

static int collect_identifier_parts(
    const struct mylite_sql_ast_node *node,
    char parts[][MYLITE_CATALOG_IDENTIFIER_CAPACITY],
    size_t part_capacity,
    size_t *part_count,
    struct mylite_db *database
) {
    const struct mylite_sql_ast_node *tail_nodes[table_name_part_capacity];
    const struct mylite_sql_ast_node *current = node;
    size_t tail_count = 0U;
    int rc = MYLITE_OK;

    if (current == NULL || part_count == NULL) {
        set_parse_error(database, NULL);
        return MYLITE_ERROR;
    }

    while (current->kind == MYLITE_SQL_AST_QUALIFIED_IDENTIFIER) {
        if (tail_count >= part_capacity || tail_count >= table_name_part_capacity) {
            set_parse_error(database, NULL);
            return MYLITE_ERROR;
        }
        tail_nodes[tail_count] = child_at(current, 1U);
        ++tail_count;
        current = child_at(current, 0U);
        if (current == NULL) {
            set_parse_error(database, NULL);
            return MYLITE_ERROR;
        }
    }

    if (current->kind != MYLITE_SQL_AST_IDENTIFIER) {
        set_parse_error(database, NULL);
        return MYLITE_ERROR;
    }
    if (*part_count >= part_capacity) {
        set_parse_error(database, NULL);
        return MYLITE_ERROR;
    }
    rc = copy_identifier_text(
        current,
        parts[*part_count],
        MYLITE_CATALOG_IDENTIFIER_CAPACITY,
        database
    );
    if (rc != MYLITE_OK) {
        return MYLITE_ERROR;
    }
    ++(*part_count);

    while (tail_count > 0U) {
        --tail_count;
        if (*part_count >= part_capacity) {
            set_parse_error(database, NULL);
            return MYLITE_ERROR;
        }
        rc = copy_identifier_text(
            tail_nodes[tail_count],
            parts[*part_count],
            MYLITE_CATALOG_IDENTIFIER_CAPACITY,
            database
        );
        if (rc != MYLITE_OK) {
            return MYLITE_ERROR;
        }
        ++(*part_count);
    }

    return MYLITE_OK;
}

static int copy_identifier_text(
    const struct mylite_sql_ast_node *node,
    char *destination,
    size_t destination_size,
    struct mylite_db *database
) {
    const char *source = NULL;
    size_t source_size = 0U;
    int rc = MYLITE_OK;

    if (node == NULL || node->kind != MYLITE_SQL_AST_IDENTIFIER || destination == NULL) {
        set_parse_error(database, NULL);
        return MYLITE_ERROR;
    }

    source = node->span.text;
    source_size = node->span.length;
    if (source == NULL || source_size == 0U) {
        set_parse_error(database, NULL);
        return MYLITE_ERROR;
    }

    if (source[0] == '`') {
        rc = copy_quoted_identifier_text(source, source_size, destination, destination_size);
    } else {
        rc = copy_unquoted_identifier_text(source, source_size, destination, destination_size);
    }
    if (rc != MYLITE_OK) {
        set_identifier_too_long_error(database, "identifier");
        return rc;
    }

    return MYLITE_OK;
}

static int copy_quoted_identifier_text(
    const char *source,
    size_t source_size,
    char *destination,
    size_t destination_size
) {
    size_t destination_index = 0U;

    if (source_size < 2U || source[source_size - 1U] != '`') {
        return MYLITE_ERROR;
    }

    for (size_t source_index = 1U; source_index + 1U < source_size; ++source_index) {
        if (destination_index + 1U >= destination_size) {
            return MYLITE_ERROR;
        }
        if (source[source_index] == '`' && source[source_index + 1U] == '`') {
            destination[destination_index] = '`';
            ++source_index;
        } else {
            destination[destination_index] = source[source_index];
        }
        ++destination_index;
    }
    destination[destination_index] = '\0';

    return destination_index == 0U ? MYLITE_ERROR : MYLITE_OK;
}

static int copy_unquoted_identifier_text(
    const char *source,
    size_t source_size,
    char *destination,
    size_t destination_size
) {
    if (source_size == 0U || source_size >= destination_size) {
        return MYLITE_ERROR;
    }

    memcpy(destination, source, source_size);
    destination[source_size] = '\0';

    return MYLITE_OK;
}

static int plan_column(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *column_node,
    struct planned_column *out_column
) {
    const struct mylite_sql_ast_node *type_node = NULL;
    const struct mylite_sql_ast_node *nullability_node = NULL;
    int rc = MYLITE_OK;

    *out_column = (struct planned_column){0};
    rc = copy_identifier_text(
        child_at(column_node, 0U),
        out_column->name,
        sizeof(out_column->name),
        database
    );
    if (rc == MYLITE_OK && mylite_catalog_name_is_reserved(out_column->name)) {
        set_reserved_name_error(database, "column", out_column->name);
        rc = MYLITE_ERROR;
    }
    if (rc == MYLITE_OK) {
        type_node = child_at(column_node, 1U);
        rc = map_column_type(database, type_node, out_column->name, out_column);
    }
    if (rc == MYLITE_OK) {
        const bool has_auto_increment_attribute =
            child_with_kind(column_node, MYLITE_SQL_AST_COLUMN_AUTO_INCREMENT) != NULL;
        out_column->is_serial_alias =
            mylite_sql_ast_node_integer_type_is_serial_alias(type_node) != 0;
        out_column->is_auto_increment = out_column->is_serial_alias;
        if (has_auto_increment_attribute) {
            out_column->is_auto_increment = true;
        }
        if (out_column->is_serial_alias) {
            out_column->is_unique_key = true;
        }
    }
    if (rc == MYLITE_OK) {
        nullability_node = child_with_kind(column_node, MYLITE_SQL_AST_NULLABILITY);
        out_column->nullability = mylite_sql_ast_node_nullability(nullability_node);
        out_column->is_nullable = column_is_nullable(nullability_node);
        out_column->is_visible = true;
    }
    if (rc == MYLITE_OK && out_column->is_auto_increment &&
        out_column->nullability == MYLITE_SQL_AST_NULLABILITY_UNSPECIFIED) {
        out_column->is_nullable = false;
    }
    if (rc == MYLITE_OK) {
        rc = apply_column_charset_collation_attributes(database, column_node, out_column);
    }
    if (rc == MYLITE_OK) {
        out_column->default_node = child_with_kind(column_node, MYLITE_SQL_AST_COLUMN_DEFAULT_NULL);
        if (out_column->default_node == NULL) {
            out_column->default_node =
                child_with_kind(column_node, MYLITE_SQL_AST_COLUMN_DEFAULT_VALUE);
        }
        out_column->on_update_current_timestamp =
            child_with_kind(column_node, MYLITE_SQL_AST_COLUMN_ON_UPDATE_CURRENT_TIMESTAMP) != NULL;
        rc = validate_column_default(database, out_column->default_node, out_column);
    }
    if (rc == MYLITE_OK) {
        rc = apply_column_comment_attributes(database, column_node, out_column);
    }
    if (rc == MYLITE_OK) {
        rc = validate_column_attributes(database, column_node, out_column);
    }

    return rc;
}

static int apply_column_comment_attributes(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *column_node,
    struct planned_column *column
) {
    const struct mylite_sql_ast_node *child = child_at(column_node, 2U);

    column->comment[0] = '\0';
    while (child != NULL) {
        if (child->kind == MYLITE_SQL_AST_COLUMN_COMMENT_ATTRIBUTE) {
            char *decoded = NULL;
            size_t decoded_length = 0U;
            size_t decoded_character_count = 0U;
            int rc = decode_table_option_string_literal(
                database,
                child_at(child, 0U),
                &decoded,
                (struct table_option_name_policy){
                    .identifier_kind = "column comment",
                    .nul_message = "column comments do not support NUL bytes",
                }
            );

            if (rc != MYLITE_OK) {
                return rc;
            }
            decoded_length = strlen(decoded);
            if (validate_utf8_text(decoded, decoded_length, &decoded_character_count) !=
                MYLITE_OK) {
                free(decoded);
                set_unsupported_error(database, "column comments support only valid UTF-8 text");
                return MYLITE_ERROR;
            }
            if (decoded_character_count > MYLITE_CATALOG_COLUMN_COMMENT_MAX_CHARACTERS ||
                decoded_length >= sizeof(column->comment)) {
                free(decoded);
                set_column_comment_too_long_error(database, column->name);
                return MYLITE_ERROR;
            }
            memcpy(column->comment, decoded, decoded_length + 1U);
            free(decoded);
        }
        child = child->next_sibling;
    }

    return MYLITE_OK;
}

static int validate_column_attributes(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *column_node,
    const struct planned_column *column
) {
    const struct mylite_sql_ast_node *child = child_at(column_node, 2U);
    size_t nullability_count = 0U;
    size_t default_count = 0U;
    size_t primary_key_count = 0U;
    size_t auto_increment_count = 0U;
    size_t on_update_count = 0U;
    size_t charset_count = 0U;
    size_t collation_count = 0U;
    bool previous_attribute_allows_check_enforcement = false;

    while (child != NULL) {
        if (child->kind == MYLITE_SQL_AST_NULLABILITY) {
            ++nullability_count;
            previous_attribute_allows_check_enforcement = false;
        } else if (
            child->kind == MYLITE_SQL_AST_COLUMN_DEFAULT_NULL ||
            child->kind == MYLITE_SQL_AST_COLUMN_DEFAULT_VALUE
        ) {
            ++default_count;
            previous_attribute_allows_check_enforcement = false;
        } else if (child->kind == MYLITE_SQL_AST_INLINE_PRIMARY_KEY) {
            ++primary_key_count;
            previous_attribute_allows_check_enforcement = false;
        } else if (
            child->kind == MYLITE_SQL_AST_INLINE_UNIQUE_KEY ||
            child->kind == MYLITE_SQL_AST_COLUMN_COMMENT_ATTRIBUTE
        ) {
            previous_attribute_allows_check_enforcement = false;
        } else if (child->kind == MYLITE_SQL_AST_COLUMN_AUTO_INCREMENT) {
            ++auto_increment_count;
            previous_attribute_allows_check_enforcement = false;
        } else if (child->kind == MYLITE_SQL_AST_COLUMN_ON_UPDATE_CURRENT_TIMESTAMP) {
            ++on_update_count;
            previous_attribute_allows_check_enforcement = false;
        } else if (child->kind == MYLITE_SQL_AST_COLUMN_CHARSET_ATTRIBUTE) {
            ++charset_count;
            previous_attribute_allows_check_enforcement = false;
        } else if (child->kind == MYLITE_SQL_AST_COLUMN_COLLATION_ATTRIBUTE) {
            ++collation_count;
            previous_attribute_allows_check_enforcement = false;
        } else if (child->kind == MYLITE_SQL_AST_CHECK_CONSTRAINT_DEFINITION) {
            /* Column CHECK attributes are planned after all columns are known. */
            previous_attribute_allows_check_enforcement = true;
        } else if (check_constraint_node_is_enforcement(child)) {
            if (!previous_attribute_allows_check_enforcement) {
                set_parse_error(database, NULL);
                return MYLITE_ERROR;
            }
            previous_attribute_allows_check_enforcement = false;
        } else {
            set_parse_error(database, NULL);
            return MYLITE_ERROR;
        }
        child = child->next_sibling;
    }

    if (nullability_count > 1U || default_count > 1U || primary_key_count > 1U ||
        auto_increment_count > 1U || on_update_count > 1U || charset_count > 1U ||
        collation_count > 1U) {
        set_unsupported_error(database, "duplicate column attributes are not supported");
        return MYLITE_ERROR;
    }
    if (column != NULL && column->is_auto_increment && column->default_node != NULL) {
        set_invalid_default_error(database, column->name);
        return MYLITE_ERROR;
    }
    if (column != NULL && column->on_update_current_timestamp &&
        !planned_column_is_datetime(column) && !planned_column_is_timestamp(column)) {
        set_invalid_default_error(database, column->name);
        return MYLITE_ERROR;
    }
    return MYLITE_OK;
}

static int apply_column_charset_collation_attributes(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *column_node,
    struct planned_column *column
) {
    const struct mylite_sql_ast_node *charset_attribute =
        child_with_kind(column_node, MYLITE_SQL_AST_COLUMN_CHARSET_ATTRIBUTE);
    const struct mylite_sql_ast_node *collation_attribute =
        child_with_kind(column_node, MYLITE_SQL_AST_COLUMN_COLLATION_ATTRIBUTE);
    char charset_name[MYLITE_CATALOG_IDENTIFIER_CAPACITY] = "";
    char collation_name[MYLITE_CATALOG_IDENTIFIER_CAPACITY] = "";
    bool has_charset = charset_attribute != NULL;
    bool has_collation = collation_attribute != NULL;
    int rc = MYLITE_OK;

    column->character_set_name[0] = '\0';
    column->collation_name[0] = '\0';
    if (!has_charset && !has_collation) {
        return MYLITE_OK;
    }
    if (planned_column_is_national_char_or_varchar(column)) {
        set_unsupported_error(
            database,
            "NATIONAL character columns do not support explicit column charset or collation"
        );
        return MYLITE_ERROR;
    }
    if (!planned_column_allows_charset_collation_attributes(column)) {
        set_unsupported_error(
            database,
            "column charset and collation attributes support only CHAR, VARCHAR, and TEXT columns"
        );
        return MYLITE_ERROR;
    }

    if (has_charset) {
        rc = copy_column_charset_attribute_name(
            database,
            charset_attribute,
            charset_name,
            sizeof(charset_name)
        );
    }
    if (rc == MYLITE_OK && has_collation) {
        rc = copy_column_collation_attribute_name(
            database,
            collation_attribute,
            collation_name,
            sizeof(collation_name)
        );
    }
    if (rc == MYLITE_OK && column_charset_collation_requests_binary(
                               has_charset,
                               charset_name,
                               has_collation,
                               collation_name
                           )) {
        return apply_column_binary_charset_collation_attributes(
            database,
            column,
            has_charset,
            charset_name,
            has_collation,
            collation_name
        );
    }
    if (rc == MYLITE_OK) {
        rc = validate_table_charset_collation_option_values(
            database,
            has_charset,
            charset_name,
            has_collation,
            collation_name
        );
    }
    if (rc != MYLITE_OK) {
        return rc;
    }

    if (has_charset) {
        rc = copy_normalized_charset_name(
            database,
            charset_name,
            column->character_set_name,
            sizeof(column->character_set_name)
        );
    }
    if (rc == MYLITE_OK && has_collation) {
        const struct collation_descriptor *collation = collation_by_name(collation_name);

        if (collation == NULL) {
            set_unknown_collation_error(database, collation_name);
            return MYLITE_ERROR;
        }
        if (!has_charset) {
            rc = copy_normalized_charset_name(
                database,
                collation->character_set,
                column->character_set_name,
                sizeof(column->character_set_name)
            );
        }
        if (rc != MYLITE_OK) {
            return rc;
        }
        snprintf(column->collation_name, sizeof(column->collation_name), "%s", collation->name);
    }

    return MYLITE_OK;
}

static bool column_charset_collation_requests_binary(
    bool has_charset,
    const char *charset_name,
    bool has_collation,
    const char *collation_name
) {
    return ((has_charset && charset_name_is_binary(charset_name)) ||
            (has_collation && collation_name_is_binary(collation_name))) != 0;
}

static int apply_column_binary_charset_collation_attributes(
    struct mylite_db *database,
    struct planned_column *column,
    bool has_charset,
    const char *charset_name,
    bool has_collation,
    const char *collation_name
) {
    int rc = validate_column_binary_charset_collation_attributes(
        database,
        has_charset,
        charset_name,
        has_collation,
        collation_name
    );

    if (rc != MYLITE_OK) {
        return rc;
    }
    rc = normalize_column_to_binary_string_descriptor(database, column);
    if (rc != MYLITE_OK) {
        return rc;
    }

    column->character_set_name[0] = '\0';
    column->collation_name[0] = '\0';
    return MYLITE_OK;
}

static int validate_column_binary_charset_collation_attributes(
    struct mylite_db *database,
    bool has_charset,
    const char *charset_name,
    bool has_collation,
    const char *collation_name
) {
    bool charset_is_binary = false;
    bool charset_is_supported = false;
    bool charset_is_known_unsupported = false;
    bool collation_is_binary = false;
    bool collation_is_supported = false;
    bool collation_is_known_unsupported = false;

    if (has_charset) {
        charset_is_binary = charset_name_is_binary(charset_name);
        if (character_set_by_name(charset_name) != NULL || charset_is_binary) {
            charset_is_supported = true;
        }
        charset_is_known_unsupported = charset_name_is_known_unsupported(charset_name);
    }
    if (has_collation) {
        collation_is_binary = collation_name_is_binary(collation_name);
        if (collation_by_name(collation_name) != NULL || collation_is_binary) {
            collation_is_supported = true;
        }
        collation_is_known_unsupported = collation_name_is_known_unsupported(collation_name);
    }

    if (has_charset && !charset_is_binary && !charset_is_supported &&
        !charset_is_known_unsupported) {
        set_unknown_character_set_error(database, charset_name);
        return MYLITE_ERROR;
    }
    if (has_collation && !collation_is_binary && !collation_is_supported &&
        !collation_is_known_unsupported) {
        set_unknown_collation_error(database, collation_name);
        return MYLITE_ERROR;
    }
    if (has_charset && has_collation && charset_is_binary != collation_is_binary) {
        set_collation_not_valid_for_charset_error(database, collation_name, charset_name);
        return MYLITE_ERROR;
    }

    return MYLITE_OK;
}

static int normalize_column_to_binary_string_descriptor(
    struct mylite_db *database,
    struct planned_column *column
) {
    static const char unsupported_message[] =
        "column binary charset supports only baseline CHAR, VARCHAR, and TEXT descriptors";
    size_t length = 0U;
    int rc = MYLITE_OK;

    if (planned_column_is_char(column)) {
        rc = parse_char_descriptor_length(
            database,
            column->logical_type,
            unsupported_message,
            &length
        );
        if (rc != MYLITE_OK) {
            return rc;
        }
        return assign_binary_descriptor_type(
            database,
            column,
            "BINARY(%" PRIu64 ")",
            (uint64_t)length
        );
    }
    if (planned_column_is_varchar(column)) {
        rc = parse_varchar_descriptor_length(
            database,
            column->logical_type,
            unsupported_message,
            &length
        );
        if (rc != MYLITE_OK) {
            return rc;
        }
        return assign_binary_descriptor_type(
            database,
            column,
            "VARBINARY(%" PRIu64 ")",
            (uint64_t)length
        );
    }
    if (planned_column_is_text_family(column)) {
        return normalize_column_to_binary_text_descriptor(database, column);
    }

    set_unsupported_error(database, unsupported_message);
    return MYLITE_ERROR;
}

static int normalize_column_to_binary_text_descriptor(
    struct mylite_db *database,
    struct planned_column *column
) {
    const char *logical_type = NULL;

    if (strcmp(column->logical_type, "TINYTEXT") == 0) {
        logical_type = "TINYBLOB";
    } else if (strcmp(column->logical_type, "TEXT") == 0) {
        logical_type = "BLOB";
    } else if (strcmp(column->logical_type, "MEDIUMTEXT") == 0) {
        logical_type = "MEDIUMBLOB";
    } else if (strcmp(column->logical_type, "LONGTEXT") == 0) {
        logical_type = "LONGBLOB";
    }
    if (logical_type == NULL) {
        set_unsupported_error(
            database,
            "column binary charset supports only baseline TEXT descriptors"
        );
        return MYLITE_ERROR;
    }

    snprintf(
        column->logical_type_storage,
        sizeof(column->logical_type_storage),
        "%s",
        logical_type
    );
    snprintf(column->physical_type_storage, sizeof(column->physical_type_storage), "BLOB");
    column->logical_type = column->logical_type_storage;
    column->physical_type = column->physical_type_storage;
    return MYLITE_OK;
}

static int copy_column_charset_attribute_name(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *charset_attribute,
    char *charset_name,
    size_t charset_name_size
) {
    if (charset_attribute == NULL ||
        charset_attribute->kind != MYLITE_SQL_AST_COLUMN_CHARSET_ATTRIBUTE) {
        set_parse_error(database, NULL);
        return MYLITE_ERROR;
    }
    return copy_table_option_name_text(
        database,
        child_at(charset_attribute, 0U),
        charset_name,
        charset_name_size,
        (struct table_option_name_policy){
            .identifier_kind = "character set",
            .nul_message = "column character set names do not support NUL bytes",
        }
    );
}

static int copy_column_collation_attribute_name(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *collation_attribute,
    char *collation_name,
    size_t collation_name_size
) {
    if (collation_attribute == NULL ||
        collation_attribute->kind != MYLITE_SQL_AST_COLUMN_COLLATION_ATTRIBUTE) {
        set_parse_error(database, NULL);
        return MYLITE_ERROR;
    }
    return copy_table_option_name_text(
        database,
        child_at(collation_attribute, 0U),
        collation_name,
        collation_name_size,
        (struct table_option_name_policy){
            .identifier_kind = "collation",
            .nul_message = "column collation names do not support NUL bytes",
        }
    );
}

static bool planned_column_allows_charset_collation_attributes(
    const struct planned_column *column
) {
    return (planned_column_is_char(column) || planned_column_is_varchar(column) ||
            planned_column_is_text_family(column)) != 0;
}

static bool planned_column_is_national_char_or_varchar(const struct planned_column *column) {
    if (column == NULL || column->logical_type == NULL || column->physical_type == NULL) {
        return false;
    }
    if (strcmp(column->physical_type, "TEXT") != 0) {
        return false;
    }
    return logical_type_is_national_char_or_varchar(column->logical_type);
}

static int validate_column_default(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *default_node,
    const struct planned_column *column
) {
    if (default_node == NULL) {
        return MYLITE_OK;
    }
    if (default_node->kind == MYLITE_SQL_AST_COLUMN_DEFAULT_VALUE) {
        return validate_column_default_value(database, default_node, column);
    }
    if (default_node->kind != MYLITE_SQL_AST_COLUMN_DEFAULT_NULL) {
        set_parse_error(database, NULL);
        return MYLITE_ERROR;
    }
    if (!column->is_nullable) {
        set_invalid_default_error(database, column->name);
        return MYLITE_ERROR;
    }

    return MYLITE_OK;
}

static int validate_column_default_value(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *default_node,
    const struct planned_column *column
) {
    const struct mylite_sql_ast_node *value_node = child_at(default_node, 0U);

    if (value_node != NULL && value_node->kind == MYLITE_SQL_AST_CURRENT_TIMESTAMP_VALUE) {
        if (planned_column_is_datetime(column) || planned_column_is_timestamp(column)) {
            return MYLITE_OK;
        }
        set_invalid_default_error(database, column->name);
        return MYLITE_ERROR;
    }
    if (column_default_value_is_current_date_expression(value_node)) {
        if (planned_column_is_date(column)) {
            return MYLITE_OK;
        }
        set_invalid_default_error(database, column->name);
        return MYLITE_ERROR;
    }
    if (column_default_value_is_current_time_expression(value_node)) {
        if (planned_column_is_time(column)) {
            return MYLITE_OK;
        }
        set_invalid_default_error(database, column->name);
        return MYLITE_ERROR;
    }
    if (planned_column_is_text_family(column)) {
        if (column_default_value_is_parenthesized_text_expression(default_node)) {
            return MYLITE_OK;
        }
        set_invalid_default_error(database, column->name);
        return MYLITE_ERROR;
    }
    if (planned_column_is_binary_string_family(column)) {
        set_invalid_default_error(database, column->name);
        return MYLITE_ERROR;
    }
    if (planned_column_is_spatial(column)) {
        set_json_cant_have_default_error(database, column->name);
        return MYLITE_ERROR;
    }
    if (planned_column_is_json(column)) {
        if (column_default_value_is_parenthesized_expression(default_node)) {
            set_unsupported_error(database, "JSON expression defaults are not yet supported");
            return MYLITE_ERROR;
        }
        set_json_cant_have_default_error(database, column->name);
        return MYLITE_ERROR;
    }
    return MYLITE_OK;
}

static int finalize_planned_column_defaults(
    struct mylite_db *database,
    struct planned_column *columns,
    size_t column_count
) {
    for (size_t column_index = 0U; column_index < column_count; ++column_index) {
        int rc = finalize_planned_column_default(database, &columns[column_index]);

        if (rc != MYLITE_OK) {
            return rc;
        }
    }

    return MYLITE_OK;
}

static int finalize_planned_column_default(
    struct mylite_db *database,
    struct planned_column *column
) {
    const struct mylite_sql_ast_node *value_node = NULL;

    column->default_kind = MYLITE_CATALOG_COLUMN_DEFAULT_NONE;
    column->default_integer = 0;
    column->default_text[0] = '\0';
    if (column->default_node == NULL ||
        column->default_node->kind == MYLITE_SQL_AST_COLUMN_DEFAULT_NULL) {
        return MYLITE_OK;
    }
    if (column->default_node->kind != MYLITE_SQL_AST_COLUMN_DEFAULT_VALUE) {
        set_parse_error(database, NULL);
        return MYLITE_ERROR;
    }
    value_node = child_at(column->default_node, 0U);
    if (value_node != NULL && value_node->kind == MYLITE_SQL_AST_CURRENT_TIMESTAMP_VALUE) {
        if (planned_column_is_datetime(column) || planned_column_is_timestamp(column)) {
            column->default_kind = MYLITE_CATALOG_COLUMN_DEFAULT_CURRENT_TIMESTAMP;
            return MYLITE_OK;
        }
        set_invalid_default_error(database, column->name);
        return MYLITE_ERROR;
    }
    if (column_default_value_is_current_date_expression(value_node)) {
        if (planned_column_is_date(column)) {
            column->default_kind = MYLITE_CATALOG_COLUMN_DEFAULT_CURRENT_DATE;
            return MYLITE_OK;
        }
        set_invalid_default_error(database, column->name);
        return MYLITE_ERROR;
    }
    if (column_default_value_is_current_time_expression(value_node)) {
        if (planned_column_is_time(column)) {
            column->default_kind = MYLITE_CATALOG_COLUMN_DEFAULT_CURRENT_TIME;
            return MYLITE_OK;
        }
        set_invalid_default_error(database, column->name);
        return MYLITE_ERROR;
    }
    if (value_node != NULL &&
        value_node->kind == MYLITE_SQL_AST_CURRENT_TIMESTAMP_ARGUMENT_COUNT_ERROR) {
        set_native_function_parameter_count_error(database, "CURRENT_TIMESTAMP");
        return MYLITE_ERROR;
    }
    if (column_default_value_is_parenthesized_expression(column->default_node)) {
        if (planned_column_is_text_family(column)) {
            return finalize_planned_column_text_expression_default(database, column, value_node);
        }
        if (planned_column_is_bit(column) || planned_column_is_year(column) ||
            planned_column_is_enum(column) || planned_column_is_set(column) ||
            planned_column_is_json(column) || planned_column_is_spatial(column)) {
            set_invalid_default_error(database, column->name);
            return MYLITE_ERROR;
        }
        return finalize_planned_column_integer_expression_default(database, column, value_node);
    }

    return finalize_planned_column_type_default(database, column);
}

static int finalize_planned_column_type_default(
    struct mylite_db *database,
    struct planned_column *column
) {
    int64_t default_integer = 0;
    int rc = MYLITE_OK;

    if (planned_column_is_char(column) || planned_column_is_varchar(column)) {
        return finalize_planned_column_string_default(database, column);
    }
    if (planned_column_is_decimal(column)) {
        return finalize_planned_column_decimal_default(database, column);
    }
    if (planned_column_is_approximate(column)) {
        return finalize_planned_column_approximate_default(database, column);
    }
    if (planned_column_is_bit(column)) {
        return finalize_planned_column_bit_default(database, column);
    }
    if (planned_column_is_year(column)) {
        return finalize_planned_column_year_default(database, column);
    }
    if (planned_column_is_date(column)) {
        return finalize_planned_column_date_default(database, column);
    }
    if (planned_column_is_time(column)) {
        return finalize_planned_column_time_default(database, column);
    }
    if (planned_column_is_datetime(column)) {
        return finalize_planned_column_datetime_default(database, column);
    }
    if (planned_column_is_timestamp(column)) {
        return finalize_planned_column_timestamp_default(database, column);
    }
    if (planned_column_is_enum(column)) {
        return finalize_planned_column_enum_default(database, column);
    }
    if (planned_column_is_set(column)) {
        return finalize_planned_column_set_default(database, column);
    }

    rc = convert_column_default_value(
        database,
        child_at(column->default_node, 0U),
        column,
        &default_integer
    );
    if (rc != MYLITE_OK) {
        return rc;
    }

    column->default_kind = MYLITE_CATALOG_COLUMN_DEFAULT_INTEGER;
    column->default_integer = default_integer;

    return MYLITE_OK;
}

static int finalize_planned_column_integer_expression_default(
    struct mylite_db *database,
    struct planned_column *column,
    const struct mylite_sql_ast_node *value_node
) {
    struct scalar_arithmetic_value expression_value = {.is_null = false, .integer = 0};
    int64_t default_integer = 0;
    int rc = evaluate_integer_default_expression(database, value_node, &expression_value);

    if (rc != MYLITE_OK) {
        if (rc == MYLITE_NOMEM) {
            return rc;
        }
        set_invalid_default_error(database, column->name);
        return MYLITE_ERROR;
    }
    if (expression_value.is_null) {
        column->default_kind = MYLITE_CATALOG_COLUMN_DEFAULT_NULL_EXPRESSION;
        snprintf(column->default_text, sizeof(column->default_text), "NULL");
        return MYLITE_OK;
    }

    rc = convert_integer_expression_default_result(
        database,
        column,
        expression_value.integer,
        &default_integer
    );
    if (rc != MYLITE_OK) {
        set_invalid_default_error(database, column->name);
        return MYLITE_ERROR;
    }
    rc = copy_planned_expression_default_text(database, column, &value_node->span);
    if (rc != MYLITE_OK) {
        return rc;
    }
    column->default_kind = MYLITE_CATALOG_COLUMN_DEFAULT_INTEGER_EXPRESSION;
    column->default_integer = default_integer;

    return MYLITE_OK;
}

static int finalize_planned_column_text_expression_default(
    struct mylite_db *database,
    struct planned_column *column,
    const struct mylite_sql_ast_node *value_node
) {
    const struct mylite_sql_ast_node *expression = unwrap_parenthesized_expression(value_node);
    struct mylite_catalog_column_descriptor descriptor = {0};
    struct planned_value value = {
        .is_null = false,
        .is_text = false,
        .integer = 0,
        .text = NULL,
        .text_length = 0U,
    };
    int rc = MYLITE_OK;

    if (expression == NULL || expression->kind != MYLITE_SQL_AST_LITERAL) {
        set_invalid_default_error(database, column->name);
        return MYLITE_ERROR;
    }
    if (mylite_sql_ast_node_literal_kind(expression) == MYLITE_SQL_AST_LITERAL_NULL) {
        column->default_kind = MYLITE_CATALOG_COLUMN_DEFAULT_NULL_EXPRESSION;
        snprintf(column->default_text, sizeof(column->default_text), "NULL");
        return MYLITE_OK;
    }
    if (mylite_sql_ast_node_literal_kind(expression) != MYLITE_SQL_AST_LITERAL_STRING) {
        set_invalid_default_error(database, column->name);
        return MYLITE_ERROR;
    }

    planned_column_descriptor_for_default(column, &descriptor);
    rc = convert_text_family_literal(database, expression, &descriptor, 1U, &value);
    if (rc != MYLITE_OK) {
        set_invalid_default_error(database, column->name);
    }
    if (rc == MYLITE_OK) {
        rc = copy_planned_default_text(database, column, &value);
    }
    planned_value_deinit(&value);
    if (rc == MYLITE_OK) {
        column->default_kind = MYLITE_CATALOG_COLUMN_DEFAULT_TEXT;
    }

    return rc;
}

static int finalize_planned_column_string_default(
    struct mylite_db *database,
    struct planned_column *column
) {
    struct mylite_catalog_column_descriptor descriptor = {0};
    struct planned_value value = {
        .is_null = false,
        .is_text = false,
        .integer = 0,
        .text = NULL,
        .text_length = 0U,
    };
    int rc = MYLITE_OK;

    planned_column_descriptor_for_default(column, &descriptor);
    if (planned_column_is_char(column)) {
        rc = convert_char_literal(
            database,
            child_at(column->default_node, 0U),
            &descriptor,
            1U,
            &value
        );
    } else {
        rc = convert_varchar_literal(
            database,
            child_at(column->default_node, 0U),
            &descriptor,
            1U,
            &value
        );
    }
    if (rc != MYLITE_OK) {
        set_invalid_default_error(database, column->name);
    }
    if (rc == MYLITE_OK) {
        rc = copy_planned_default_text(database, column, &value);
    }
    planned_value_deinit(&value);
    if (rc == MYLITE_OK) {
        column->default_kind = MYLITE_CATALOG_COLUMN_DEFAULT_TEXT;
    }

    return rc;
}

