static bool normalize_iso_temporal_predicate_text(
    const struct temporal_predicate_normalization_input *input,
    char *out_text
) {
    struct date_add_datetime_parts parts = {0};
    int source_offset_minutes = 0;

    if (input == NULL || input->text == NULL || out_text == NULL) {
        return false;
    }
    if (input->text_length == datetime_text_length &&
        input->text[datetime_date_time_separator_offset] == 'T') {
        memcpy(out_text, input->text, datetime_text_length);
        out_text[datetime_date_time_separator_offset] = ' ';
        out_text[datetime_text_length] = '\0';
        return datetime_text_has_canonical_shape(out_text, datetime_text_length);
    }
    if (input->text_length != datetime_text_length + sizeof("+00:00") - 1U ||
        (input->text[datetime_date_time_separator_offset] != ' ' &&
         input->text[datetime_date_time_separator_offset] != 'T')) {
        return false;
    }

    memcpy(out_text, input->text, datetime_text_length);
    out_text[datetime_date_time_separator_offset] = ' ';
    out_text[datetime_text_length] = '\0';
    if (!date_add_parse_datetime_text(out_text, datetime_text_length, &parts)) {
        return false;
    }
    if (!parse_temporal_predicate_offset(
            input->text + datetime_text_length,
            &source_offset_minutes
        )) {
        return false;
    }

    return shift_datetime_parts_by_minutes(
        &parts,
        input->target_offset_minutes - source_offset_minutes,
        out_text
    );
}

static bool normalize_z_temporal_predicate_text(
    const char *text,
    size_t text_length,
    char *out_text
) {
    if (text == NULL || out_text == NULL) {
        return false;
    }
    if (text_length != datetime_text_length + 1U ||
        (text[datetime_date_time_separator_offset] != ' ' &&
         text[datetime_date_time_separator_offset] != 'T') ||
        (text[datetime_text_length] != 'Z' && text[datetime_text_length] != 'z')) {
        return false;
    }

    memcpy(out_text, text, datetime_text_length);
    out_text[datetime_date_time_separator_offset] = ' ';
    out_text[datetime_text_length] = '\0';
    return datetime_text_has_canonical_shape(out_text, datetime_text_length);
}

static bool parse_temporal_predicate_offset(const char *text, int *out_offset_minutes) {
    int sign = 0;
    int hours = 0;
    int minutes = 0;
    int total_minutes = 0;

    if (text == NULL || out_offset_minutes == NULL) {
        return false;
    }
    if (text[temporal_predicate_offset_sign_index] == '+') {
        sign = 1;
    } else if (text[temporal_predicate_offset_sign_index] == '-') {
        sign = -1;
    } else {
        return false;
    }
    if (text[temporal_predicate_offset_hour_tens_index] < '0' ||
        text[temporal_predicate_offset_hour_tens_index] > '9' ||
        text[temporal_predicate_offset_hour_ones_index] < '0' ||
        text[temporal_predicate_offset_hour_ones_index] > '9' ||
        text[temporal_predicate_offset_separator_index] != ':' ||
        text[temporal_predicate_offset_minute_tens_index] < '0' ||
        text[temporal_predicate_offset_minute_tens_index] > '9' ||
        text[temporal_predicate_offset_minute_ones_index] < '0' ||
        text[temporal_predicate_offset_minute_ones_index] > '9' ||
        text[temporal_predicate_offset_text_length] != '\0') {
        return false;
    }

    hours = ((text[temporal_predicate_offset_hour_tens_index] - '0') * decimal_base) +
            (text[temporal_predicate_offset_hour_ones_index] - '0');
    minutes = ((text[temporal_predicate_offset_minute_tens_index] - '0') * decimal_base) +
              (text[temporal_predicate_offset_minute_ones_index] - '0');
    if (minutes > time_zone_max_minute) {
        return false;
    }
    total_minutes = (hours * time_zone_minutes_per_hour) + minutes;
    if (total_minutes > temporal_predicate_offset_max_minutes) {
        return false;
    }
    if (sign < 0 && total_minutes == 0) {
        return false;
    }

    *out_offset_minutes = sign * total_minutes;
    return true;
}

static bool shift_datetime_parts_by_minutes(
    const struct date_add_datetime_parts *parts,
    int delta_minutes,
    char *out_text
) {
    const int64_t seconds_per_day = date_add_seconds_per_day();
    struct date_add_day_second shifted = {0};
    struct date_add_datetime_parts output = {0};
    int64_t days = 0;
    int64_t day_seconds = 0;
    int64_t base_seconds = 0;
    int64_t shifted_seconds = 0;
    int64_t result_day_seconds = 0;

    if (parts == NULL || out_text == NULL) {
        return false;
    }

    days = date_add_days_from_datetime(parts);
    day_seconds = ((int64_t)parts->hour * (int64_t)time_second_per_hour) +
                  ((int64_t)parts->minute * (int64_t)time_second_per_minute) +
                  (int64_t)parts->second;
    base_seconds = (days * seconds_per_day) + day_seconds;
    if (!date_add_checked_add_int64(
            base_seconds,
            (int64_t)delta_minutes * time_zone_seconds_per_minute,
            &shifted_seconds
        )) {
        return false;
    }

    shifted = date_add_floor_divmod_seconds(shifted_seconds);
    date_add_civil_from_days(shifted.days, &output);
    if (output.year < date_minimum_year || output.year > date_maximum_year) {
        return false;
    }
    result_day_seconds = shifted.day_seconds;
    output.hour = (uint32_t)(result_day_seconds / time_second_per_hour);
    result_day_seconds %= time_second_per_hour;
    output.minute = (uint32_t)(result_day_seconds / time_second_per_minute);
    output.second = (uint32_t)(result_day_seconds % time_second_per_minute);

    return format_datetime_parts_text(&output, out_text);
}

static bool format_datetime_parts_text(
    const struct date_add_datetime_parts *parts,
    char *out_text
) {
    int written = 0;

    if (parts == NULL || out_text == NULL) {
        return false;
    }

    written = snprintf(
        out_text,
        datetime_text_length + 1U,
        "%04" PRId64 "-%02" PRIu32 "-%02" PRIu32 " %02" PRIu32 ":%02" PRIu32 ":%02" PRIu32,
        parts->year,
        parts->month,
        parts->day,
        parts->hour,
        parts->minute,
        parts->second
    );
    return written == datetime_text_length;
}

static bool predicate_date_text_admitted(
    const struct mylite_db *database,
    const char *text,
    size_t text_length
) {
    enum temporal_text_kind kind = classify_date_text(text, text_length);

    switch (kind) {
    case TEMPORAL_TEXT_NORMAL:
        return true;
    case TEMPORAL_TEXT_FULL_ZERO:
        if (temporal_sql_mode_has_no_zero_date(database)) {
            return false;
        }
        return true;
    case TEMPORAL_TEXT_PARTIAL_ZERO:
        if (temporal_sql_mode_has_no_zero_in_date(database)) {
            return false;
        }
        return true;
    case TEMPORAL_TEXT_ALLOW_INVALID_CANDIDATE:
        return temporal_sql_mode_has_allow_invalid_dates(database);
    case TEMPORAL_TEXT_INVALID:
    case TEMPORAL_TEXT_DEFERRED:
        return false;
    }
    return false;
}

static bool predicate_datetime_text_admitted(
    const struct mylite_db *database,
    const char *text,
    size_t text_length
) {
    enum temporal_text_kind kind = classify_datetime_text(text, text_length);

    switch (kind) {
    case TEMPORAL_TEXT_NORMAL:
        return true;
    case TEMPORAL_TEXT_FULL_ZERO:
        if (temporal_sql_mode_has_no_zero_date(database)) {
            return false;
        }
        return true;
    case TEMPORAL_TEXT_PARTIAL_ZERO:
        if (temporal_sql_mode_has_no_zero_in_date(database)) {
            return false;
        }
        return true;
    case TEMPORAL_TEXT_ALLOW_INVALID_CANDIDATE:
        return temporal_sql_mode_has_allow_invalid_dates(database);
    case TEMPORAL_TEXT_INVALID:
    case TEMPORAL_TEXT_DEFERRED:
        return false;
    }
    return false;
}

static bool predicate_timestamp_text_admitted(
    const struct mylite_db *database,
    const char *text,
    size_t text_length
) {
    if (timestamp_text_is_canonical_valid(text, text_length)) {
        return true;
    }
    if (datetime_text_is_zero_datetime(text, text_length)) {
        if (temporal_sql_mode_has_no_zero_date(database)) {
            return false;
        }
        return true;
    }
    return false;
}

static int convert_integer_for_predicate(
    struct mylite_db *database,
    uint64_t magnitude,
    bool is_negative,
    const struct mylite_catalog_column_descriptor *column,
    int64_t *out_value
) {
    const uint64_t bigint_signed_negative_abs_max = 9223372036854775808ULL;
    struct integer_column_range range = {0};
    int rc = integer_range_for_column(
        database,
        column,
        "WHERE supports only baseline integer columns",
        &range
    );

    if (rc != MYLITE_OK) {
        return rc;
    }
    if (is_negative) {
        if ((range.negative_abs_max == 0U && magnitude != 0U) ||
            magnitude > range.negative_abs_max) {
            set_predicate_out_of_range_error(database, column->name);
            return MYLITE_ERROR;
        }
        if (magnitude == bigint_signed_negative_abs_max) {
            *out_value = INT64_MIN;
        } else {
            *out_value = -(int64_t)magnitude;
        }
        return MYLITE_OK;
    }
    if (magnitude > range.positive_max) {
        set_predicate_out_of_range_error(database, column->name);
        return MYLITE_ERROR;
    }

    *out_value = (int64_t)magnitude;
    return MYLITE_OK;
}

static int plan_select_order(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *order_clause,
    const struct select_source_context *source_context,
    const struct planned_select *select_plan,
    const struct mylite_catalog_column_descriptor *table_columns,
    size_t table_column_count,
    struct planned_select_order *out_order
) {
    const struct mylite_sql_ast_node *direction = NULL;
    bool resolved_alias = false;
    int rc = MYLITE_OK;

    out_order->has_order = false;
    out_order->column = (struct mylite_catalog_column_descriptor){0};
    out_order->column_source_index = 0U;
    out_order->direction = PLANNED_SELECT_ORDER_DEFAULT;
    out_order->qualify_column_reference = select_source_context_is_joined(source_context);
    if (order_clause == NULL) {
        return MYLITE_OK;
    }
    if (order_clause->kind != MYLITE_SQL_AST_ORDER_BY_CLAUSE) {
        set_unsupported_error(database, "SELECT supports only one descriptor ORDER BY column");
        return MYLITE_ERROR;
    }

    rc = resolve_order_alias(
        database,
        child_at(order_clause, 0U),
        select_plan,
        &out_order->column,
        &out_order->column_source_index,
        &resolved_alias
    );
    if (rc == MYLITE_OK && !resolved_alias) {
        rc = resolve_order_column(
            database,
            child_at(order_clause, 0U),
            source_context,
            table_columns,
            table_column_count,
            &out_order->column,
            &out_order->column_source_index
        );
    }
    if (rc != MYLITE_OK) {
        return rc;
    }
    if (column_descriptor_is_set(&out_order->column)) {
        set_unsupported_error(database, "ORDER BY does not yet support SET columns");
        return MYLITE_ERROR;
    }
    if (column_descriptor_is_string_family(&out_order->column)) {
        out_order->has_order = true;
        out_order->direction = PLANNED_SELECT_ORDER_ASC;
        direction = child_at(order_clause, 1U);
        if (mylite_sql_ast_node_order_direction(direction) == MYLITE_SQL_AST_ORDER_DIRECTION_DESC) {
            out_order->direction = PLANNED_SELECT_ORDER_DESC;
        }
        return MYLITE_OK;
    }
    if (rc == MYLITE_OK && !column_descriptor_is_date(&out_order->column) &&
        !column_descriptor_is_time(&out_order->column) &&
        !column_descriptor_is_datetime(&out_order->column) &&
        !column_descriptor_is_timestamp(&out_order->column) &&
        !column_descriptor_is_year(&out_order->column) &&
        !column_descriptor_is_bit(&out_order->column)) {
        struct integer_column_range range = {0};

        rc = integer_range_for_column(
            database,
            &out_order->column,
            "ORDER BY supports only integer, BIT, YEAR, DATE, TIME, DATETIME, TIMESTAMP, or "
            "nonbinary string descriptor columns",
            &range
        );
    }
    if (rc != MYLITE_OK) {
        return rc;
    }

    out_order->has_order = true;
    out_order->direction = PLANNED_SELECT_ORDER_ASC;
    direction = child_at(order_clause, 1U);
    if (mylite_sql_ast_node_order_direction(direction) == MYLITE_SQL_AST_ORDER_DIRECTION_DESC) {
        out_order->direction = PLANNED_SELECT_ORDER_DESC;
    }

    return MYLITE_OK;
}

static int resolve_order_alias(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *column_node,
    const struct planned_select *select_plan,
    struct mylite_catalog_column_descriptor *out_column,
    size_t *out_source_index,
    bool *out_resolved
) {
    char *order_name = NULL;
    bool found = false;
    int rc = MYLITE_OK;

    *out_resolved = false;
    if (select_plan == NULL || column_node == NULL ||
        column_node->kind != MYLITE_SQL_AST_IDENTIFIER) {
        return MYLITE_OK;
    }

    rc = copy_select_item_identifier_alias_text(database, column_node, &order_name);
    if (rc != MYLITE_OK) {
        return rc;
    }

    for (size_t column_index = 0U; column_index < select_plan->column_count; ++column_index) {
        const struct mylite_sql_ast_node *alias = select_plan->column_aliases[column_index];
        char *alias_text = NULL;

        if (alias == NULL) {
            continue;
        }

        rc = copy_select_item_alias_text(database, alias, &alias_text);
        if (rc != MYLITE_OK) {
            free(order_name);
            return rc;
        }
        if (text_equals_ascii_case_insensitive(alias_text, order_name)) {
            if (found) {
                free(alias_text);
                set_ambiguous_order_column_error(database, order_name);
                free(order_name);
                return MYLITE_ERROR;
            }
            *out_column = select_plan->columns[column_index];
            if (out_source_index != NULL) {
                *out_source_index = select_plan->column_source_indexes[column_index];
            }
            found = true;
        }
        free(alias_text);
    }

    free(order_name);
    *out_resolved = found;
    return MYLITE_OK;
}

static int resolve_order_column(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *column_node,
    const struct select_source_context *source_context,
    const struct mylite_catalog_column_descriptor *table_columns,
    size_t table_column_count,
    struct mylite_catalog_column_descriptor *out_column,
    size_t *out_source_index
) {
    return resolve_descriptor_column_reference_with_source_index(
        database,
        column_node,
        source_context,
        COLUMN_REFERENCE_ORDER,
        "ORDER BY supports only unqualified descriptor columns",
        table_columns,
        table_column_count,
        out_column,
        out_source_index
    );
}

static int plan_select_limit(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *limit_clause,
    struct planned_select_limit *out_limit
) {
    int rc = MYLITE_OK;

    out_limit->has_limit = false;
    out_limit->row_count = 0;
    out_limit->has_offset = false;
    out_limit->offset = 0;
    if (limit_clause == NULL) {
        return MYLITE_OK;
    }
    if (limit_clause->kind != MYLITE_SQL_AST_LIMIT_CLAUSE) {
        set_unsupported_error(database, "SELECT supports only literal LIMIT clauses");
        return MYLITE_ERROR;
    }

    rc = convert_limit_integer_literal(database, child_at(limit_clause, 0U), &out_limit->row_count);
    if (rc != MYLITE_OK) {
        return rc;
    }
    out_limit->has_limit = true;

    if (child_at(limit_clause, 1U) != NULL) {
        rc =
            convert_limit_integer_literal(database, child_at(limit_clause, 1U), &out_limit->offset);
        if (rc != MYLITE_OK) {
            return rc;
        }
        out_limit->has_offset = true;
    }

    return MYLITE_OK;
}

static int plan_delete_limit(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *limit_clause,
    struct planned_select_limit *out_limit
) {
    int rc = MYLITE_OK;

    out_limit->has_limit = false;
    out_limit->row_count = 0;
    out_limit->has_offset = false;
    out_limit->offset = 0;
    if (limit_clause == NULL) {
        return MYLITE_OK;
    }
    if (limit_clause->kind != MYLITE_SQL_AST_LIMIT_CLAUSE) {
        set_unsupported_error(database, "DELETE supports only LIMIT row_count");
        return MYLITE_ERROR;
    }
    if (child_at(limit_clause, 1U) != NULL) {
        set_unsupported_error(database, "DELETE supports only LIMIT row_count");
        return MYLITE_ERROR;
    }

    rc = convert_limit_integer_literal(database, child_at(limit_clause, 0U), &out_limit->row_count);
    if (rc != MYLITE_OK) {
        return rc;
    }
    out_limit->has_limit = true;

    return MYLITE_OK;
}

static int plan_update_assignment(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *assignment_list,
    const struct mylite_catalog_column_descriptor *table_columns,
    size_t table_column_count,
    struct planned_update *out_plan
) {
    const struct mylite_sql_ast_node *assignment = child_at(assignment_list, 0U);
    const struct mylite_sql_ast_node *target = NULL;
    char column_name[MYLITE_CATALOG_IDENTIFIER_CAPACITY];
    size_t column_index = 0U;
    int rc = MYLITE_OK;

    if (assignment_list == NULL || assignment_list->kind != MYLITE_SQL_AST_UPDATE_ASSIGNMENT_LIST) {
        set_parse_error(database, NULL);
        return MYLITE_ERROR;
    }
    if (mylite_sql_ast_node_child_count(assignment_list) == 0U) {
        set_parse_error(database, NULL);
        return MYLITE_ERROR;
    }
    if (mylite_sql_ast_node_child_count(assignment_list) != 1U) {
        rc = plan_update_multiple_assignments(
            database,
            assignment_list,
            table_columns,
            table_column_count,
            out_plan
        );
        if (rc == MYLITE_OK) {
            rc = validate_update_multiple_auto_update_columns(
                database,
                out_plan,
                table_columns,
                table_column_count
            );
        }
        return rc;
    }
    if (assignment == NULL || assignment->kind != MYLITE_SQL_AST_UPDATE_ASSIGNMENT) {
        set_parse_error(database, NULL);
        return MYLITE_ERROR;
    }

    target = child_at(assignment, 0U);
    if (target == NULL || target->kind != MYLITE_SQL_AST_IDENTIFIER) {
        set_unsupported_error(database, "UPDATE supports only unqualified assignment columns");
        return MYLITE_ERROR;
    }
    rc = copy_identifier_text(target, column_name, sizeof(column_name), database);
    if (rc != MYLITE_OK) {
        return rc;
    }
    rc = find_column_index(table_columns, table_column_count, column_name, &column_index);
    if (rc != MYLITE_OK) {
        set_unknown_column_error(database, column_name);
        return MYLITE_ERROR;
    }

    out_plan->assignment_column = table_columns[column_index];
    out_plan->assignment_value_node = child_at(assignment, 1U);
    if (out_plan->assignment_value_node == NULL) {
        set_parse_error(database, NULL);
        return MYLITE_ERROR;
    }
    rc = plan_update_arithmetic_assignment(database, table_columns, table_column_count, out_plan);
    if (rc != MYLITE_OK ||
        out_plan->assignment_value_kind == PLANNED_UPDATE_ASSIGNMENT_SAME_COLUMN_ARITHMETIC) {
        return rc;
    }

    return plan_update_scalar_subquery_assignment(database, out_plan);
}

static int plan_update_multiple_assignments(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *assignment_list,
    const struct mylite_catalog_column_descriptor *table_columns,
    size_t table_column_count,
    struct planned_update *out_plan
) {
    size_t assignment_count = mylite_sql_ast_node_child_count(assignment_list);
    int rc = MYLITE_OK;

    out_plan->assignments = calloc(assignment_count, sizeof(*out_plan->assignments));
    if (out_plan->assignments == NULL) {
        set_nomem_error(database);
        return MYLITE_NOMEM;
    }
    out_plan->assignment_count = assignment_count;

    for (size_t assignment_index = 0U; rc == MYLITE_OK && assignment_index < assignment_count;
         ++assignment_index) {
        rc = plan_update_multiple_assignment(
            database,
            child_at(assignment_list, assignment_index),
            table_columns,
            table_column_count,
            out_plan,
            assignment_index
        );
    }

    return rc;
}

static int plan_update_multiple_assignment(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *assignment,
    const struct mylite_catalog_column_descriptor *table_columns,
    size_t table_column_count,
    struct planned_update *out_plan,
    size_t assignment_index
) {
    const struct mylite_sql_ast_node *target = NULL;
    const struct mylite_sql_ast_node *value_node = NULL;
    char column_name[MYLITE_CATALOG_IDENTIFIER_CAPACITY];
    size_t column_index = 0U;
    int rc = MYLITE_OK;

    if (assignment == NULL || assignment->kind != MYLITE_SQL_AST_UPDATE_ASSIGNMENT) {
        set_parse_error(database, NULL);
        return MYLITE_ERROR;
    }

    target = child_at(assignment, 0U);
    if (target == NULL || target->kind != MYLITE_SQL_AST_IDENTIFIER) {
        set_update_multiple_assignment_unsupported_error(database);
        return MYLITE_ERROR;
    }
    rc = copy_identifier_text(target, column_name, sizeof(column_name), database);
    if (rc != MYLITE_OK) {
        return rc;
    }
    rc = find_column_index(table_columns, table_column_count, column_name, &column_index);
    if (rc != MYLITE_OK) {
        set_unknown_column_error(database, column_name);
        return MYLITE_ERROR;
    }
    for (size_t index = 0U; index < assignment_index; ++index) {
        if (out_plan->assignments[index].column.column_id ==
            table_columns[column_index].column_id) {
            set_update_duplicate_assignment_unsupported_error(database);
            return MYLITE_ERROR;
        }
    }
    if (column_descriptor_is_auto_increment(&table_columns[column_index]) ||
        update_column_id_is_keyed(out_plan, table_columns[column_index].column_id)) {
        set_update_multiple_assignment_unsupported_error(database);
        return MYLITE_ERROR;
    }

    value_node = child_at(assignment, 1U);
    if (!update_assignment_value_is_multi_constant_supported(value_node)) {
        set_update_multiple_assignment_unsupported_error(database);
        return MYLITE_ERROR;
    }

    out_plan->assignments[assignment_index].column = table_columns[column_index];
    out_plan->assignments[assignment_index].value_node = value_node;

    return MYLITE_OK;
}

static int plan_update_arithmetic_assignment(
    struct mylite_db *database,
    const struct mylite_catalog_column_descriptor *table_columns,
    size_t table_column_count,
    struct planned_update *out_plan
) {
    const struct mylite_sql_ast_node *value_node = NULL;
    const struct mylite_sql_ast_node *source = NULL;
    const struct mylite_sql_ast_node *delta = NULL;
    enum mylite_sql_ast_operator operator_kind = MYLITE_SQL_AST_OPERATOR_NONE;
    char source_name[MYLITE_CATALOG_IDENTIFIER_CAPACITY];
    size_t source_index = 0U;
    int rc = MYLITE_OK;

    value_node = unwrap_parenthesized_expression(out_plan->assignment_value_node);
    if (value_node == NULL || value_node->kind != MYLITE_SQL_AST_BINARY_EXPRESSION) {
        return MYLITE_OK;
    }

    operator_kind = mylite_sql_ast_node_operator(value_node);
    if (operator_kind != MYLITE_SQL_AST_OPERATOR_ADD &&
        operator_kind != MYLITE_SQL_AST_OPERATOR_SUBTRACT) {
        set_update_arithmetic_unsupported_error(database);
        return MYLITE_ERROR;
    }

    source = child_at(value_node, 0U);
    delta = child_at(value_node, 1U);
    if (source == NULL || source->kind != MYLITE_SQL_AST_IDENTIFIER || delta == NULL ||
        delta->kind != MYLITE_SQL_AST_LITERAL ||
        mylite_sql_ast_node_literal_kind(delta) != MYLITE_SQL_AST_LITERAL_INTEGER) {
        set_update_arithmetic_unsupported_error(database);
        return MYLITE_ERROR;
    }

    rc = copy_identifier_text(source, source_name, sizeof(source_name), database);
    if (rc != MYLITE_OK) {
        return rc;
    }
    rc = find_column_index(table_columns, table_column_count, source_name, &source_index);
    if (rc != MYLITE_OK) {
        set_unknown_column_error(database, source_name);
        return MYLITE_ERROR;
    }
    if (table_columns[source_index].column_id != out_plan->assignment_column.column_id) {
        set_update_arithmetic_unsupported_error(database);
        return MYLITE_ERROR;
    }

    out_plan->assignment_value_kind = PLANNED_UPDATE_ASSIGNMENT_SAME_COLUMN_ARITHMETIC;
    out_plan->arithmetic_operator = operator_kind;
    out_plan->arithmetic_delta_node = delta;

    return validate_update_arithmetic_assignment_target(database, out_plan);
}

static int validate_update_arithmetic_assignment_target(
    struct mylite_db *database,
    const struct planned_update *plan
) {
    struct integer_column_range range = {0};
    int rc = integer_range_for_column(
        database,
        &plan->assignment_column,
        "UPDATE arithmetic assignment supports only integer columns",
        &range
    );

    (void)range;
    if (rc != MYLITE_OK) {
        return rc;
    }
    if (column_descriptor_is_auto_increment(&plan->assignment_column) ||
        update_assignment_column_is_keyed(plan)) {
        set_update_arithmetic_unsupported_error(database);
        return MYLITE_ERROR;
    }

    return MYLITE_OK;
}

static bool update_assignment_column_is_keyed(const struct planned_update *plan) {
    if (plan == NULL) {
        return false;
    }
    return update_column_id_is_keyed(plan, plan->assignment_column.column_id);
}

static bool update_column_id_is_keyed(const struct planned_update *plan, int64_t column_id) {
    if (plan == NULL) {
        return false;
    }
    for (size_t index = 0U; index < plan->index_count; ++index) {
        const struct loaded_index_info *key = &plan->indexes[index];

        if ((key->index.kind == MYLITE_CATALOG_INDEX_KIND_PRIMARY || key->index.is_unique) &&
            loaded_index_contains_column_id(key, column_id)) {
            return true;
        }
    }

    return false;
}

static bool update_assignment_value_is_multi_constant_supported(
    const struct mylite_sql_ast_node *value_node
) {
    value_node = unwrap_parenthesized_expression(value_node);
    if (value_node == NULL) {
        return false;
    }

    switch (value_node->kind) {
    case MYLITE_SQL_AST_LITERAL:
    case MYLITE_SQL_AST_DML_DEFAULT_VALUE:
    case MYLITE_SQL_AST_DEFAULT_FUNCTION:
    case MYLITE_SQL_AST_CURRENT_TIMESTAMP_VALUE:
    case MYLITE_SQL_AST_CURRENT_TIMESTAMP_ARGUMENT_COUNT_ERROR:
    case MYLITE_SQL_AST_CURRENT_DATE_VALUE:
    case MYLITE_SQL_AST_CURRENT_TIME_VALUE:
    case MYLITE_SQL_AST_UTC_DATE_VALUE:
    case MYLITE_SQL_AST_UTC_TIME_VALUE:
    case MYLITE_SQL_AST_UTC_TIMESTAMP_VALUE:
        return true;
    case MYLITE_SQL_AST_UNARY_EXPRESSION:
        return update_assignment_unary_value_is_multi_constant_supported(value_node);
    default:
        return false;
    }
}

static bool update_assignment_unary_value_is_multi_constant_supported(
    const struct mylite_sql_ast_node *value_node
) {
    const struct mylite_sql_ast_node *operand = NULL;
    enum mylite_sql_ast_operator operator_kind = MYLITE_SQL_AST_OPERATOR_NONE;
    enum mylite_sql_ast_literal_kind literal_kind = MYLITE_SQL_AST_LITERAL_NULL;

    if (value_node == NULL || value_node->kind != MYLITE_SQL_AST_UNARY_EXPRESSION) {
        return false;
    }
    operator_kind = mylite_sql_ast_node_operator(value_node);
    if (operator_kind != MYLITE_SQL_AST_OPERATOR_POSITIVE &&
        operator_kind != MYLITE_SQL_AST_OPERATOR_NEGATIVE) {
        return false;
    }

    operand = child_at(value_node, 0U);
    if (operand == NULL || operand->kind != MYLITE_SQL_AST_LITERAL) {
        return false;
    }
    literal_kind = mylite_sql_ast_node_literal_kind(operand);
    if (literal_kind == MYLITE_SQL_AST_LITERAL_INTEGER ||
        literal_kind == MYLITE_SQL_AST_LITERAL_DECIMAL ||
        literal_kind == MYLITE_SQL_AST_LITERAL_FLOAT) {
        return true;
    }
    return false;
}

static int validate_update_multiple_auto_update_columns(
    struct mylite_db *database,
    const struct planned_update *plan,
    const struct mylite_catalog_column_descriptor *table_columns,
    size_t table_column_count
) {
    for (size_t column_index = 0U; column_index < table_column_count; ++column_index) {
        if (planned_update_column_has_auto_update(plan, &table_columns[column_index]) &&
            update_column_id_is_keyed(plan, table_columns[column_index].column_id)) {
            set_update_multiple_assignment_unsupported_error(database);
            return MYLITE_ERROR;
        }
    }

    return MYLITE_OK;
}

static void set_update_multiple_assignment_unsupported_error(struct mylite_db *database) {
    set_unsupported_error(
        database,
        "UPDATE multiple assignments support only distinct unqualified non-key constant "
        "assignments"
    );
}

static void set_update_duplicate_assignment_unsupported_error(struct mylite_db *database) {
    set_unsupported_error(database, "UPDATE multiple assignments do not support duplicate targets");
}

static int validate_update_default_function_sources(
    struct mylite_db *database,
    const struct planned_update *plan,
    const struct mylite_catalog_column_descriptor *table_columns,
    size_t table_column_count
) {
    if (plan == NULL) {
        set_parse_error(database, NULL);
        return MYLITE_ERROR;
    }
    if (planned_update_has_multiple_assignments(plan)) {
        int rc = MYLITE_OK;

        for (size_t index = 0U; rc == MYLITE_OK && index < plan->assignment_count; ++index) {
            rc = validate_update_default_function_source(
                database,
                plan->assignments[index].value_node,
                plan,
                table_columns,
                table_column_count
            );
        }
        return rc;
    }

    return validate_update_default_function_source(
        database,
        plan->assignment_value_node,
        plan,
        table_columns,
        table_column_count
    );
}

static int validate_update_default_function_source(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *value_node,
    const struct planned_update *plan,
    const struct mylite_catalog_column_descriptor *table_columns,
    size_t table_column_count
) {
    struct select_source_context source_context = {0};

    value_node = unwrap_parenthesized_expression(value_node);
    if (value_node == NULL || value_node->kind != MYLITE_SQL_AST_DEFAULT_FUNCTION) {
        return MYLITE_OK;
    }

    source_context.source = &plan->target;
    return validate_default_function_source_value(
        database,
        value_node,
        &source_context,
        table_columns,
        table_column_count
    );
}

static int plan_update_scalar_subquery_assignment(
    struct mylite_db *database,
    struct planned_update *out_plan
) {
    const struct mylite_sql_ast_node *value_node = NULL;
    const struct mylite_sql_ast_node *statement = NULL;
    int rc = MYLITE_OK;

    if (out_plan == NULL) {
        return MYLITE_MISUSE;
    }

    value_node = unwrap_parenthesized_expression(out_plan->assignment_value_node);
    if (value_node == NULL || value_node->kind != MYLITE_SQL_AST_SCALAR_SUBQUERY) {
        return MYLITE_OK;
    }
    if (mylite_sql_ast_node_child_count(value_node) != 1U) {
        set_unsupported_error(
            database,
            "UPDATE scalar subquery assignment supports only parenthesized SELECT"
        );
        return MYLITE_ERROR;
    }

    statement = child_at(value_node, 0U);
    rc = validate_update_scalar_subquery_select(database, statement);
    if (rc == MYLITE_OK) {
        rc = plan_select(database, statement, &out_plan->assignment_subquery);
    }
    if (rc == MYLITE_OK && out_plan->assignment_subquery.column_count != 1U) {
        set_scalar_subquery_column_count_error(database);
        rc = MYLITE_ERROR;
    }
    if (rc == MYLITE_OK &&
        out_plan->assignment_subquery.table.table_id == out_plan->table.table_id) {
        set_update_table_used_error(database, out_plan->target.table_name);
        rc = MYLITE_ERROR;
    }
    if (rc == MYLITE_OK) {
        out_plan->assignment_value_is_scalar_subquery = true;
    }

    return rc;
}

static int validate_update_scalar_subquery_select(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *statement
) {
    const struct mylite_sql_ast_node *select_list = NULL;
    const struct mylite_sql_ast_node *from_clause = NULL;

    if (statement == NULL || statement->kind != MYLITE_SQL_AST_SELECT_STATEMENT) {
        set_unsupported_error(
            database,
            "UPDATE scalar subquery assignment supports only parenthesized SELECT"
        );
        return MYLITE_ERROR;
    }
    if (mylite_sql_ast_node_select_modifier(statement) != MYLITE_SQL_AST_SELECT_MODIFIER_DEFAULT ||
        mylite_sql_ast_node_select_options(statement) != 0U ||
        mylite_sql_ast_node_select_calc_found_rows(statement) != 0 ||
        mylite_sql_ast_node_select_locking_clause(statement) !=
            MYLITE_SQL_AST_SELECT_LOCKING_CLAUSE_NONE) {
        set_unsupported_error(
            database,
            "UPDATE scalar subquery assignment supports only plain inner SELECT"
        );
        return MYLITE_ERROR;
    }

    select_list = child_at(statement, 0U);
    if (select_list == NULL || select_list->kind != MYLITE_SQL_AST_SELECT_LIST ||
        select_list_is_wildcard(select_list)) {
        set_unsupported_error(
            database,
            "UPDATE scalar subquery assignment supports only one explicit source column"
        );
        return MYLITE_ERROR;
    }

    from_clause = child_at(statement, 1U);
    if (from_clause == NULL || from_clause->kind != MYLITE_SQL_AST_FROM_TABLE) {
        set_unsupported_error(
            database,
            "UPDATE scalar subquery assignment supports only one descriptor table source"
        );
        return MYLITE_ERROR;
    }

    return MYLITE_OK;
}

static int convert_update_value(
    struct mylite_db *database,
    const struct planned_update *plan,
    struct planned_value *out_value
) {
    const struct mylite_sql_ast_node *value_node = NULL;
    const struct mylite_catalog_column_descriptor *column = NULL;

    if (plan == NULL) {
        set_parse_error(database, NULL);
        return MYLITE_ERROR;
    }
    value_node = unwrap_parenthesized_expression(plan->assignment_value_node);
    column = &plan->assignment_column;
    if (value_node == NULL || column == NULL || out_value == NULL) {
        set_parse_error(database, NULL);
        return MYLITE_ERROR;
    }

    if (value_node->kind == MYLITE_SQL_AST_SCALAR_SUBQUERY) {
        planned_value_deinit(out_value);
        *out_value = (struct planned_value){.is_null = true, .is_text = false, .integer = 0};
        return materialize_update_scalar_subquery_value(database, plan, out_value);
    }
    if (value_node->kind == MYLITE_SQL_AST_DEFAULT_FUNCTION) {
        struct select_source_context source_context = {.source = &plan->target};

        return convert_default_function_value_for_target(
            database,
            value_node,
            &source_context,
            plan->columns,
            plan->column_count,
            column,
            false,
            out_value
        );
    }

    return convert_update_value_for_column(database, value_node, column, out_value);
}

static int convert_update_value_for_column(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *value_node,
    const struct mylite_catalog_column_descriptor *column,
    struct planned_value *out_value
) {
    bool handled = false;
    bool adjust_missing_default = dml_allows_missing_default_adjustment(database, false);
    int rc = MYLITE_OK;

    value_node = unwrap_parenthesized_expression(value_node);
    if (value_node == NULL || column == NULL || out_value == NULL) {
        set_parse_error(database, NULL);
        return MYLITE_ERROR;
    }

    planned_value_deinit(out_value);
    *out_value = (struct planned_value){.is_null = true, .is_text = false, .integer = 0};
    if (value_node->kind == MYLITE_SQL_AST_DML_DEFAULT_VALUE) {
        return materialize_dml_default_value(database, column, adjust_missing_default, out_value);
    }
    rc = convert_statement_time_value_for_column(database, value_node, column, out_value, &handled);
    if (handled) {
        return rc;
    }
    if (value_node->kind == MYLITE_SQL_AST_LITERAL &&
        mylite_sql_ast_node_literal_kind(value_node) == MYLITE_SQL_AST_LITERAL_NULL) {
        if (!column->is_nullable) {
            if (!adjust_missing_default) {
                if (column_descriptor_is_spatial(column)) {
                    set_spatial_bad_null_error(database, column->name);
                    return MYLITE_ERROR;
                }
                set_bad_null_error(database, column->name);
                return MYLITE_ERROR;
            }
            rc = append_bad_null_warning(database, column->name);
            if (rc != MYLITE_OK) {
                return rc;
            }
            return make_insert_ignore_implicit_value(database, column, out_value);
        }
        return MYLITE_OK;
    }

    return convert_update_column_value(database, value_node, column, out_value);
}

static int convert_statement_time_value_for_column(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *value_node,
    const struct mylite_catalog_column_descriptor *column,
    struct planned_value *out_value,
    bool *out_handled
) {
    if (out_handled == NULL) {
        set_parse_error(database, NULL);
        return MYLITE_ERROR;
    }
    *out_handled = true;

    switch (value_node->kind) {
    case MYLITE_SQL_AST_CURRENT_DATE_VALUE:
        if (column_descriptor_is_date(column)) {
            return make_current_date_value(database, out_value);
        }
        set_unsupported_error(database, "CURRENT_DATE values are supported only for DATE columns");
        return MYLITE_ERROR;
    case MYLITE_SQL_AST_CURRENT_TIME_VALUE:
        if (column_descriptor_is_time(column)) {
            return make_current_time_value(database, out_value);
        }
        set_unsupported_error(database, "CURRENT_TIME values are supported only for TIME columns");
        return MYLITE_ERROR;
    case MYLITE_SQL_AST_CURRENT_TIMESTAMP_VALUE:
        if (column_descriptor_is_datetime(column) || column_descriptor_is_timestamp(column)) {
            return make_current_timestamp_value(database, out_value);
        }
        set_unsupported_error(
            database,
            "CURRENT_TIMESTAMP values are supported only for DATETIME and TIMESTAMP columns"
        );
        return MYLITE_ERROR;
    case MYLITE_SQL_AST_UTC_DATE_VALUE:
        if (column_descriptor_is_date(column)) {
            return make_utc_date_value(database, out_value);
        }
        set_unsupported_error(database, "UTC_DATE values are supported only for DATE columns");
        return MYLITE_ERROR;
    case MYLITE_SQL_AST_UTC_TIME_VALUE:
        if (column_descriptor_is_time(column)) {
            return make_utc_time_value(database, out_value);
        }
        set_unsupported_error(database, "UTC_TIME values are supported only for TIME columns");
        return MYLITE_ERROR;
    case MYLITE_SQL_AST_UTC_TIMESTAMP_VALUE:
        if (column_descriptor_is_datetime(column) || column_descriptor_is_timestamp(column)) {
            return make_utc_timestamp_value(database, out_value);
        }
        set_unsupported_error(
            database,
            "UTC_TIMESTAMP values are supported only for DATETIME and TIMESTAMP columns"
        );
        return MYLITE_ERROR;
    case MYLITE_SQL_AST_CURRENT_TIMESTAMP_ARGUMENT_COUNT_ERROR:
        set_native_function_parameter_count_error(database, "CURRENT_TIMESTAMP");
        return MYLITE_ERROR;
    default:
        *out_handled = false;
        return MYLITE_OK;
    }
}

static int convert_update_column_value(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *value_node,
    const struct mylite_catalog_column_descriptor *column,
    struct planned_value *out_value
) {
    if (column_descriptor_is_char(column)) {
        return convert_char_literal(database, value_node, column, 1U, out_value);
    }
    if (column_descriptor_is_varchar(column)) {
        return convert_varchar_literal(database, value_node, column, 1U, out_value);
    }
    if (column_descriptor_is_text_family(column)) {
        return convert_text_family_literal(database, value_node, column, 1U, out_value);
    }
    if (column_descriptor_is_json(column)) {
        return convert_json_literal(database, value_node, column, out_value);
    }
    if (column_descriptor_is_enum(column)) {
        return convert_enum_literal(database, value_node, column, 1U, out_value);
    }
    if (column_descriptor_is_set(column)) {
        return convert_set_literal(database, value_node, column, 1U, out_value);
    }
    if (column_descriptor_is_binary_string_family(column)) {
        return convert_binary_string_literal(database, value_node, column, 1U, false, out_value);
    }
    if (column_descriptor_is_bit(column)) {
        return convert_bit_literal(database, value_node, column, 1U, false, out_value);
    }
    if (column_descriptor_is_year(column)) {
        return convert_year_literal(database, value_node, column, 1U, false, out_value);
    }
    if (column_descriptor_is_decimal(column)) {
        return convert_decimal_literal(database, value_node, column, 1U, false, out_value);
    }
    if (column_descriptor_is_approximate(column)) {
        return convert_approximate_literal(database, value_node, column, 1U, false, out_value);
    }
    if (column_descriptor_is_date(column)) {
        return convert_date_literal(database, value_node, column, 1U, false, out_value);
    }
    if (column_descriptor_is_time(column)) {
        return convert_time_literal(database, value_node, column, 1U, false, out_value);
    }
    if (column_descriptor_is_datetime(column)) {
        return convert_datetime_literal(database, value_node, column, 1U, false, out_value);
    }
    if (column_descriptor_is_timestamp(column)) {
        return convert_timestamp_literal(database, value_node, column, 1U, false, out_value);
    }
    if (column_descriptor_is_spatial(column)) {
        set_unsupported_error(database, "Spatial DML supports only NULL or DEFAULT values");
        return MYLITE_ERROR;
    }

    return convert_update_integer_literal(database, value_node, column, out_value);
}

static int materialize_update_scalar_subquery_value(
    struct mylite_db *database,
    const struct planned_update *plan,
    struct planned_value *out_value
) {
    sqlite3_stmt *statement = NULL;
    struct planned_select scalar_plan = plan->assignment_subquery;
    char *sql = NULL;
    int rc = MYLITE_OK;

    if (!plan->assignment_value_is_scalar_subquery ||
        plan->assignment_subquery.column_count != 1U) {
        set_unsupported_error(
            database,
            "UPDATE scalar subquery assignment supports only one descriptor source column"
        );
        return MYLITE_ERROR;
    }

    cap_update_scalar_subquery_limit(&scalar_plan.limit);
    rc = build_select_sql(&scalar_plan, &sql);
    if (rc == MYLITE_OK) {
        rc = prepare_sqlite_statement(database, sql, &statement);
    }
    if (rc == MYLITE_OK) {
        rc = bind_select_parameters(statement, &scalar_plan);
    }
    if (rc == MYLITE_OK) {
        rc = step_update_scalar_subquery_value(database, statement, plan, out_value);
    }
    rc = finalize_sqlite_statement(statement, rc);
    free(sql);

    if (rc == MYLITE_NOMEM) {
        set_nomem_error(database);
        return rc;
    }
    if (rc != MYLITE_OK &&
        mylite_diagnostics_errcode(mylite_connection_diagnostics(database)) == MYLITE_OK) {
        set_physical_sqlite_row_error(database);
        return MYLITE_ERROR;
    }

    return rc;
}

static void cap_update_scalar_subquery_limit(struct planned_select_limit *limit) {
    if (limit == NULL) {
        return;
    }
    if (!limit->has_limit) {
        *limit = (struct planned_select_limit){
            .has_limit = true,
            .row_count = 2,
            .has_offset = false,
            .offset = 0,
        };
        return;
    }
    if (limit->row_count > 2) {
        limit->row_count = 2;
    }
}

static int step_update_scalar_subquery_value(
    struct mylite_db *database,
    sqlite3_stmt *statement,
    const struct planned_update *plan,
    struct planned_value *out_value
) {
    int sqlite_rc = sqlite3_step(statement);
    int rc = MYLITE_OK;

    if (sqlite_rc == SQLITE_DONE) {
        if (!plan->assignment_column.is_nullable) {
            if (column_descriptor_is_spatial(&plan->assignment_column)) {
                set_spatial_bad_null_error(database, plan->assignment_column.name);
                return MYLITE_ERROR;
            }
            set_bad_null_error(database, plan->assignment_column.name);
            return MYLITE_ERROR;
        }
        *out_value = (struct planned_value){.is_null = true};
        return MYLITE_OK;
    }
    if (sqlite_rc != SQLITE_ROW) {
        return mylite_sqlite_status_to_mylite(sqlite_rc);
    }

    rc = materialize_update_scalar_subquery_sqlite_value(database, statement, plan, out_value);
    if (rc != MYLITE_OK) {
        return rc;
    }

    sqlite_rc = sqlite3_step(statement);
    if (sqlite_rc == SQLITE_ROW) {
        set_scalar_subquery_row_count_error(database);
        return MYLITE_ERROR;
    }
    if (sqlite_rc != SQLITE_DONE) {
        return mylite_sqlite_status_to_mylite(sqlite_rc);
    }

    return MYLITE_OK;
}

static int materialize_update_scalar_subquery_sqlite_value(
    struct mylite_db *database,
    sqlite3_stmt *statement,
    const struct planned_update *plan,
    struct planned_value *out_value
) {
    const struct mylite_catalog_column_descriptor *source_column =
        &plan->assignment_subquery.columns[0];
    const struct mylite_catalog_column_descriptor *target_column = &plan->assignment_column;
    int sqlite_type = sqlite3_column_type(statement, 0);

    if (sqlite_type == SQLITE_NULL) {
        if (!target_column->is_nullable) {
            if (column_descriptor_is_spatial(target_column)) {
                set_spatial_bad_null_error(database, target_column->name);
                return MYLITE_ERROR;
            }
            set_bad_null_error(database, target_column->name);
            return MYLITE_ERROR;
        }
        *out_value = (struct planned_value){.is_null = true};
        return MYLITE_OK;
    }
    if (!update_scalar_subquery_source_target_types_are_compatible(source_column, target_column)) {
        set_unsupported_error(
            database,
            update_scalar_subquery_implicit_conversion_message(target_column)
        );
        return MYLITE_ERROR;
    }
    if (column_descriptor_is_approximate(target_column)) {
        return materialize_update_scalar_subquery_approximate_value(
            database,
            statement,
            target_column,
            out_value
        );
    }
    if (update_scalar_subquery_target_uses_text_storage(target_column)) {
        return materialize_update_scalar_subquery_text_storage_value(
            database,
            statement,
            target_column,
            out_value
        );
    }
    if (update_scalar_subquery_target_uses_blob_storage(target_column)) {
        return materialize_update_scalar_subquery_blob_storage_value(
            database,
            statement,
            target_column,
            out_value
        );
    }

    return materialize_update_scalar_subquery_integer_value(
        database,
        statement,
        sqlite_type,
        target_column,
        out_value
    );
}

static bool update_scalar_subquery_target_uses_text_storage(
    const struct mylite_catalog_column_descriptor *target_column
) {
    if (column_descriptor_is_string_family(target_column)) {
        return true;
    }
    if (column_descriptor_is_json(target_column)) {
        return true;
    }
    if (column_descriptor_is_decimal(target_column)) {
        return true;
    }
    if (column_descriptor_is_date(target_column)) {
        return true;
    }
    if (column_descriptor_is_time(target_column)) {
        return true;
    }
    if (column_descriptor_is_datetime(target_column)) {
        return true;
    }
    if (column_descriptor_is_timestamp(target_column)) {
        return true;
    }
    if (column_descriptor_is_year(target_column)) {
        return true;
    }
    return false;
}

static bool update_scalar_subquery_target_uses_blob_storage(
    const struct mylite_catalog_column_descriptor *target_column
) {
    return (column_descriptor_is_binary_string_family(target_column) ||
            column_descriptor_is_bit(target_column)) != 0;
}

static int materialize_update_scalar_subquery_text_storage_value(
    struct mylite_db *database,
    sqlite3_stmt *statement,
    const struct mylite_catalog_column_descriptor *target_column,
    struct planned_value *out_value
) {
    int rc = validate_update_scalar_subquery_text_storage_value(database, statement, target_column);

    if (rc == MYLITE_OK) {
        rc = copy_update_scalar_subquery_text_value(database, statement, 0, out_value);
    }
    return rc;
}

static int materialize_update_scalar_subquery_blob_storage_value(
    struct mylite_db *database,
    sqlite3_stmt *statement,
    const struct mylite_catalog_column_descriptor *target_column,
    struct planned_value *out_value
) {
    if (column_descriptor_is_bit(target_column)) {
        return materialize_sqlite_bit_value(database, statement, 0, target_column, 1U, out_value);
    }
    return materialize_sqlite_binary_string_value(
        database,
        statement,
        0,
        target_column,
        1U,
        out_value
    );
}

static int validate_update_scalar_subquery_text_storage_value(
    struct mylite_db *database,
    sqlite3_stmt *statement,
    const struct mylite_catalog_column_descriptor *target_column
) {
    if (column_descriptor_is_string_family(target_column)) {
        return validate_insert_select_string_value(database, statement, 0, target_column, 1U);
    }
    if (column_descriptor_is_json(target_column)) {
        return validate_insert_select_json_value(database, statement, 0, target_column);
    }
    if (column_descriptor_is_decimal(target_column)) {
        return validate_insert_select_decimal_value(database, statement, 0, target_column, 1U);
    }
    if (column_descriptor_is_date(target_column)) {
        return validate_insert_select_date_value(database, statement, 0, target_column, 1U);
    }
    if (column_descriptor_is_time(target_column)) {
        return validate_insert_select_time_value(database, statement, 0, target_column, 1U);
    }
    if (column_descriptor_is_datetime(target_column)) {
        return validate_insert_select_datetime_value(database, statement, 0, target_column, 1U);
    }
    if (column_descriptor_is_year(target_column)) {
        return validate_insert_select_year_value(database, statement, 0, target_column, 1U);
    }
    return validate_insert_select_timestamp_value(database, statement, 0, target_column, 1U);
}

static int materialize_update_scalar_subquery_approximate_value(
    struct mylite_db *database,
    sqlite3_stmt *statement,
    const struct mylite_catalog_column_descriptor *target_column,
    struct planned_value *out_value
) {
    int rc = validate_insert_select_approximate_value(database, statement, 0, target_column, 1U);

    if (rc == MYLITE_OK) {
        *out_value = (struct planned_value){
            .is_null = false,
            .is_real = true,
            .real = sqlite3_column_double(statement, 0),
        };
    }
    return rc;
}

static int materialize_update_scalar_subquery_integer_value(
    struct mylite_db *database,
    sqlite3_stmt *statement,
    int sqlite_type,
    const struct mylite_catalog_column_descriptor *target_column,
    struct planned_value *out_value
) {
    int rc = MYLITE_OK;

    if (sqlite_type != SQLITE_INTEGER) {
        set_unsupported_error(
            database,
            "UPDATE scalar subquery assignment does not support implicit integer conversion"
        );
        return MYLITE_ERROR;
    }

    rc = validate_insert_select_integer_value(database, statement, 0, target_column, 1U);
    if (rc == MYLITE_OK) {
        *out_value = (struct planned_value){
            .is_null = false,
            .integer = (int64_t)sqlite3_column_int64(statement, 0),
        };
    }
    return rc;
}

static int copy_update_scalar_subquery_text_value(
    struct mylite_db *database,
    sqlite3_stmt *statement,
    int selected_column_index,
    struct planned_value *out_value
) {
    const unsigned char *text = sqlite3_column_text(statement, selected_column_index);
    int byte_count = sqlite3_column_bytes(statement, selected_column_index);
    char *copy = NULL;

    if (text == NULL || byte_count < 0) {
        set_physical_sqlite_row_error(database);
        return MYLITE_ERROR;
    }
    copy = malloc((size_t)byte_count + 1U);
    if (copy == NULL) {
        set_nomem_error(database);
        return MYLITE_NOMEM;
    }
    memcpy(copy, text, (size_t)byte_count);
    copy[(size_t)byte_count] = '\0';

    return assign_text_value(database, copy, (size_t)byte_count, out_value);
}

static bool update_scalar_subquery_source_target_types_are_compatible(
    const struct mylite_catalog_column_descriptor *source_column,
    const struct mylite_catalog_column_descriptor *target_column
) {
    return insert_select_source_target_types_are_compatible(source_column, target_column);
}

static const char *update_scalar_subquery_implicit_conversion_message(
    const struct mylite_catalog_column_descriptor *target_column
) {
    if (column_descriptor_is_string_family(target_column)) {
        return "UPDATE scalar subquery assignment does not support implicit string conversion";
    }
    if (column_descriptor_is_json(target_column)) {
        return "UPDATE scalar subquery assignment does not support implicit JSON conversion";
    }
    if (column_descriptor_is_enum(target_column)) {
        return "UPDATE scalar subquery assignment does not support implicit ENUM conversion";
    }
    if (column_descriptor_is_set(target_column)) {
        return "UPDATE scalar subquery assignment does not support implicit SET conversion";
    }
    if (column_descriptor_is_binary_string_family(target_column)) {
        return "UPDATE scalar subquery assignment does not support implicit binary string "
               "conversion";
    }
    if (column_descriptor_is_bit(target_column)) {
        return "UPDATE scalar subquery assignment does not support implicit BIT conversion";
    }
    if (column_descriptor_is_decimal(target_column)) {
        return "UPDATE scalar subquery assignment does not support implicit DECIMAL conversion";
    }
    if (column_descriptor_is_approximate(target_column)) {
        return "UPDATE scalar subquery assignment does not support implicit FLOAT or DOUBLE "
               "conversion";
    }
    if (column_descriptor_is_date(target_column)) {
        return "UPDATE scalar subquery assignment does not support implicit DATE conversion";
    }
    if (column_descriptor_is_time(target_column)) {
        return "UPDATE scalar subquery assignment does not support implicit TIME conversion";
    }
    if (column_descriptor_is_datetime(target_column)) {
        return "UPDATE scalar subquery assignment does not support implicit DATETIME conversion";
    }
    if (column_descriptor_is_timestamp(target_column)) {
        return "UPDATE scalar subquery assignment does not support implicit TIMESTAMP conversion";
    }
    if (column_descriptor_is_year(target_column)) {
        return "UPDATE scalar subquery assignment does not support implicit YEAR conversion";
    }

    return "UPDATE scalar subquery assignment does not support implicit integer conversion";
}

static int convert_update_integer_literal(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *value_node,
    const struct mylite_catalog_column_descriptor *column,
    struct planned_value *out_value
) {
    const struct mylite_sql_ast_node *literal = value_node;
    bool is_negative = false;
    uint64_t magnitude = 0U;
    int rc = MYLITE_OK;

    if (value_node->kind == MYLITE_SQL_AST_UNARY_EXPRESSION) {
        enum mylite_sql_ast_operator operator_kind = mylite_sql_ast_node_operator(value_node);

        if (operator_kind == MYLITE_SQL_AST_OPERATOR_NEGATIVE) {
            is_negative = true;
        } else if (operator_kind != MYLITE_SQL_AST_OPERATOR_POSITIVE) {
            set_unsupported_error(
                database,
                "UPDATE supports only integer, boolean, NULL, and DEFAULT assignment values"
            );
            return MYLITE_ERROR;
        }
        literal = child_at(value_node, 0U);
    }
    if (!boolean_literal_magnitude(literal, &magnitude)) {
        if (literal == NULL || literal->kind != MYLITE_SQL_AST_LITERAL ||
            (mylite_sql_ast_node_literal_kind(literal) != MYLITE_SQL_AST_LITERAL_INTEGER &&
             mylite_sql_ast_node_literal_kind(literal) != MYLITE_SQL_AST_LITERAL_STRING)) {
            set_unsupported_error(
                database,
                "UPDATE supports only integer, boolean, NULL, and DEFAULT assignment values"
            );
            return MYLITE_ERROR;
        }
        if (mylite_sql_ast_node_literal_kind(literal) == MYLITE_SQL_AST_LITERAL_STRING) {
            return convert_integer_string_literal(database, literal, column, 1U, false, out_value);
        }

        rc = parse_unsigned_integer_literal(&literal->span, &magnitude);
        if (rc != MYLITE_OK) {
            set_out_of_range_error(database, column->name, 1U);
            return MYLITE_ERROR;
        }
    }

    out_value->is_null = false;
    rc = convert_integer_for_column(
        database,
        magnitude,
        is_negative,
        column,
        1U,
        &out_value->integer
    );
    if (rc != MYLITE_OK) {
        return rc;
    }

    return MYLITE_OK;
}

static int plan_update_limit(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *limit_clause,
    struct planned_select_limit *out_limit
) {
    int rc = MYLITE_OK;

    out_limit->has_limit = false;
    out_limit->row_count = 0;
    out_limit->has_offset = false;
    out_limit->offset = 0;
    if (limit_clause == NULL) {
        return MYLITE_OK;
    }
    if (limit_clause->kind != MYLITE_SQL_AST_LIMIT_CLAUSE) {
        set_unsupported_error(database, "UPDATE supports only LIMIT row_count");
        return MYLITE_ERROR;
    }
    if (child_at(limit_clause, 1U) != NULL) {
        set_unsupported_error(database, "UPDATE supports only LIMIT row_count");
        return MYLITE_ERROR;
    }

    rc = convert_limit_integer_literal(database, child_at(limit_clause, 0U), &out_limit->row_count);
    if (rc != MYLITE_OK) {
        return rc;
    }
    out_limit->has_limit = true;

    return MYLITE_OK;
}

static int convert_limit_integer_literal(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *value_node,
    int64_t *out_value
) {
    const uint64_t sqlite_int64_positive_max = 9223372036854775807ULL;
    uint64_t magnitude = 0U;
    int rc = MYLITE_OK;

    if (value_node == NULL || value_node->kind != MYLITE_SQL_AST_LITERAL ||
        mylite_sql_ast_node_literal_kind(value_node) != MYLITE_SQL_AST_LITERAL_INTEGER) {
        set_unsupported_error(database, "LIMIT supports only unsigned decimal integer literals");
        return MYLITE_ERROR;
    }

    rc = parse_unsigned_integer_literal(&value_node->span, &magnitude);
    if (rc != MYLITE_OK || magnitude > sqlite_int64_positive_max) {
        set_limit_out_of_range_error(database);
        return MYLITE_ERROR;
    }

    *out_value = (int64_t)magnitude;
    return MYLITE_OK;
}

static int integer_range_for_column(
    struct mylite_db *database,
    const struct mylite_catalog_column_descriptor *column,
    const char *unsupported_message,
    struct integer_column_range *out_range
) {
    const uint64_t int_signed_positive_max = 2147483647ULL;
    const uint64_t int_signed_negative_abs_max = 2147483648ULL;
    const uint64_t int_unsigned_max = 4294967295ULL;
    const uint64_t mediumint_signed_positive_max = 8388607ULL;
    const uint64_t mediumint_signed_negative_abs_max = 8388608ULL;
    const uint64_t mediumint_unsigned_max = 16777215ULL;
    const uint64_t smallint_signed_positive_max = 32767ULL;
    const uint64_t smallint_signed_negative_abs_max = 32768ULL;
    const uint64_t smallint_unsigned_max = 65535ULL;
    const uint64_t tinyint_signed_positive_max = 127ULL;
    const uint64_t tinyint_signed_negative_abs_max = 128ULL;
    const uint64_t tinyint_unsigned_max = 255ULL;
    const uint64_t bigint_signed_positive_max = 9223372036854775807ULL;
    const uint64_t bigint_signed_negative_abs_max = 9223372036854775808ULL;

    if (strcmp(column->logical_type, "TINYINT") == 0) {
        *out_range = (struct integer_column_range){
            .positive_max = tinyint_signed_positive_max,
            .negative_abs_max = tinyint_signed_negative_abs_max,
        };
        return MYLITE_OK;
    }
    if (strcmp(column->logical_type, "TINYINT(1)") == 0) {
        *out_range = (struct integer_column_range){
            .positive_max = tinyint_signed_positive_max,
            .negative_abs_max = tinyint_signed_negative_abs_max,
        };
        return MYLITE_OK;
    }
    if (strcmp(column->logical_type, "TINYINT UNSIGNED") == 0) {
        *out_range = (struct integer_column_range){
            .positive_max = tinyint_unsigned_max,
            .negative_abs_max = 0U,
        };
        return MYLITE_OK;
    }
    if (strcmp(column->logical_type, "SMALLINT") == 0) {
        *out_range = (struct integer_column_range){
            .positive_max = smallint_signed_positive_max,
            .negative_abs_max = smallint_signed_negative_abs_max,
        };
        return MYLITE_OK;
    }
    if (strcmp(column->logical_type, "SMALLINT UNSIGNED") == 0) {
        *out_range = (struct integer_column_range){
            .positive_max = smallint_unsigned_max,
            .negative_abs_max = 0U,
        };
        return MYLITE_OK;
    }
    if (strcmp(column->logical_type, "MEDIUMINT") == 0) {
        *out_range = (struct integer_column_range){
            .positive_max = mediumint_signed_positive_max,
            .negative_abs_max = mediumint_signed_negative_abs_max,
        };
        return MYLITE_OK;
    }
    if (strcmp(column->logical_type, "MEDIUMINT UNSIGNED") == 0) {
        *out_range = (struct integer_column_range){
            .positive_max = mediumint_unsigned_max,
            .negative_abs_max = 0U,
        };
        return MYLITE_OK;
    }
    if (strcmp(column->logical_type, "INT") == 0) {
        *out_range = (struct integer_column_range){
            .positive_max = int_signed_positive_max,
            .negative_abs_max = int_signed_negative_abs_max,
        };
        return MYLITE_OK;
    }
    if (strcmp(column->logical_type, "INT UNSIGNED") == 0) {
        *out_range = (struct integer_column_range){
            .positive_max = int_unsigned_max,
            .negative_abs_max = 0U,
        };
        return MYLITE_OK;
    }
    if (strcmp(column->logical_type, "BIGINT") == 0) {
        *out_range = (struct integer_column_range){
            .positive_max = bigint_signed_positive_max,
            .negative_abs_max = bigint_signed_negative_abs_max,
        };
        return MYLITE_OK;
    }
    if (strcmp(column->logical_type, "BIGINT UNSIGNED") == 0) {
        *out_range = (struct integer_column_range){
            .positive_max = bigint_signed_positive_max,
            .negative_abs_max = 0U,
        };
        return MYLITE_OK;
    }

    set_unsupported_error(database, unsupported_message);
    return MYLITE_ERROR;
}

static int append_show_table(const struct mylite_catalog_table_descriptor *table, void *user_data) {
    struct show_tables_context *context = user_data;
    const char *values[2] = {NULL, NULL};

    if (table == NULL || context == NULL || context->result == NULL) {
        return MYLITE_MISUSE;
    }
    if (table->kind != MYLITE_CATALOG_TABLE_KIND_BASE) {
        return MYLITE_OK;
    }

    if (!show_like_filter_matches(context->filter, table->name, true)) {
        return MYLITE_OK;
    }

    values[0] = table->name;
    if (context->is_full) {
        values[1] = "BASE TABLE";
    }

    return mylite_result_append_text_row(context->result, values);
}

static int append_show_table_status(
    const struct mylite_catalog_table_descriptor *table,
    void *user_data
) {
    struct show_table_status_context *context = user_data;
    struct table_status_values status = {0};
    bool where_matches = true;
    int rc = MYLITE_OK;

    if (table == NULL || context == NULL || context->database == NULL || context->result == NULL) {
        return MYLITE_MISUSE;
    }
    if (table->kind != MYLITE_CATALOG_TABLE_KIND_BASE) {
        return MYLITE_OK;
    }
    if (!show_like_filter_matches(context->filter, table->name, true)) {
        return MYLITE_OK;
    }

    rc = load_table_status_values(context->database, table, &status);
    if (rc != MYLITE_OK) {
        return rc;
    }

    const char *values[show_table_status_result_column_count] = {
        table->name,
        "InnoDB",
        "10",
        "Dynamic",
        status.row_count_text,
        status.average_row_length_text,
        "16384",
        "0",
        status.index_length,
        "0",
        status.auto_increment,
        status.create_time,
        status.update_time,
        NULL,
        table->default_collation,
        NULL,
        "",
        table->comment,
    };

    if (context->where_clause != NULL) {
        rc = show_table_status_where_clause_matches(
            context->database,
            context->where_clause,
            values,
            &where_matches
        );
    }
    if (rc == MYLITE_OK && !where_matches) {
        return MYLITE_OK;
    }
    if (rc == MYLITE_OK) {
        rc = mylite_result_append_text_row(context->result, values);
    }
    if (rc == MYLITE_NOMEM) {
        set_nomem_error(context->database);
    }
    return rc;
}

static int validate_show_table_status_where_clause(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *where_clause
) {
    static const char *const validation_values[show_table_status_result_column_count] = {
        "table_name",
        "InnoDB",
        "10",
        "Dynamic",
        "0",
        "0",
        "16384",
        "0",
        "0",
        "0",
        "0",
        "2000-01-01 00:00:00",
        "2000-01-01 00:00:00",
        "2000-01-01 00:00:00",
        "utf8mb4_0900_ai_ci",
        "0",
        "",
        "",
    };
    bool matches = false;

    if (where_clause == NULL) {
        return MYLITE_OK;
    }
    return show_table_status_where_clause_matches(
        database,
        where_clause,
        validation_values,
        &matches
    );
}

static int show_table_status_where_clause_matches(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *where_clause,
    const char *const values[show_table_status_result_column_count],
    bool *out_matches
) {
    enum show_variables_where_truth truth = SHOW_VARIABLES_WHERE_FALSE;
    int rc = MYLITE_OK;

    if (where_clause == NULL || where_clause->kind != MYLITE_SQL_AST_WHERE_CLAUSE ||
        values == NULL || out_matches == NULL) {
        set_runtime_error(database, "invalid SHOW TABLE STATUS WHERE predicate");
        return MYLITE_ERROR;
    }

    *out_matches = false;
    rc = evaluate_show_table_status_where_predicate(
        database,
        child_at(where_clause, 0U),
        values,
        &truth
    );
    if (rc == MYLITE_OK) {
        *out_matches = truth == SHOW_VARIABLES_WHERE_TRUE;
    }
    return rc;
}

static int evaluate_show_table_status_where_predicate(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *predicate,
    const char *const values[show_table_status_result_column_count],
    enum show_variables_where_truth *out_truth
) {
    struct show_variables_where_frame_stack frame_stack = {0};
    struct show_variables_where_truth_stack truth_stack = {0};
    struct show_variables_where_eval_frame frame = {
        .node = predicate,
        .action = SHOW_VARIABLES_WHERE_VISIT,
    };
    int rc = MYLITE_OK;

    if (predicate == NULL || values == NULL || out_truth == NULL) {
        set_runtime_error(database, "invalid SHOW TABLE STATUS WHERE predicate");
        return MYLITE_ERROR;
    }

    rc = show_variables_where_frame_stack_push(database, &frame_stack, frame);
    while (rc == MYLITE_OK && show_variables_where_frame_stack_pop(&frame_stack, &frame)) {
        const struct mylite_sql_ast_node *current = unwrap_parenthesized_predicate(frame.node);

        if (current == NULL) {
            set_runtime_error(database, "invalid SHOW TABLE STATUS WHERE predicate");
            rc = MYLITE_ERROR;
        } else if (frame.action == SHOW_VARIABLES_WHERE_VISIT) {
            rc = visit_show_table_status_where_predicate(database, &frame_stack, current);
        } else {
            rc = evaluate_show_table_status_where_frame(database, current, values, &truth_stack);
        }
    }

    if (rc == MYLITE_OK) {
        if (truth_stack.count != 1U ||
            !show_variables_where_truth_stack_pop(&truth_stack, out_truth)) {
            set_runtime_error(database, "invalid SHOW TABLE STATUS WHERE predicate state");
            rc = MYLITE_ERROR;
        }
    }

    show_variables_where_truth_stack_deinit(&truth_stack);
    show_variables_where_frame_stack_deinit(&frame_stack);
    return rc;
}

static int visit_show_table_status_where_predicate(
    struct mylite_db *database,
    struct show_variables_where_frame_stack *frame_stack,
    const struct mylite_sql_ast_node *predicate
) {
    int rc = show_variables_where_frame_stack_push(
        database,
        frame_stack,
        (struct show_variables_where_eval_frame){
            .node = predicate,
            .action = SHOW_VARIABLES_WHERE_EVALUATE,
        }
    );

    if (rc != MYLITE_OK) {
        return rc;
    }
    if (predicate->kind == MYLITE_SQL_AST_NOT_PREDICATE) {
        return show_variables_where_frame_stack_push(
            database,
            frame_stack,
            (struct show_variables_where_eval_frame){
                .node = child_at(predicate, 0U),
                .action = SHOW_VARIABLES_WHERE_VISIT,
            }
        );
    }
    if (predicate->kind == MYLITE_SQL_AST_AND_PREDICATE ||
        predicate->kind == MYLITE_SQL_AST_OR_PREDICATE) {
        rc = show_variables_where_frame_stack_push(
            database,
            frame_stack,
            (struct show_variables_where_eval_frame){
                .node = child_at(predicate, 1U),
                .action = SHOW_VARIABLES_WHERE_VISIT,
            }
        );
        if (rc == MYLITE_OK) {
            rc = show_variables_where_frame_stack_push(
                database,
                frame_stack,
                (struct show_variables_where_eval_frame){
                    .node = child_at(predicate, 0U),
                    .action = SHOW_VARIABLES_WHERE_VISIT,
                }
            );
        }
    }
    return rc;
}

static int evaluate_show_table_status_where_frame(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *predicate,
    const char *const values[show_table_status_result_column_count],
    struct show_variables_where_truth_stack *truth_stack
) {
    enum show_variables_where_truth truth = SHOW_VARIABLES_WHERE_FALSE;
    int rc = MYLITE_OK;

    if (predicate->kind == MYLITE_SQL_AST_COMPARISON_PREDICATE) {
        rc = evaluate_show_table_status_where_comparison_predicate(
            database,
            predicate,
            values,
            &truth
        );
    } else if (predicate->kind == MYLITE_SQL_AST_IN_PREDICATE) {
        rc = evaluate_show_table_status_where_in_predicate(database, predicate, values, &truth);
    } else if (predicate->kind == MYLITE_SQL_AST_IS_NULL_PREDICATE) {
        rc =
            evaluate_show_table_status_where_is_null_predicate(database, predicate, values, &truth);
    } else if (predicate->kind == MYLITE_SQL_AST_NOT_PREDICATE) {
        enum show_variables_where_truth child_truth = SHOW_VARIABLES_WHERE_FALSE;

        if (!show_variables_where_truth_stack_pop(truth_stack, &child_truth)) {
            set_runtime_error(database, "invalid SHOW TABLE STATUS WHERE predicate stack");
            return MYLITE_ERROR;
        }
        truth = negate_show_variables_where_truth(child_truth);
    } else if (
        predicate->kind == MYLITE_SQL_AST_AND_PREDICATE ||
        predicate->kind == MYLITE_SQL_AST_OR_PREDICATE
    ) {
        rc = evaluate_show_variables_where_logical_frame(database, predicate, truth_stack, &truth);
    } else if (predicate->kind == MYLITE_SQL_AST_XOR_PREDICATE) {
        set_unsupported_error(database, "SHOW TABLE STATUS WHERE does not support XOR predicates");
        return MYLITE_ERROR;
    } else {
        set_unsupported_error(
            database,
            "SHOW TABLE STATUS WHERE supports output-column predicates"
        );
        return MYLITE_ERROR;
    }
    if (rc == MYLITE_OK) {
        rc = show_variables_where_truth_stack_push(database, truth_stack, truth);
    }
    return rc;
}

static int evaluate_show_table_status_where_comparison_predicate(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *predicate,
    const char *const values[show_table_status_result_column_count],
    enum show_variables_where_truth *out_truth
) {
    const struct mylite_sql_ast_node *left_node = child_at(predicate, 0U);
    const struct mylite_sql_ast_node *right_node = child_at(predicate, 1U);
    const char *left = NULL;
    size_t column_index = 0U;
    enum mylite_sql_ast_operator operator_kind = mylite_sql_ast_node_operator(predicate);
    int rc =
        show_table_status_where_column_value(database, left_node, values, &left, &column_index);
    static const struct show_metadata_regexp_messages regexp_messages = {
        .literal = "SHOW TABLE STATUS WHERE REGEXP predicates support only string pattern literals",
        .nul = "SHOW TABLE STATUS WHERE REGEXP pattern literals do not support NUL bytes",
        .ascii = "SHOW TABLE STATUS WHERE REGEXP pattern literals support only ASCII text",
        .unsupported =
            "SHOW TABLE STATUS WHERE REGEXP patterns support only MyLite's baseline ASCII regular "
            "expression subset",
    };

    if (rc != MYLITE_OK) {
        return rc;
    }
    if (operator_kind == MYLITE_SQL_AST_OPERATOR_REGEXP ||
        operator_kind == MYLITE_SQL_AST_OPERATOR_RLIKE) {
        (void)column_index;
        return evaluate_show_metadata_where_regexp_predicate(
            database,
            left,
            right_node,
            &regexp_messages,
            show_table_status_where_column_is_case_sensitive(column_index),
            out_truth
        );
    }
    if (operator_kind == MYLITE_SQL_AST_OPERATOR_LIKE) {
        char *pattern = NULL;

        if (left == NULL) {
            *out_truth = SHOW_VARIABLES_WHERE_UNKNOWN;
            return MYLITE_OK;
        }
        rc = decode_show_table_status_where_string_literal(database, right_node, &pattern);
        if (rc == MYLITE_OK) {
            bool matches = show_like_pattern_matches(
                pattern,
                strlen(pattern),
                left,
                strlen(left),
                show_table_status_where_column_is_case_sensitive(column_index)
            );

            if (matches) {
                *out_truth = SHOW_VARIABLES_WHERE_TRUE;
            } else {
                *out_truth = SHOW_VARIABLES_WHERE_FALSE;
            }
        }
        free(pattern);
        return rc;
    }

    return compare_show_table_status_where_literal(
        database,
        operator_kind,
        left,
        column_index,
        right_node,
        out_truth
    );
}

static int evaluate_show_table_status_where_in_predicate(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *predicate,
    const char *const values[show_table_status_result_column_count],
    enum show_variables_where_truth *out_truth
) {
    const struct mylite_sql_ast_node *left_node = child_at(predicate, 0U);
    const struct mylite_sql_ast_node *value_list = child_at(predicate, 1U);
    const char *left = NULL;
    size_t column_index = 0U;
    size_t value_count = 0U;
    bool saw_null = false;
    int rc =
        show_table_status_where_column_value(database, left_node, values, &left, &column_index);

    if (rc != MYLITE_OK) {
        return rc;
    }
    if (left == NULL) {
        *out_truth = SHOW_VARIABLES_WHERE_UNKNOWN;
        return MYLITE_OK;
    }
    if (value_list == NULL || value_list->kind != MYLITE_SQL_AST_PREDICATE_VALUE_LIST) {
        set_runtime_error(database, "invalid SHOW TABLE STATUS WHERE IN list");
        return MYLITE_ERROR;
    }

    value_count = mylite_sql_ast_node_child_count(value_list);
    for (size_t index = 0U; index < value_count; ++index) {
        const struct mylite_sql_ast_node *value_node = child_at(value_list, index);
        enum mylite_sql_ast_literal_kind literal_kind = MYLITE_SQL_AST_LITERAL_NONE;
        char *right = NULL;

        if (value_node == NULL || value_node->kind != MYLITE_SQL_AST_LITERAL) {
            set_unsupported_error(
                database,
                "SHOW TABLE STATUS WHERE IN supports only string and NULL literals"
            );
            return MYLITE_ERROR;
        }

        literal_kind = mylite_sql_ast_node_literal_kind(value_node);
        if (literal_kind == MYLITE_SQL_AST_LITERAL_NULL) {
            saw_null = true;
            continue;
        }
        rc = decode_show_table_status_where_string_literal(database, value_node, &right);
        if (rc == MYLITE_OK) {
            bool equal = false;

            rc = show_table_status_where_texts_are_equal(
                database,
                left,
                right,
                column_index,
                &equal
            );
            if (rc == MYLITE_OK && equal) {
                *out_truth = SHOW_VARIABLES_WHERE_TRUE;
                free(right);
                return MYLITE_OK;
            }
        }
        free(right);
        if (rc != MYLITE_OK) {
            return rc;
        }
    }

    if (saw_null) {
        *out_truth = SHOW_VARIABLES_WHERE_UNKNOWN;
    } else {
        *out_truth = SHOW_VARIABLES_WHERE_FALSE;
    }
    return MYLITE_OK;
}

static int evaluate_show_table_status_where_is_null_predicate(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *predicate,
    const char *const values[show_table_status_result_column_count],
    enum show_variables_where_truth *out_truth
) {
    const char *value = NULL;
    size_t column_index = 0U;
    int rc = show_table_status_where_column_value(
        database,
        child_at(predicate, 0U),
        values,
        &value,
        &column_index
    );

    (void)column_index;
    if (rc != MYLITE_OK) {
        return rc;
    }
    if (mylite_sql_ast_node_operator(predicate) == MYLITE_SQL_AST_OPERATOR_IS_NOT_NULL) {
        *out_truth = value == NULL ? SHOW_VARIABLES_WHERE_FALSE : SHOW_VARIABLES_WHERE_TRUE;
    } else {
        *out_truth = value == NULL ? SHOW_VARIABLES_WHERE_TRUE : SHOW_VARIABLES_WHERE_FALSE;
    }
    return MYLITE_OK;
}

static int show_table_status_where_column_value(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *column_node,
    const char *const values[show_table_status_result_column_count],
    const char **out_value,
    size_t *out_column_index
) {
    size_t column_index = 0U;
    int rc = resolve_show_table_status_where_column(database, column_node, &column_index);

    if (rc != MYLITE_OK) {
        return rc;
    }
    if (values == NULL || out_value == NULL || out_column_index == NULL) {
        set_runtime_error(database, "invalid SHOW TABLE STATUS WHERE row");
        return MYLITE_ERROR;
    }

    *out_value = values[column_index];
    *out_column_index = column_index;
    return MYLITE_OK;
}

static int resolve_show_table_status_where_column(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *column_node,
    size_t *out_column_index
) {
    char parts[table_name_part_capacity][MYLITE_CATALOG_IDENTIFIER_CAPACITY];
    char *display_text = NULL;
    size_t part_count = 0U;
    int rc = MYLITE_OK;

    if (out_column_index == NULL) {
        return MYLITE_MISUSE;
    }
    *out_column_index = 0U;
    if (column_node == NULL || (column_node->kind != MYLITE_SQL_AST_IDENTIFIER &&
                                column_node->kind != MYLITE_SQL_AST_QUALIFIED_IDENTIFIER)) {
        set_unsupported_error(database, "SHOW TABLE STATUS WHERE supports only output columns");
        return MYLITE_ERROR;
    }

    rc = collect_identifier_parts(
        column_node,
        parts,
        table_name_part_capacity,
        &part_count,
        database
    );
    if (rc != MYLITE_OK) {
        return rc;
    }
    if (part_count == 1U) {
        for (size_t column_index = 0U; column_index < show_table_status_result_column_count;
             ++column_index) {
            if (text_equals_ascii_case_insensitive(
                    parts[0],
                    show_table_status_result_columns[column_index]
                )) {
                *out_column_index = column_index;
                return MYLITE_OK;
            }
        }
    }

    rc = show_variables_column_reference_text(database, column_node, &display_text);
    if (rc == MYLITE_OK) {
        set_unknown_where_column_error(database, display_text);
        rc = MYLITE_ERROR;
    }
    free(display_text);
    return rc;
}

static int compare_show_table_status_where_literal(
    struct mylite_db *database,
    enum mylite_sql_ast_operator operator_kind,
    const char *left,
    size_t column_index,
    const struct mylite_sql_ast_node *right,
    enum show_variables_where_truth *out_truth
) {
    enum mylite_sql_ast_literal_kind literal_kind = MYLITE_SQL_AST_LITERAL_NONE;
    char *right_text = NULL;
    int comparison = 0;
    int rc = MYLITE_OK;

    if (right == NULL || out_truth == NULL) {
        set_runtime_error(database, "invalid SHOW TABLE STATUS WHERE comparison");
        return MYLITE_ERROR;
    }
    if (right->kind != MYLITE_SQL_AST_LITERAL) {
        set_unsupported_error(
            database,
            "SHOW TABLE STATUS WHERE comparisons support only string and NULL literals"
        );
        return MYLITE_ERROR;
    }

    literal_kind = mylite_sql_ast_node_literal_kind(right);
    if (compare_show_table_status_where_null_operand(
            operator_kind,
            left,
            literal_kind,
            out_truth
        )) {
        return MYLITE_OK;
    }

    rc = decode_show_table_status_where_string_literal(database, right, &right_text);
    if (rc != MYLITE_OK) {
        free(right_text);
        return rc;
    }

    rc =
        show_table_status_where_compare_text(database, left, right_text, column_index, &comparison);
    if (rc == MYLITE_OK) {
        rc = show_table_status_where_truth_from_comparison(
            database,
            operator_kind,
            (struct show_table_status_where_comparison){.value = comparison},
            out_truth
        );
    }

    free(right_text);
    return rc;
}

static int show_table_status_where_compare_text(
    struct mylite_db *database,
    const char *left,
    const char *right,
    size_t column_index,
    int *out_comparison
) {
    if (out_comparison == NULL) {
        return MYLITE_MISUSE;
    }
    *out_comparison = 0;
    if (show_table_status_where_column_is_numeric(column_index)) {
        return show_table_status_where_compare_numeric_text(database, left, right, out_comparison);
    }

    *out_comparison = compare_show_table_status_where_text(left, right, column_index);
    return MYLITE_OK;
}

static int show_table_status_where_compare_numeric_text(
    struct mylite_db *database,
    const char *left,
    const char *right,
    int *out_comparison
) {
    uint64_t left_value = 0U;
    uint64_t right_value = 0U;

    if (!parse_show_table_status_where_unsigned_text(left, &left_value) ||
        !parse_show_table_status_where_unsigned_text(right, &right_value)) {
        set_unsupported_error(
            database,
            "SHOW TABLE STATUS WHERE numeric columns support only unsigned decimal string "
            "predicates"
        );
        return MYLITE_ERROR;
    }

    if (left_value < right_value) {
        *out_comparison = -1;
    } else if (left_value > right_value) {
        *out_comparison = 1;
    } else {
        *out_comparison = 0;
    }
    return MYLITE_OK;
}

static int show_table_status_where_texts_are_equal(
    struct mylite_db *database,
    const char *left,
    const char *right,
    size_t column_index,
    bool *out_equal
) {
    int comparison = 0;
    int rc = MYLITE_OK;

    if (out_equal == NULL) {
        return MYLITE_MISUSE;
    }
    *out_equal = false;
    rc = show_table_status_where_compare_text(database, left, right, column_index, &comparison);
    if (rc == MYLITE_OK) {
        *out_equal = comparison == 0;
    }
    return rc;
}

static int show_table_status_where_truth_from_comparison(
    struct mylite_db *database,
    enum mylite_sql_ast_operator operator_kind,
    struct show_table_status_where_comparison comparison,
    enum show_variables_where_truth *out_truth
) {
    switch (operator_kind) {
    case MYLITE_SQL_AST_OPERATOR_EQUAL:
    case MYLITE_SQL_AST_OPERATOR_NULL_SAFE_EQUAL:
        *out_truth = comparison.value == 0 ? SHOW_VARIABLES_WHERE_TRUE : SHOW_VARIABLES_WHERE_FALSE;
        return MYLITE_OK;
    case MYLITE_SQL_AST_OPERATOR_NOT_EQUAL:
        *out_truth = comparison.value != 0 ? SHOW_VARIABLES_WHERE_TRUE : SHOW_VARIABLES_WHERE_FALSE;
        return MYLITE_OK;
    case MYLITE_SQL_AST_OPERATOR_LESS:
        *out_truth = comparison.value < 0 ? SHOW_VARIABLES_WHERE_TRUE : SHOW_VARIABLES_WHERE_FALSE;
        return MYLITE_OK;
    case MYLITE_SQL_AST_OPERATOR_LESS_EQUAL:
        *out_truth = comparison.value <= 0 ? SHOW_VARIABLES_WHERE_TRUE : SHOW_VARIABLES_WHERE_FALSE;
        return MYLITE_OK;
    case MYLITE_SQL_AST_OPERATOR_GREATER:
        *out_truth = comparison.value > 0 ? SHOW_VARIABLES_WHERE_TRUE : SHOW_VARIABLES_WHERE_FALSE;
        return MYLITE_OK;
    case MYLITE_SQL_AST_OPERATOR_GREATER_EQUAL:
        *out_truth = comparison.value >= 0 ? SHOW_VARIABLES_WHERE_TRUE : SHOW_VARIABLES_WHERE_FALSE;
        return MYLITE_OK;
    default:
        set_unsupported_error(
            database,
            "SHOW TABLE STATUS WHERE comparison operator is not supported"
        );
        return MYLITE_ERROR;
    }
}

static bool compare_show_table_status_where_null_operand(
    enum mylite_sql_ast_operator operator_kind,
    const char *left,
    enum mylite_sql_ast_literal_kind literal_kind,
    enum show_variables_where_truth *out_truth
) {
    if (literal_kind == MYLITE_SQL_AST_LITERAL_NULL) {
        if (operator_kind == MYLITE_SQL_AST_OPERATOR_NULL_SAFE_EQUAL) {
            *out_truth = left == NULL ? SHOW_VARIABLES_WHERE_TRUE : SHOW_VARIABLES_WHERE_FALSE;
        } else {
            *out_truth = SHOW_VARIABLES_WHERE_UNKNOWN;
        }
        return true;
    }
    if (left == NULL) {
        *out_truth = operator_kind == MYLITE_SQL_AST_OPERATOR_NULL_SAFE_EQUAL
                         ? SHOW_VARIABLES_WHERE_FALSE
                         : SHOW_VARIABLES_WHERE_UNKNOWN;
        return true;
    }
    return false;
}

static int decode_show_table_status_where_string_literal(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *literal_node,
    char **out_text
) {
    size_t text_length = 0U;

    return decode_sql_string_literal(
        database,
        literal_node,
        "SHOW TABLE STATUS WHERE supports only string literal predicates",
        "SHOW TABLE STATUS WHERE string literals do not support NUL bytes",
        out_text,
        &text_length
    );
}

static int compare_show_table_status_where_text(
    const char *left,
    const char *right,
    size_t column_index
) {
    if (show_table_status_where_column_is_case_sensitive(column_index)) {
        return strcmp(left, right);
    }
    return compare_ascii_case_insensitive_text(left, right);
}

static bool parse_show_table_status_where_unsigned_text(const char *text, uint64_t *out_value) {
    uint64_t value = 0U;

    if (text == NULL || text[0] == '\0' || out_value == NULL) {
        return false;
    }
    for (size_t index = 0U; text[index] != '\0'; ++index) {
        uint64_t digit = 0U;

        if (text[index] < '0' || text[index] > '9') {
            return false;
        }
        digit = (uint64_t)(text[index] - '0');
        if (value > (UINT64_MAX - digit) / decimal_base) {
            return false;
        }
        value = (value * decimal_base) + digit;
    }

    *out_value = value;
    return true;
}

static bool show_table_status_where_column_is_case_sensitive(size_t column_index) {
    return column_index == show_table_status_name_column;
}

static bool show_table_status_where_column_is_numeric(size_t column_index) {
    return (column_index == show_table_status_version_column ||
            column_index == show_table_status_rows_column ||
            column_index == show_table_status_average_row_length_column ||
            column_index == show_table_status_data_length_column ||
            column_index == show_table_status_max_data_length_column ||
            column_index == show_table_status_index_length_column ||
            column_index == show_table_status_data_free_column ||
            column_index == show_table_status_auto_increment_column ||
            column_index == show_table_status_checksum_column) != 0;
}

static int append_show_column(
    const struct mylite_catalog_column_descriptor *column,
    void *user_data
) {
    struct show_columns_context *context = user_data;
    const char *type_text = NULL;
    char type_text_storage[MYLITE_CATALOG_TYPE_NAME_CAPACITY];
    char default_text[generated_default_display_text_capacity];
    const char *values[show_full_columns_result_column_count] = {0};
    int rc = MYLITE_OK;

    if (column == NULL || context == NULL || context->result == NULL) {
        return MYLITE_MISUSE;
    }

    if (!show_like_filter_matches(context->filter, column->name, false)) {
        return MYLITE_OK;
    }

    rc = show_column_type_text(
        context->database,
        column->logical_type,
        type_text_storage,
        sizeof(type_text_storage),
        &type_text
    );
    if (rc != MYLITE_OK) {
        return rc;
    }

    values[0] = column->name;
    values[1] = type_text;
    if (context->full) {
        bool where_matches = true;

        values[2] = show_column_collation_text(context->table, column);
        values[3] = "NO";
        if (column->is_nullable) {
            values[3] = "YES";
        }
        values[4] = column_key_text(
            (struct loaded_index_info_span){
                .indexes = context->indexes,
                .count = context->index_count,
            },
            context->primary_key,
            column
        );
        rc = column_default_display_text(
            context->database,
            column,
            default_text,
            sizeof(default_text),
            &values[show_full_columns_default_column]
        );
        if (rc != MYLITE_OK) {
            return rc;
        }
        values[show_full_columns_extra_column] = column_extra_text(column);
        values[show_full_columns_privileges_column] = "select,insert,update,references";
        values[show_full_columns_comment_column] = column->comment;

        if (context->where_clause != NULL) {
            rc = show_columns_where_clause_matches(
                context->database,
                context->where_clause,
                values,
                context->full,
                &where_matches
            );
        }
        if (rc == MYLITE_OK && !where_matches) {
            return MYLITE_OK;
        }
        return mylite_result_append_text_row(context->result, values);
    }

    values[2] = "NO";
    if (column->is_nullable) {
        values[2] = "YES";
    }
    values[3] = column_key_text(
        (struct loaded_index_info_span){
            .indexes = context->indexes,
            .count = context->index_count,
        },
        context->primary_key,
        column
    );
    rc = column_default_display_text(
        context->database,
        column,
        default_text,
        sizeof(default_text),
        &values[4]
    );
    if (rc != MYLITE_OK) {
        return rc;
    }
    values[show_columns_extra_column] = column_extra_text(column);

    if (context->where_clause != NULL) {
        bool where_matches = true;

        rc = show_columns_where_clause_matches(
            context->database,
            context->where_clause,
            values,
            context->full,
            &where_matches
        );
        if (rc == MYLITE_OK && !where_matches) {
            return MYLITE_OK;
        }
    }

    return mylite_result_append_text_row(context->result, values);
}

static int evaluate_show_columns_where_comparison_predicate(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *predicate,
    const char *const *values,
    bool full,
    enum show_variables_where_truth *out_truth
) {
    const struct mylite_sql_ast_node *left_node = child_at(predicate, 0U);
    const struct mylite_sql_ast_node *right_node = child_at(predicate, 1U);
    const char *left = NULL;
    enum mylite_sql_ast_operator operator_kind = mylite_sql_ast_node_operator(predicate);
    int rc = show_columns_where_column_value(database, left_node, values, full, &left);
    static const struct show_metadata_regexp_messages regexp_messages = {
        .literal = "SHOW COLUMNS WHERE REGEXP predicates support only string pattern literals",
        .nul = "SHOW COLUMNS WHERE REGEXP pattern literals do not support NUL bytes",
        .ascii = "SHOW COLUMNS WHERE REGEXP pattern literals support only ASCII text",
        .unsupported =
            "SHOW COLUMNS WHERE REGEXP patterns support only MyLite's baseline ASCII regular "
            "expression subset",
    };

    if (rc != MYLITE_OK) {
        return rc;
    }
    if (operator_kind == MYLITE_SQL_AST_OPERATOR_REGEXP ||
        operator_kind == MYLITE_SQL_AST_OPERATOR_RLIKE) {
        return evaluate_show_metadata_where_regexp_predicate(
            database,
            left,
            right_node,
            &regexp_messages,
            false,
            out_truth
        );
    }
    if (operator_kind == MYLITE_SQL_AST_OPERATOR_LIKE) {
        char *pattern = NULL;

        rc = decode_show_columns_where_string_literal(database, right_node, &pattern);
        if (rc == MYLITE_OK) {
            if (left == NULL) {
                *out_truth = SHOW_VARIABLES_WHERE_UNKNOWN;
            } else if (
                show_like_pattern_matches(pattern, strlen(pattern), left, strlen(left), false)
            ) {
                *out_truth = SHOW_VARIABLES_WHERE_TRUE;
            } else {
                *out_truth = SHOW_VARIABLES_WHERE_FALSE;
            }
        }
        free(pattern);
        return rc;
    }

    return compare_show_columns_where_literal(database, operator_kind, left, right_node, out_truth);
}

static int evaluate_show_columns_where_in_predicate(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *predicate,
    const char *const *values,
    bool full,
    enum show_variables_where_truth *out_truth
) {
    const struct mylite_sql_ast_node *left_node = child_at(predicate, 0U);
    const struct mylite_sql_ast_node *value_list = child_at(predicate, 1U);
    const char *left = NULL;
    size_t value_count = 0U;
    bool matched = false;
    bool saw_null = false;
    int rc = show_columns_where_column_value(database, left_node, values, full, &left);

    if (rc != MYLITE_OK) {
        return rc;
    }
    if (value_list == NULL || value_list->kind != MYLITE_SQL_AST_PREDICATE_VALUE_LIST) {
        set_runtime_error(database, "invalid SHOW COLUMNS WHERE IN list");
        return MYLITE_ERROR;
    }

    value_count = mylite_sql_ast_node_child_count(value_list);
    for (size_t index = 0U; index < value_count; ++index) {
        const struct mylite_sql_ast_node *value_node = child_at(value_list, index);
        enum mylite_sql_ast_literal_kind literal_kind = MYLITE_SQL_AST_LITERAL_NONE;
        char *right = NULL;

        if (value_node == NULL || value_node->kind != MYLITE_SQL_AST_LITERAL) {
            set_unsupported_error(
                database,
                "SHOW COLUMNS WHERE IN supports only string and NULL literals"
            );
            return MYLITE_ERROR;
        }

        literal_kind = mylite_sql_ast_node_literal_kind(value_node);
        if (literal_kind == MYLITE_SQL_AST_LITERAL_NULL) {
            saw_null = true;
            continue;
        }
        if (literal_kind != MYLITE_SQL_AST_LITERAL_STRING) {
            set_unsupported_error(
                database,
                "SHOW COLUMNS WHERE IN supports only string and NULL literals"
            );
            return MYLITE_ERROR;
        }
        rc = decode_show_columns_where_string_literal(database, value_node, &right);
        if (rc == MYLITE_OK && left != NULL &&
            compare_ascii_case_insensitive_text(left, right) == 0) {
            matched = true;
        }
        free(right);
        if (rc != MYLITE_OK) {
            return rc;
        }
    }

    if (matched) {
        *out_truth = SHOW_VARIABLES_WHERE_TRUE;
    } else if (left == NULL || saw_null) {
        *out_truth = SHOW_VARIABLES_WHERE_UNKNOWN;
    } else {
        *out_truth = SHOW_VARIABLES_WHERE_FALSE;
    }
    return MYLITE_OK;
}

static int evaluate_show_columns_where_is_null_predicate(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *predicate,
    const char *const *values,
    bool full,
    enum show_variables_where_truth *out_truth
) {
    const char *value = NULL;
    int rc =
        show_columns_where_column_value(database, child_at(predicate, 0U), values, full, &value);

    if (rc != MYLITE_OK) {
        return rc;
    }
    if (mylite_sql_ast_node_operator(predicate) == MYLITE_SQL_AST_OPERATOR_IS_NOT_NULL) {
        *out_truth = value == NULL ? SHOW_VARIABLES_WHERE_FALSE : SHOW_VARIABLES_WHERE_TRUE;
    } else {
        *out_truth = value == NULL ? SHOW_VARIABLES_WHERE_TRUE : SHOW_VARIABLES_WHERE_FALSE;
    }
    return MYLITE_OK;
}

static int show_columns_where_column_value(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *column_node,
    const char *const *values,
    bool full,
    const char **out_value
) {
    size_t column_index = 0U;
    int rc = resolve_show_columns_where_column(database, column_node, full, &column_index);

    if (rc != MYLITE_OK) {
        return rc;
    }
    if (values == NULL || out_value == NULL) {
        set_runtime_error(database, "invalid SHOW COLUMNS WHERE row");
        return MYLITE_ERROR;
    }

    *out_value = values[column_index];
    return MYLITE_OK;
}

static int resolve_show_columns_where_column(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *column_node,
    bool full,
    size_t *out_column_index
) {
    char parts[table_name_part_capacity][MYLITE_CATALOG_IDENTIFIER_CAPACITY];
    char *display_text = NULL;
    const char *const *columns = show_columns_result_columns;
    size_t column_count = show_columns_result_column_count;
    size_t part_count = 0U;
    int rc = MYLITE_OK;

    if (out_column_index == NULL) {
        return MYLITE_MISUSE;
    }
    *out_column_index = 0U;
    if (column_node == NULL || (column_node->kind != MYLITE_SQL_AST_IDENTIFIER &&
                                column_node->kind != MYLITE_SQL_AST_QUALIFIED_IDENTIFIER)) {
        set_unsupported_error(database, "SHOW COLUMNS WHERE supports only output columns");
        return MYLITE_ERROR;
    }

    if (full) {
        columns = show_full_columns_result_columns;
        column_count = show_full_columns_result_column_count;
    }

    rc = collect_identifier_parts(
        column_node,
        parts,
        table_name_part_capacity,
        &part_count,
        database
    );
    if (rc != MYLITE_OK) {
        return rc;
    }
    if (part_count == 1U) {
        for (size_t column_index = 0U; column_index < column_count; ++column_index) {
            if (text_equals_ascii_case_insensitive(parts[0], columns[column_index])) {
                *out_column_index = column_index;
                return MYLITE_OK;
            }
        }
    }

    rc = show_variables_column_reference_text(database, column_node, &display_text);
    if (rc == MYLITE_OK) {
        set_unknown_where_column_error(database, display_text);
        rc = MYLITE_ERROR;
    }
    free(display_text);
    return rc;
}

static int compare_show_columns_where_literal(
    struct mylite_db *database,
    enum mylite_sql_ast_operator operator_kind,
    const char *left,
    const struct mylite_sql_ast_node *right,
    enum show_variables_where_truth *out_truth
) {
    enum mylite_sql_ast_literal_kind literal_kind = MYLITE_SQL_AST_LITERAL_NONE;
    char *right_text = NULL;
    int comparison = 0;
    int rc = MYLITE_OK;

    if (right == NULL || out_truth == NULL) {
        set_runtime_error(database, "invalid SHOW COLUMNS WHERE comparison");
        return MYLITE_ERROR;
    }
    if (right->kind != MYLITE_SQL_AST_LITERAL) {
        set_unsupported_error(
            database,
            "SHOW COLUMNS WHERE comparisons support only string and NULL literals"
        );
        return MYLITE_ERROR;
    }

    literal_kind = mylite_sql_ast_node_literal_kind(right);
    if (literal_kind == MYLITE_SQL_AST_LITERAL_NULL &&
        compare_show_index_where_null_operand(operator_kind, left, literal_kind, out_truth)) {
        return MYLITE_OK;
    }

    rc = decode_show_columns_where_string_literal(database, right, &right_text);
    if (rc != MYLITE_OK) {
        free(right_text);
        return rc;
    }
    if (left == NULL &&
        compare_show_index_where_null_operand(operator_kind, left, literal_kind, out_truth)) {
        free(right_text);
        return MYLITE_OK;
    }

    comparison = compare_ascii_case_insensitive_text(left, right_text);
    rc = show_index_where_truth_from_comparison(
        database,
        operator_kind,
        (struct show_table_status_where_comparison){.value = comparison},
        out_truth
    );

    free(right_text);
    return rc;
}

static int decode_show_columns_where_string_literal(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *literal_node,
    char **out_text
) {
    size_t text_length = 0U;

    return decode_sql_string_literal(
        database,
        literal_node,
        "SHOW COLUMNS WHERE supports only string literal predicates",
        "SHOW COLUMNS WHERE string literals do not support NUL bytes",
        out_text,
        &text_length
    );
}

static int append_show_index(
    struct mylite_db *database,
    mylite_result *result,
    const struct table_name_resolution *target,
    const struct loaded_index_info *index,
    const struct mylite_sql_ast_node *where_clause
) {
    static const char cardinality[] = "0";
    static const char non_unique[] = "1";
    static const char unique[] = "0";
    char sequence[integer_text_capacity];
    const char *non_unique_text = non_unique;
    int rc = MYLITE_OK;

    if (database == NULL || result == NULL || target == NULL || index == NULL) {
        return MYLITE_MISUSE;
    }
    if (index->index.is_unique) {
        non_unique_text = unique;
    }

    for (size_t part_index = 0U; rc == MYLITE_OK && part_index < index->part_count; ++part_index) {
        const struct loaded_index_part *part = &index->parts[part_index];
        char prefix_text[integer_text_capacity];
        const char *nullable = show_index_part_nullable_text(part);
        const char *collation = show_index_part_collation_text(index, part);
        const char *prefix_value = NULL;
        const char *index_type = show_index_index_type_text(index);
        bool where_matches = true;

        rc = show_index_part_prefix_value(
            database,
            index,
            part,
            prefix_text,
            sizeof(prefix_text),
            &prefix_value
        );
        if (rc == MYLITE_OK) {
            rc = information_schema_format_i64(
                database,
                part->index_column.ordinal_position,
                sequence,
                sizeof(sequence)
            );
        }
        if (rc == MYLITE_OK) {
            const char *values[show_index_result_column_count] = {
                target->table_name,
                non_unique_text,
                index->index.name,
                sequence,
                part->column.name,
                collation,
                cardinality,
                prefix_value,
                NULL,
                nullable,
                index_type,
                "",
                index->index.comment,
                index_visibility_text(index->index.is_visible),
                NULL,
            };

            if (where_clause != NULL) {
                rc =
                    show_index_where_clause_matches(database, where_clause, values, &where_matches);
            }
            if (rc == MYLITE_OK && where_matches) {
                rc = mylite_result_append_text_row(result, values);
            }
        }
    }

    return rc;
}

static const char *show_index_part_nullable_text(const struct loaded_index_part *part) {
    if (part->column.is_nullable) {
        return "YES";
    }

    return "";
}

static const char *show_index_part_collation_text(
    const struct loaded_index_info *index,
    const struct loaded_index_part *part
) {
    if (index->index.kind == MYLITE_CATALOG_INDEX_KIND_FULLTEXT) {
        return NULL;
    }
    if (index->index.kind == MYLITE_CATALOG_INDEX_KIND_SPATIAL) {
        return "A";
    }
    if (part->index_column.sort_direction == MYLITE_CATALOG_INDEX_SORT_DIRECTION_DESC) {
        return "D";
    }

    return "A";
}

static int show_index_part_prefix_value(
    struct mylite_db *database,
    const struct loaded_index_info *index,
    const struct loaded_index_part *part,
    char *prefix_text,
    size_t prefix_text_size,
    const char **out_prefix_value
) {
    *out_prefix_value = NULL;
    if (index->index.kind == MYLITE_CATALOG_INDEX_KIND_SPATIAL) {
        *out_prefix_value = "32";
        return MYLITE_OK;
    }
    if (index->index.kind == MYLITE_CATALOG_INDEX_KIND_FULLTEXT ||
        !part->index_column.has_prefix_length) {
        return MYLITE_OK;
    }

    int rc = information_schema_format_i64(
        database,
        part->index_column.prefix_length,
        prefix_text,
        prefix_text_size
    );

    if (rc == MYLITE_OK) {
        *out_prefix_value = prefix_text;
    }
    return rc;
}

static const char *show_index_index_type_text(const struct loaded_index_info *index) {
    if (index->index.kind == MYLITE_CATALOG_INDEX_KIND_FULLTEXT) {
        return "FULLTEXT";
    }
    if (index->index.kind == MYLITE_CATALOG_INDEX_KIND_SPATIAL) {
        return "SPATIAL";
    }

    return "BTREE";
}

static int validate_show_index_where_clause(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *where_clause
) {
    static const char *const validation_values[show_index_result_column_count] = {
        "table_name",
        "1",
        "key_name",
        "1",
        "column_name",
        "A",
        "0",
        "3",
        NULL,
        "YES",
        "BTREE",
        "",
        "",
        "YES",
        NULL,
    };
    bool matches = false;

    if (where_clause == NULL) {
        return MYLITE_OK;
    }
    return show_index_where_clause_matches(database, where_clause, validation_values, &matches);
}

static int show_index_where_clause_matches(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *where_clause,
    const char *const values[show_index_result_column_count],
    bool *out_matches
) {
    enum show_variables_where_truth truth = SHOW_VARIABLES_WHERE_FALSE;
    int rc = MYLITE_OK;

    if (where_clause == NULL || where_clause->kind != MYLITE_SQL_AST_WHERE_CLAUSE ||
        values == NULL || out_matches == NULL) {
        set_runtime_error(database, "invalid SHOW INDEX WHERE predicate");
        return MYLITE_ERROR;
    }

    *out_matches = false;
    rc = evaluate_show_index_where_predicate(database, child_at(where_clause, 0U), values, &truth);
    if (rc == MYLITE_OK) {
        *out_matches = truth == SHOW_VARIABLES_WHERE_TRUE;
    }
    return rc;
}

static int evaluate_show_index_where_predicate(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *predicate,
    const char *const values[show_index_result_column_count],
    enum show_variables_where_truth *out_truth
) {
    struct show_variables_where_frame_stack frame_stack = {0};
    struct show_variables_where_truth_stack truth_stack = {0};
    struct show_variables_where_eval_frame frame = {
        .node = predicate,
        .action = SHOW_VARIABLES_WHERE_VISIT,
    };
    int rc = MYLITE_OK;

    if (predicate == NULL || values == NULL || out_truth == NULL) {
        set_runtime_error(database, "invalid SHOW INDEX WHERE predicate");
        return MYLITE_ERROR;
    }

    rc = show_variables_where_frame_stack_push(database, &frame_stack, frame);
    while (rc == MYLITE_OK && show_variables_where_frame_stack_pop(&frame_stack, &frame)) {
        const struct mylite_sql_ast_node *current = unwrap_parenthesized_predicate(frame.node);

        if (current == NULL) {
            set_runtime_error(database, "invalid SHOW INDEX WHERE predicate");
            rc = MYLITE_ERROR;
        } else if (frame.action == SHOW_VARIABLES_WHERE_VISIT) {
            rc = visit_show_index_where_predicate(database, &frame_stack, current);
        } else {
            rc = evaluate_show_index_where_frame(database, current, values, &truth_stack);
        }
    }

    if (rc == MYLITE_OK) {
        if (truth_stack.count != 1U ||
            !show_variables_where_truth_stack_pop(&truth_stack, out_truth)) {
            set_runtime_error(database, "invalid SHOW INDEX WHERE predicate state");
            rc = MYLITE_ERROR;
        }
    }

    show_variables_where_truth_stack_deinit(&truth_stack);
    show_variables_where_frame_stack_deinit(&frame_stack);
    return rc;
}

static int visit_show_index_where_predicate(
    struct mylite_db *database,
    struct show_variables_where_frame_stack *frame_stack,
    const struct mylite_sql_ast_node *predicate
) {
    int rc = show_variables_where_frame_stack_push(
        database,
        frame_stack,
        (struct show_variables_where_eval_frame){
            .node = predicate,
            .action = SHOW_VARIABLES_WHERE_EVALUATE,
        }
    );

    if (rc != MYLITE_OK) {
        return rc;
    }
    if (predicate->kind == MYLITE_SQL_AST_NOT_PREDICATE) {
        return show_variables_where_frame_stack_push(
            database,
            frame_stack,
            (struct show_variables_where_eval_frame){
                .node = child_at(predicate, 0U),
                .action = SHOW_VARIABLES_WHERE_VISIT,
            }
        );
    }
    if (predicate->kind == MYLITE_SQL_AST_AND_PREDICATE ||
        predicate->kind == MYLITE_SQL_AST_OR_PREDICATE) {
        rc = show_variables_where_frame_stack_push(
            database,
            frame_stack,
            (struct show_variables_where_eval_frame){
                .node = child_at(predicate, 1U),
                .action = SHOW_VARIABLES_WHERE_VISIT,
            }
        );
        if (rc == MYLITE_OK) {
            rc = show_variables_where_frame_stack_push(
                database,
                frame_stack,
                (struct show_variables_where_eval_frame){
                    .node = child_at(predicate, 0U),
                    .action = SHOW_VARIABLES_WHERE_VISIT,
                }
            );
        }
    }
    return rc;
}

static int evaluate_show_index_where_frame(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *predicate,
    const char *const values[show_index_result_column_count],
    struct show_variables_where_truth_stack *truth_stack
) {
    enum show_variables_where_truth truth = SHOW_VARIABLES_WHERE_FALSE;
    int rc = MYLITE_OK;

    if (predicate->kind == MYLITE_SQL_AST_COMPARISON_PREDICATE) {
        rc = evaluate_show_index_where_comparison_predicate(database, predicate, values, &truth);
    } else if (predicate->kind == MYLITE_SQL_AST_IN_PREDICATE) {
        rc = evaluate_show_index_where_in_predicate(database, predicate, values, &truth);
    } else if (predicate->kind == MYLITE_SQL_AST_IS_NULL_PREDICATE) {
        rc = evaluate_show_index_where_is_null_predicate(database, predicate, values, &truth);
    } else if (predicate->kind == MYLITE_SQL_AST_NOT_PREDICATE) {
        enum show_variables_where_truth child_truth = SHOW_VARIABLES_WHERE_FALSE;

        if (!show_variables_where_truth_stack_pop(truth_stack, &child_truth)) {
            set_runtime_error(database, "invalid SHOW INDEX WHERE predicate stack");
            return MYLITE_ERROR;
        }
        truth = negate_show_variables_where_truth(child_truth);
    } else if (
        predicate->kind == MYLITE_SQL_AST_AND_PREDICATE ||
        predicate->kind == MYLITE_SQL_AST_OR_PREDICATE
    ) {
        rc = evaluate_show_variables_where_logical_frame(database, predicate, truth_stack, &truth);
    } else if (predicate->kind == MYLITE_SQL_AST_XOR_PREDICATE) {
        set_unsupported_error(database, "SHOW INDEX WHERE does not support XOR predicates");
        return MYLITE_ERROR;
    } else {
        set_unsupported_error(database, "SHOW INDEX WHERE supports output-column predicates");
        return MYLITE_ERROR;
    }
    if (rc == MYLITE_OK) {
        rc = show_variables_where_truth_stack_push(database, truth_stack, truth);
    }
    return rc;
}

static int evaluate_show_index_where_comparison_predicate(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *predicate,
    const char *const values[show_index_result_column_count],
    enum show_variables_where_truth *out_truth
) {
    const struct mylite_sql_ast_node *left_node = child_at(predicate, 0U);
    const struct mylite_sql_ast_node *right_node = child_at(predicate, 1U);
    const char *left = NULL;
    size_t column_index = 0U;
    enum mylite_sql_ast_operator operator_kind = mylite_sql_ast_node_operator(predicate);
    int rc = show_index_where_column_value(database, left_node, values, &left, &column_index);
    static const struct show_metadata_regexp_messages regexp_messages = {
        .literal = "SHOW INDEX WHERE REGEXP predicates support only string pattern literals",
        .nul = "SHOW INDEX WHERE REGEXP pattern literals do not support NUL bytes",
        .ascii = "SHOW INDEX WHERE REGEXP pattern literals support only ASCII text",
        .unsupported =
            "SHOW INDEX WHERE REGEXP patterns support only MyLite's baseline ASCII regular "
            "expression subset",
    };

    if (rc != MYLITE_OK) {
        return rc;
    }
    if (operator_kind == MYLITE_SQL_AST_OPERATOR_REGEXP ||
        operator_kind == MYLITE_SQL_AST_OPERATOR_RLIKE) {
        (void)column_index;
        return evaluate_show_metadata_where_regexp_predicate(
            database,
            left,
            right_node,
            &regexp_messages,
            false,
            out_truth
        );
    }
    if (operator_kind == MYLITE_SQL_AST_OPERATOR_LIKE) {
        char *pattern = NULL;

        rc = decode_show_index_where_string_literal(database, right_node, &pattern);
        if (rc == MYLITE_OK) {
            if (left == NULL) {
                *out_truth = SHOW_VARIABLES_WHERE_UNKNOWN;
            } else {
                bool matches =
                    show_like_pattern_matches(pattern, strlen(pattern), left, strlen(left), false);

                if (matches) {
                    *out_truth = SHOW_VARIABLES_WHERE_TRUE;
                } else {
                    *out_truth = SHOW_VARIABLES_WHERE_FALSE;
                }
            }
        }
        free(pattern);
        return rc;
    }

    return compare_show_index_where_literal(
        database,
        operator_kind,
        left,
        column_index,
        right_node,
        out_truth
    );
}

static int evaluate_show_index_where_in_predicate(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *predicate,
    const char *const values[show_index_result_column_count],
    enum show_variables_where_truth *out_truth
) {
    const struct mylite_sql_ast_node *left_node = child_at(predicate, 0U);
    const struct mylite_sql_ast_node *value_list = child_at(predicate, 1U);
    const char *left = NULL;
    size_t column_index = 0U;
    size_t value_count = 0U;
    bool saw_null = false;
    int rc = show_index_where_column_value(database, left_node, values, &left, &column_index);

    if (rc != MYLITE_OK) {
        return rc;
    }
    if (value_list == NULL || value_list->kind != MYLITE_SQL_AST_PREDICATE_VALUE_LIST) {
        set_runtime_error(database, "invalid SHOW INDEX WHERE IN list");
        return MYLITE_ERROR;
    }

    value_count = mylite_sql_ast_node_child_count(value_list);
    for (size_t index = 0U; index < value_count; ++index) {
        const struct mylite_sql_ast_node *value_node = child_at(value_list, index);
        enum mylite_sql_ast_literal_kind literal_kind = MYLITE_SQL_AST_LITERAL_NONE;
        char *right = NULL;

        if (value_node == NULL || value_node->kind != MYLITE_SQL_AST_LITERAL) {
            set_unsupported_error(
                database,
                "SHOW INDEX WHERE IN supports only string and NULL literals"
            );
            return MYLITE_ERROR;
        }

        literal_kind = mylite_sql_ast_node_literal_kind(value_node);
        if (literal_kind == MYLITE_SQL_AST_LITERAL_NULL) {
            saw_null = true;
            continue;
        }
        rc = decode_show_index_where_string_literal(database, value_node, &right);
        if (rc == MYLITE_OK) {
            bool equal = false;

            if (left != NULL) {
                rc = show_index_where_texts_are_equal(database, left, right, column_index, &equal);
            }
            if (rc == MYLITE_OK && equal) {
                *out_truth = SHOW_VARIABLES_WHERE_TRUE;
                free(right);
                return MYLITE_OK;
            }
        }
        free(right);
        if (rc != MYLITE_OK) {
            return rc;
        }
    }

    if (left == NULL || saw_null) {
        *out_truth = SHOW_VARIABLES_WHERE_UNKNOWN;
    } else {
        *out_truth = SHOW_VARIABLES_WHERE_FALSE;
    }
    return MYLITE_OK;
}

static int evaluate_show_index_where_is_null_predicate(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *predicate,
    const char *const values[show_index_result_column_count],
    enum show_variables_where_truth *out_truth
) {
    const char *value = NULL;
    size_t column_index = 0U;
    int rc = show_index_where_column_value(
        database,
        child_at(predicate, 0U),
        values,
        &value,
        &column_index
    );

    (void)column_index;
    if (rc != MYLITE_OK) {
        return rc;
    }
    if (mylite_sql_ast_node_operator(predicate) == MYLITE_SQL_AST_OPERATOR_IS_NOT_NULL) {
        *out_truth = value == NULL ? SHOW_VARIABLES_WHERE_FALSE : SHOW_VARIABLES_WHERE_TRUE;
    } else {
        *out_truth = value == NULL ? SHOW_VARIABLES_WHERE_TRUE : SHOW_VARIABLES_WHERE_FALSE;
    }
    return MYLITE_OK;
}

static int show_index_where_column_value(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *column_node,
    const char *const values[show_index_result_column_count],
    const char **out_value,
    size_t *out_column_index
) {
    size_t column_index = 0U;
    int rc = resolve_show_index_where_column(database, column_node, &column_index);

    if (rc != MYLITE_OK) {
        return rc;
    }
    if (values == NULL || out_value == NULL || out_column_index == NULL) {
        set_runtime_error(database, "invalid SHOW INDEX WHERE row");
        return MYLITE_ERROR;
    }

    *out_value = values[column_index];
    *out_column_index = column_index;
    return MYLITE_OK;
}

static int resolve_show_index_where_column(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *column_node,
    size_t *out_column_index
) {
    char parts[table_name_part_capacity][MYLITE_CATALOG_IDENTIFIER_CAPACITY];
    char *display_text = NULL;
    size_t part_count = 0U;
    int rc = MYLITE_OK;

    if (out_column_index == NULL) {
        return MYLITE_MISUSE;
    }
    *out_column_index = 0U;
    if (column_node == NULL || (column_node->kind != MYLITE_SQL_AST_IDENTIFIER &&
                                column_node->kind != MYLITE_SQL_AST_QUALIFIED_IDENTIFIER)) {
        set_unsupported_error(database, "SHOW INDEX WHERE supports only output columns");
        return MYLITE_ERROR;
    }

    rc = collect_identifier_parts(
        column_node,
        parts,
        table_name_part_capacity,
        &part_count,
        database
    );
    if (rc != MYLITE_OK) {
        return rc;
    }
    if (part_count == 1U) {
        for (size_t column_index = 0U; column_index < show_index_result_column_count;
             ++column_index) {
            if (text_equals_ascii_case_insensitive(
                    parts[0],
                    show_index_result_columns[column_index]
                )) {
                *out_column_index = column_index;
                return MYLITE_OK;
            }
        }
    }

    rc = show_variables_column_reference_text(database, column_node, &display_text);
    if (rc == MYLITE_OK) {
        set_unknown_where_column_error(database, display_text);
        rc = MYLITE_ERROR;
    }
    free(display_text);
    return rc;
}

static int compare_show_index_where_literal(
    struct mylite_db *database,
    enum mylite_sql_ast_operator operator_kind,
    const char *left,
    size_t column_index,
    const struct mylite_sql_ast_node *right,
    enum show_variables_where_truth *out_truth
) {
    enum mylite_sql_ast_literal_kind literal_kind = MYLITE_SQL_AST_LITERAL_NONE;
    char *right_text = NULL;
    int comparison = 0;
    int rc = MYLITE_OK;

    if (right == NULL || out_truth == NULL) {
        set_runtime_error(database, "invalid SHOW INDEX WHERE comparison");
        return MYLITE_ERROR;
    }
    if (right->kind != MYLITE_SQL_AST_LITERAL) {
        set_unsupported_error(
            database,
            "SHOW INDEX WHERE comparisons support only string and NULL literals"
        );
        return MYLITE_ERROR;
    }

    literal_kind = mylite_sql_ast_node_literal_kind(right);
    if (literal_kind == MYLITE_SQL_AST_LITERAL_NULL &&
        compare_show_index_where_null_operand(operator_kind, left, literal_kind, out_truth)) {
        return MYLITE_OK;
    }

    rc = decode_show_index_where_string_literal(database, right, &right_text);
    if (rc != MYLITE_OK) {
        free(right_text);
        return rc;
    }
    if (left == NULL &&
        compare_show_index_where_null_operand(operator_kind, left, literal_kind, out_truth)) {
        free(right_text);
        return MYLITE_OK;
    }

    rc = show_index_where_compare_text(database, left, right_text, column_index, &comparison);
    if (rc == MYLITE_OK) {
        rc = show_index_where_truth_from_comparison(
            database,
            operator_kind,
            (struct show_table_status_where_comparison){.value = comparison},
            out_truth
        );
    }

    free(right_text);
    return rc;
}

static int show_index_where_compare_text(
    struct mylite_db *database,
    const char *left,
    const char *right,
    size_t column_index,
    int *out_comparison
) {
    if (out_comparison == NULL) {
        return MYLITE_MISUSE;
    }
    *out_comparison = 0;
    if (show_index_where_column_is_numeric(column_index)) {
        return show_index_where_compare_numeric_text(database, left, right, out_comparison);
    }

    *out_comparison = compare_show_index_where_text(left, right);
    return MYLITE_OK;
}

static int show_index_where_compare_numeric_text(
    struct mylite_db *database,
    const char *left,
    const char *right,
    int *out_comparison
) {
    uint64_t left_value = 0U;
    uint64_t right_value = 0U;

    if (!parse_show_table_status_where_unsigned_text(left, &left_value) ||
        !parse_show_table_status_where_unsigned_text(right, &right_value)) {
        set_unsupported_error(
            database,
            "SHOW INDEX WHERE numeric columns support only unsigned decimal string predicates"
        );
        return MYLITE_ERROR;
    }

    if (left_value < right_value) {
        *out_comparison = -1;
    } else if (left_value > right_value) {
        *out_comparison = 1;
    } else {
        *out_comparison = 0;
    }
    return MYLITE_OK;
}

static int show_index_where_texts_are_equal(
    struct mylite_db *database,
    const char *left,
    const char *right,
    size_t column_index,
    bool *out_equal
) {
    int comparison = 0;
    int rc = MYLITE_OK;

    if (out_equal == NULL) {
        return MYLITE_MISUSE;
    }
    *out_equal = false;
    rc = show_index_where_compare_text(database, left, right, column_index, &comparison);
    if (rc == MYLITE_OK) {
        *out_equal = comparison == 0;
    }
    return rc;
}

static int show_index_where_truth_from_comparison(
    struct mylite_db *database,
    enum mylite_sql_ast_operator operator_kind,
    struct show_table_status_where_comparison comparison,
    enum show_variables_where_truth *out_truth
) {
    switch (operator_kind) {
    case MYLITE_SQL_AST_OPERATOR_EQUAL:
    case MYLITE_SQL_AST_OPERATOR_NULL_SAFE_EQUAL:
        *out_truth = comparison.value == 0 ? SHOW_VARIABLES_WHERE_TRUE : SHOW_VARIABLES_WHERE_FALSE;
        return MYLITE_OK;
    case MYLITE_SQL_AST_OPERATOR_NOT_EQUAL:
        *out_truth = comparison.value != 0 ? SHOW_VARIABLES_WHERE_TRUE : SHOW_VARIABLES_WHERE_FALSE;
        return MYLITE_OK;
    case MYLITE_SQL_AST_OPERATOR_LESS:
        *out_truth = comparison.value < 0 ? SHOW_VARIABLES_WHERE_TRUE : SHOW_VARIABLES_WHERE_FALSE;
        return MYLITE_OK;
    case MYLITE_SQL_AST_OPERATOR_LESS_EQUAL:
        *out_truth = comparison.value <= 0 ? SHOW_VARIABLES_WHERE_TRUE : SHOW_VARIABLES_WHERE_FALSE;
        return MYLITE_OK;
    case MYLITE_SQL_AST_OPERATOR_GREATER:
        *out_truth = comparison.value > 0 ? SHOW_VARIABLES_WHERE_TRUE : SHOW_VARIABLES_WHERE_FALSE;
        return MYLITE_OK;
    case MYLITE_SQL_AST_OPERATOR_GREATER_EQUAL:
        *out_truth = comparison.value >= 0 ? SHOW_VARIABLES_WHERE_TRUE : SHOW_VARIABLES_WHERE_FALSE;
        return MYLITE_OK;
    default:
        set_unsupported_error(database, "SHOW INDEX WHERE comparison operator is not supported");
        return MYLITE_ERROR;
    }
}

static bool compare_show_index_where_null_operand(
    enum mylite_sql_ast_operator operator_kind,
    const char *left,
    enum mylite_sql_ast_literal_kind literal_kind,
    enum show_variables_where_truth *out_truth
) {
    if (literal_kind == MYLITE_SQL_AST_LITERAL_NULL) {
        if (operator_kind == MYLITE_SQL_AST_OPERATOR_NULL_SAFE_EQUAL) {
            *out_truth = left == NULL ? SHOW_VARIABLES_WHERE_TRUE : SHOW_VARIABLES_WHERE_FALSE;
        } else {
            *out_truth = SHOW_VARIABLES_WHERE_UNKNOWN;
        }
        return true;
    }
    if (left == NULL) {
        *out_truth = operator_kind == MYLITE_SQL_AST_OPERATOR_NULL_SAFE_EQUAL
                         ? SHOW_VARIABLES_WHERE_FALSE
                         : SHOW_VARIABLES_WHERE_UNKNOWN;
        return true;
    }
    return false;
}

static int decode_show_index_where_string_literal(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *literal_node,
    char **out_text
) {
    size_t text_length = 0U;

    return decode_sql_string_literal(
        database,
        literal_node,
        "SHOW INDEX WHERE supports only string literal predicates",
        "SHOW INDEX WHERE string literals do not support NUL bytes",
        out_text,
        &text_length
    );
}

static int evaluate_show_metadata_where_regexp_predicate(
    struct mylite_db *database,
    const char *left,
    const struct mylite_sql_ast_node *right,
    const struct show_metadata_regexp_messages *messages,
    bool case_sensitive,
    enum show_variables_where_truth *out_truth
) {
    struct mylite_regexp_program *program = NULL;
    char *pattern = NULL;
    size_t pattern_length = 0U;
    bool matches = false;
    int rc = MYLITE_OK;

    if (messages == NULL || out_truth == NULL) {
        return MYLITE_MISUSE;
    }
    if (right == NULL || right->kind != MYLITE_SQL_AST_LITERAL ||
        mylite_sql_ast_node_literal_kind(right) != MYLITE_SQL_AST_LITERAL_STRING) {
        set_unsupported_error(database, messages->literal);
        return MYLITE_ERROR;
    }

    rc = decode_sql_string_literal(
        database,
        right,
        messages->literal,
        messages->nul,
        &pattern,
        &pattern_length
    );
    if (rc != MYLITE_OK) {
        return rc;
    }
    if (!text_value_is_supported_string_key(pattern, pattern_length)) {
        free(pattern);
        set_unsupported_error(database, messages->ascii);
        return MYLITE_ERROR;
    }

    enum mylite_regexp_compile_status compile_status = MYLITE_REGEXP_COMPILE_OK;

    if (case_sensitive) {
        compile_status = mylite_regexp_compile_ascii_cs(pattern, pattern_length, &program);
    } else {
        compile_status = mylite_regexp_compile_ascii_ci(pattern, pattern_length, &program);
    }
    free(pattern);
    if (compile_status != MYLITE_REGEXP_COMPILE_OK) {
        mylite_regexp_program_free(program);
        if (compile_status == MYLITE_REGEXP_COMPILE_NOMEM) {
            set_nomem_error(database);
            return MYLITE_NOMEM;
        }
        if (compile_status == MYLITE_REGEXP_COMPILE_UNCLOSED_BRACKET) {
            set_regexp_error(
                database,
                "The regular expression contains an unclosed bracket expression."
            );
            return MYLITE_ERROR;
        }
        if (compile_status == MYLITE_REGEXP_COMPILE_INVALID_RANGE) {
            set_regexp_character_range_error(
                database,
                "The regular expression contains an invalid character range."
            );
            return MYLITE_ERROR;
        }
        set_unsupported_error(database, messages->unsupported);
        return MYLITE_ERROR;
    }

    if (left == NULL) {
        mylite_regexp_program_free(program);
        *out_truth = SHOW_VARIABLES_WHERE_UNKNOWN;
        return MYLITE_OK;
    }

    enum mylite_regexp_match_status match_status = MYLITE_REGEXP_MATCH_OK;

    if (case_sensitive) {
        match_status = mylite_regexp_program_match_ascii_cs(program, left, strlen(left), &matches);
    } else {
        match_status = mylite_regexp_program_match_ascii_ci(program, left, strlen(left), &matches);
    }
    mylite_regexp_program_free(program);
    if (match_status == MYLITE_REGEXP_MATCH_NOMEM) {
        set_nomem_error(database);
        return MYLITE_NOMEM;
    }
    if (match_status == MYLITE_REGEXP_MATCH_UNSUPPORTED_VALUE) {
        set_unsupported_error(
            database,
            "SHOW metadata WHERE REGEXP input supports only ASCII text"
        );
        return MYLITE_ERROR;
    }
    if (match_status != MYLITE_REGEXP_MATCH_OK) {
        set_unsupported_error(
            database,
            "SHOW metadata WHERE REGEXP input is too large for MyLite's baseline subset"
        );
        return MYLITE_ERROR;
    }

    if (matches) {
        *out_truth = SHOW_VARIABLES_WHERE_TRUE;
    } else {
        *out_truth = SHOW_VARIABLES_WHERE_FALSE;
    }
    return MYLITE_OK;
}

static int compare_show_index_where_text(const char *left, const char *right) {
    return compare_ascii_case_insensitive_text(left, right);
}

static bool show_index_where_column_is_numeric(size_t column_index) {
    return (column_index == show_index_non_unique_column ||
            column_index == show_index_seq_in_index_column ||
            column_index == show_index_cardinality_column ||
            column_index == show_index_sub_part_column) != 0;
}

static const char *index_visibility_text(bool is_visible) {
    if (!is_visible) {
        return "NO";
    }

    return "YES";
}

static int show_column_type_text(
    struct mylite_db *database,
    const char *logical_type,
    char *buffer,
    size_t buffer_size,
    const char **out_type_text
) {
    return show_descriptor_type_text(
        database,
        logical_type,
        buffer,
        buffer_size,
        "SHOW COLUMNS supports only integer, BIT, string, decimal, approximate numeric, DATE, "
        "TIME, DATETIME, and TIMESTAMP column descriptors",
        out_type_text
    );
}

static const char *show_column_collation_text(
    const struct mylite_catalog_table_descriptor *table,
    const struct mylite_catalog_column_descriptor *column
) {
    if (column_descriptor_is_string_family(column) || column_descriptor_is_enum(column) ||
        column_descriptor_is_set(column)) {
        return column_effective_collation_name(table, column);
    }

    return NULL;
}

static int append_show_database(
    const struct mylite_catalog_schema_descriptor *schema,
    void *user_data
) {
    struct show_databases_context *context = user_data;
    const char *values[1] = {NULL};

    if (schema == NULL || context == NULL || context->result == NULL) {
        return MYLITE_MISUSE;
    }

    if (!show_like_filter_matches(context->filter, schema->name, true)) {
        return MYLITE_OK;
    }

    values[0] = schema->name;

    return mylite_result_append_text_row(context->result, values);
}

static int make_show_like_filter(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *pattern_node,
    struct show_like_filter *out_filter
) {
    char *pattern = NULL;
    int rc = MYLITE_OK;

    if (out_filter == NULL) {
        set_runtime_error(database, "invalid SHOW LIKE filter");
        return MYLITE_ERROR;
    }
    *out_filter = (struct show_like_filter){
        .has_pattern = false,
        .pattern = NULL,
        .pattern_length = 0U,
    };
    if (pattern_node == NULL) {
        return MYLITE_OK;
    }

    rc = decode_show_like_pattern(database, pattern_node, &pattern);
    if (rc != MYLITE_OK) {
        return rc;
    }

    out_filter->has_pattern = true;
    out_filter->pattern = pattern;
    out_filter->pattern_length = strlen(pattern);
    return MYLITE_OK;
}

static void show_like_filter_deinit(struct show_like_filter *filter) {
    if (filter == NULL) {
        return;
    }

    free(filter->pattern);
    *filter = (struct show_like_filter){
        .has_pattern = false,
        .pattern = NULL,
        .pattern_length = 0U,
    };
}

static bool show_like_filter_matches(
    const struct show_like_filter *filter,
    const char *value,
    bool case_sensitive
) {
    if (filter == NULL || !filter->has_pattern) {
        return true;
    }
    if (value == NULL) {
        return false;
    }

    return show_like_pattern_matches(
        filter->pattern,
        filter->pattern_length,
        value,
        strlen(value),
        case_sensitive
    );
}

static int build_show_databases_column_name(
    const struct show_like_filter *filter,
    char **out_name
) {
    struct dynamic_string string;
    int rc = MYLITE_OK;

    if (out_name == NULL) {
        return MYLITE_MISUSE;
    }
    *out_name = NULL;

    dynamic_string_init(&string);
    rc = dynamic_string_append(&string, "Database");
    if (rc == MYLITE_OK && filter != NULL && filter->has_pattern) {
        rc = dynamic_string_append(&string, " (");
        if (rc == MYLITE_OK) {
            rc = dynamic_string_append(&string, filter->pattern);
        }
        if (rc == MYLITE_OK) {
            rc = dynamic_string_append_char(&string, ')');
        }
    }
    if (rc == MYLITE_OK) {
        *out_name = dynamic_string_take(&string);
        if (*out_name == NULL) {
            rc = MYLITE_NOMEM;
        }
    }
    dynamic_string_deinit(&string);
    return rc;
}

static int build_show_tables_column_name(
    const char *schema_name,
    const struct show_like_filter *filter,
    char **out_name
) {
    struct dynamic_string string;
    int rc = MYLITE_OK;

    if (schema_name == NULL || out_name == NULL) {
        return MYLITE_MISUSE;
    }
    *out_name = NULL;

    dynamic_string_init(&string);
    rc = dynamic_string_append(&string, "Tables_in_");
    if (rc == MYLITE_OK) {
        rc = dynamic_string_append(&string, schema_name);
    }
    if (rc == MYLITE_OK && filter != NULL && filter->has_pattern) {
        rc = dynamic_string_append(&string, " (");
        if (rc == MYLITE_OK) {
            rc = dynamic_string_append(&string, filter->pattern);
        }
        if (rc == MYLITE_OK) {
            rc = dynamic_string_append_char(&string, ')');
        }
    }
    if (rc == MYLITE_OK) {
        *out_name = dynamic_string_take(&string);
        if (*out_name == NULL) {
            rc = MYLITE_NOMEM;
        }
    }
    dynamic_string_deinit(&string);
    return rc;
}

static int read_show_table_status_row_count(
    struct mylite_db *database,
    const struct mylite_catalog_table_descriptor *table,
    int64_t *out_count
) {
    sqlite3_stmt *statement = NULL;
    char *sql = NULL;
    int rc = build_show_table_status_count_sql(table, &sql);

    if (rc == MYLITE_OK) {
        rc = prepare_sqlite_statement(database, sql, &statement);
    }
    if (rc == MYLITE_OK) {
        rc = step_count_statement(statement, out_count);
    }

    rc = finalize_sqlite_statement(statement, rc);
    free(sql);

    return rc;
}

static int build_show_table_status_count_sql(
    const struct mylite_catalog_table_descriptor *table,
    char **out_sql
) {
    struct dynamic_string string;
    int rc = MYLITE_OK;

    if (table == NULL || out_sql == NULL) {
        return MYLITE_MISUSE;
    }
    *out_sql = NULL;
    dynamic_string_init(&string);

    rc = dynamic_string_append(&string, "SELECT COUNT(*) FROM ");
    if (rc == MYLITE_OK) {
        rc = dynamic_string_append_quoted_identifier(&string, table->physical_name);
    }
    if (rc == MYLITE_OK) {
        *out_sql = dynamic_string_take(&string);
        if (*out_sql == NULL) {
            rc = MYLITE_NOMEM;
        }
    }

    dynamic_string_deinit(&string);

    return rc;
}

static int format_show_table_status_integer(
    struct mylite_db *database,
    int64_t value,
    char *buffer,
    size_t buffer_size
) {
    int written = snprintf(buffer, buffer_size, "%" PRId64, value);

    if (written < 0 || (size_t)written >= buffer_size) {
        set_runtime_error(database, "failed to format SHOW TABLE STATUS value");
        return MYLITE_ERROR;
    }

    return MYLITE_OK;
}

static int decode_show_like_pattern(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *pattern_node,
    char **out_pattern
) {
    struct dynamic_string string;
    const char *text = NULL;
    size_t length = 0U;
    char quote = '\0';
    int rc = MYLITE_OK;

    if (out_pattern == NULL) {
        set_runtime_error(database, "invalid SHOW LIKE pattern");
        return MYLITE_ERROR;
    }
    *out_pattern = NULL;
    if (pattern_node == NULL || pattern_node->kind != MYLITE_SQL_AST_LITERAL ||
        mylite_sql_ast_node_literal_kind(pattern_node) != MYLITE_SQL_AST_LITERAL_STRING) {
        set_unsupported_error(database, "SHOW LIKE supports only string literal patterns");
        return MYLITE_ERROR;
    }

    text = pattern_node->span.text;
    length = pattern_node->span.length;
    if (text == NULL || length < 2U) {
        set_runtime_error(database, "invalid SHOW LIKE pattern");
        return MYLITE_ERROR;
    }

    quote = text[0];
    dynamic_string_init(&string);
    for (size_t index = 1U; rc == MYLITE_OK && index + 1U < length; ++index) {
        char byte = text[index];

        if (byte == quote && index + 2U < length && text[index + 1U] == quote) {
            rc = dynamic_string_append_char(&string, quote);
            ++index;
        } else if (byte == '\\' && index + 2U < length) {
            ++index;
            rc = append_decoded_string_escape(database, &string, text[index]);
        } else {
            rc = dynamic_string_append_char(&string, byte);
        }
    }
    if (rc == MYLITE_OK && string.text == NULL) {
        rc = dynamic_string_append(&string, "");
    }
    if (rc == MYLITE_OK) {
        *out_pattern = dynamic_string_take(&string);
        if (*out_pattern == NULL) {
            rc = MYLITE_NOMEM;
        }
    }
    if (rc == MYLITE_NOMEM) {
        set_nomem_error(database);
    }
    dynamic_string_deinit(&string);
    return rc;
}

static int append_decoded_string_escape(
    struct mylite_db *database,
    struct dynamic_string *string,
    char escaped_byte
) {
    switch (escaped_byte) {
    case '0':
        set_unsupported_error(database, "SHOW LIKE does not support NUL bytes in patterns");
        return MYLITE_ERROR;
    case 'n':
        return dynamic_string_append_char(string, '\n');
    case 'r':
        return dynamic_string_append_char(string, '\r');
    case 't':
        return dynamic_string_append_char(string, '\t');
    case 'b':
        return dynamic_string_append_char(string, '\b');
    case 'Z':
        return dynamic_string_append_char(string, '\032');
    case '\\':
        return dynamic_string_append_char(string, '\\');
    case '\'':
        return dynamic_string_append_char(string, '\'');
    case '"':
        return dynamic_string_append_char(string, '"');
    case '%':
        if (dynamic_string_append_char(string, '\\') != MYLITE_OK) {
            return MYLITE_NOMEM;
        }
        return dynamic_string_append_char(string, '%');
    case '_':
        if (dynamic_string_append_char(string, '\\') != MYLITE_OK) {
            return MYLITE_NOMEM;
        }
        return dynamic_string_append_char(string, '_');
    default:
        return dynamic_string_append_char(string, escaped_byte);
    }
}

static bool show_like_pattern_matches(
    const char *pattern,
    size_t pattern_length,
    const char *value,
    size_t value_length,
    bool case_sensitive
) {
    const size_t no_retry_pattern = SIZE_MAX;
    size_t pattern_index = 0U;
    size_t value_index = 0U;
    size_t retry_pattern_index = no_retry_pattern;
    size_t retry_value_index = 0U;

    while (value_index < value_length) {
        size_t next_pattern_index = pattern_index;

        if (pattern_index < pattern_length && pattern[pattern_index] == '%') {
            pattern_index = show_like_skip_percent_run(pattern, pattern_length, pattern_index);
            if (pattern_index == pattern_length) {
                return true;
            }
            retry_pattern_index = pattern_index;
            retry_value_index = value_index;
            continue;
        }
        if (show_like_pattern_item_matches(
                (struct show_like_pattern_item_request){
                    .pattern = pattern,
                    .pattern_length = pattern_length,
                    .pattern_index = pattern_index,
                    .value_byte = value[value_index],
                    .case_sensitive = case_sensitive,
                },
                &next_pattern_index
            )) {
            pattern_index = next_pattern_index;
            ++value_index;
            continue;
        }
        if (retry_pattern_index == no_retry_pattern || retry_value_index >= value_length) {
            return false;
        }
        ++retry_value_index;
        value_index = retry_value_index;
        pattern_index = retry_pattern_index;
    }

    pattern_index = show_like_skip_percent_run(pattern, pattern_length, pattern_index);

    return pattern_index == pattern_length;
}

static size_t show_like_skip_percent_run(
    const char *pattern,
    size_t pattern_length,
    size_t pattern_index
) {
    while (pattern_index < pattern_length && pattern[pattern_index] == '%') {
        ++pattern_index;
    }
    return pattern_index;
}

static bool show_like_pattern_item_matches(
    struct show_like_pattern_item_request request,
    size_t *out_next_pattern_index
) {
    char pattern_byte = '\0';
    size_t next_pattern_index = request.pattern_index;

    if (request.pattern_index >= request.pattern_length || out_next_pattern_index == NULL) {
        return false;
    }

    pattern_byte = request.pattern[request.pattern_index];
    if (pattern_byte == '_') {
        *out_next_pattern_index = request.pattern_index + 1U;
        return true;
    }
    if (pattern_byte == '\\' && request.pattern_index + 1U < request.pattern_length) {
        ++next_pattern_index;
        pattern_byte = request.pattern[next_pattern_index];
    }
    ++next_pattern_index;
    if (!show_like_bytes_equal(pattern_byte, request.value_byte, request.case_sensitive)) {
        return false;
    }

    *out_next_pattern_index = next_pattern_index;
    return true;
}

static bool show_like_bytes_equal(char left, char right, bool case_sensitive) {
    if (case_sensitive) {
        return left == right;
    }

    return show_like_ascii_lower(left) == show_like_ascii_lower(right);
}

static char show_like_ascii_lower(char byte) {
    if (byte >= 'A' && byte <= 'Z') {
        return (char)(byte - 'A' + 'a');
    }
    return byte;
}

static int build_physical_table_name(int64_t table_id, char *destination, size_t destination_size) {
    int written = snprintf(destination, destination_size, "_mylite_user_table_%" PRId64, table_id);

    if (written < 0 || (size_t)written >= destination_size) {
        return MYLITE_ERROR;
    }

    return MYLITE_OK;
}

static int build_physical_index_name(int64_t index_id, char *destination, size_t destination_size) {
    int written = snprintf(destination, destination_size, "_mylite_user_index_%" PRId64, index_id);

    if (written < 0 || (size_t)written >= destination_size) {
        return MYLITE_ERROR;
    }

    return MYLITE_OK;
}

static int build_physical_check_constraint_name(
    int64_t check_constraint_id,
    char *destination,
    size_t destination_size
) {
    int written =
        snprintf(destination, destination_size, "_mylite_user_check_%" PRId64, check_constraint_id);

    if (written < 0 || (size_t)written >= destination_size) {
        return MYLITE_ERROR;
    }

    return MYLITE_OK;
}

static int build_create_table_sql(
    const struct planned_create_table *plan,
    const char *physical_name,
    bool temporary,
    char **out_sql
) {
    struct dynamic_string string;
    int rc = MYLITE_OK;

    *out_sql = NULL;
    dynamic_string_init(&string);

    rc = append_create_table_definition_sql(&string, plan, physical_name, temporary);
    if (rc == MYLITE_OK && plan->has_primary_key) {
        rc = append_create_table_primary_key_sql(&string, plan, physical_name);
    }
    if (rc == MYLITE_OK) {
        rc = append_create_table_secondary_indexes_sql(&string, plan, physical_name);
    }
    if (rc == MYLITE_OK) {
        *out_sql = dynamic_string_take(&string);
        if (*out_sql == NULL) {
            rc = MYLITE_NOMEM;
        }
    }

    dynamic_string_deinit(&string);

    return rc;
}

static int build_create_table_definition_sql(
    const struct planned_create_table *plan,
    const char *physical_name,
    bool temporary,
    char **out_sql
) {
    struct dynamic_string string;
    int rc = MYLITE_OK;

    *out_sql = NULL;
    dynamic_string_init(&string);

    rc = append_create_table_definition_sql(&string, plan, physical_name, temporary);
    if (rc == MYLITE_OK) {
        *out_sql = dynamic_string_take(&string);
        if (*out_sql == NULL) {
            rc = MYLITE_NOMEM;
        }
    }

    dynamic_string_deinit(&string);
    return rc;
}

static int append_create_table_definition_sql(
    struct dynamic_string *string,
    const struct planned_create_table *plan,
    const char *physical_name,
    bool temporary
) {
    const char *create_prefix = "CREATE TABLE ";
    int rc = MYLITE_OK;

    if (temporary) {
        create_prefix = "CREATE TEMPORARY TABLE ";
    }
    rc = dynamic_string_append(string, create_prefix);

    if (rc == MYLITE_OK) {
        rc = dynamic_string_append_quoted_identifier(string, physical_name);
    }
    if (rc == MYLITE_OK) {
        rc = dynamic_string_append(string, " (");
    }
    if (rc == MYLITE_OK) {
        rc = append_create_table_columns_sql(string, plan);
    }
    if (rc == MYLITE_OK) {
        rc = append_create_table_check_constraints_sql(string, plan);
    }
    if (rc == MYLITE_OK) {
        rc = dynamic_string_append_char(string, ')');
    }

    return rc;
}

static int build_create_table_indexes_sql(
    const struct planned_create_table *plan,
    const char *physical_name,
    char **out_sql
) {
    struct dynamic_string string;
    int rc = MYLITE_OK;

    *out_sql = NULL;
    dynamic_string_init(&string);

    if (plan->has_primary_key) {
        rc = append_create_table_primary_key_sql(&string, plan, physical_name);
    }
    if (rc == MYLITE_OK) {
        rc = append_create_table_secondary_indexes_sql(&string, plan, physical_name);
    }
    if (rc == MYLITE_OK && string.length != 0U) {
        *out_sql = dynamic_string_take(&string);
        if (*out_sql == NULL) {
            rc = MYLITE_NOMEM;
        }
    }

    dynamic_string_deinit(&string);
    return rc;
}

static int append_create_table_columns_sql(
    struct dynamic_string *string,
    const struct planned_create_table *plan
) {
    int rc = MYLITE_OK;

    for (size_t column_index = 0U; rc == MYLITE_OK && column_index < plan->column_count;
         ++column_index) {
        const struct planned_column *column = &plan->columns[column_index];

        if (column_index != 0U) {
            rc = dynamic_string_append(string, ", ");
        }
        if (rc == MYLITE_OK) {
            rc = dynamic_string_append_quoted_identifier(string, column->name);
        }
        if (rc == MYLITE_OK) {
            rc = dynamic_string_append_char(string, ' ');
        }
        if (rc == MYLITE_OK) {
            rc = dynamic_string_append(string, column->physical_type);
        }
        if (rc == MYLITE_OK && !column->is_nullable) {
            rc = dynamic_string_append(string, " NOT NULL");
        }
    }

    return rc;
}

static int append_create_table_check_constraints_sql(
    struct dynamic_string *string,
    const struct planned_create_table *plan
) {
    int rc = MYLITE_OK;

    for (size_t index = 0U; rc == MYLITE_OK && index < plan->check_constraint_count; ++index) {
        const struct planned_check_constraint *check_constraint = &plan->check_constraints[index];

        if (!check_constraint->is_enforced) {
            continue;
        }
        rc = dynamic_string_append(string, ", CONSTRAINT ");
        if (rc == MYLITE_OK) {
            rc = dynamic_string_append_quoted_identifier(string, check_constraint->physical_name);
        }
        if (rc == MYLITE_OK) {
            rc = dynamic_string_append(string, " CHECK (");
        }
        if (rc == MYLITE_OK) {
            rc = dynamic_string_append(string, check_constraint->sqlite_expression);
        }
        if (rc == MYLITE_OK) {
            rc = dynamic_string_append_char(string, ')');
        }
    }

    return rc;
}

static int append_create_table_primary_key_sql(
    struct dynamic_string *string,
    const struct planned_create_table *plan,
    const char *physical_name
) {
    int rc =
        append_create_table_index_sql(string, true, plan->primary_key_physical_name, physical_name);

    for (size_t part_index = 0U; rc == MYLITE_OK && part_index < plan->primary_key_part_count;
         ++part_index) {
        size_t column_index = plan->primary_key_parts[part_index].column_index;

        if (part_index != 0U) {
            rc = dynamic_string_append(string, ", ");
        }
        if (rc == MYLITE_OK) {
            rc = append_planned_key_part_sql(string, &plan->columns[column_index]);
        }
        if (rc == MYLITE_OK && plan->primary_key_parts[part_index].sort_direction ==
                                   MYLITE_CATALOG_INDEX_SORT_DIRECTION_DESC) {
            rc = dynamic_string_append(string, " DESC");
        }
    }
    if (rc == MYLITE_OK) {
        rc = append_create_table_index_sql_close(string);
    }

    return rc;
}

static int append_create_table_secondary_indexes_sql(
    struct dynamic_string *string,
    const struct planned_create_table *plan,
    const char *physical_name
) {
    int rc = MYLITE_OK;

    for (size_t index = 0U; rc == MYLITE_OK && index < plan->secondary_index_count; ++index) {
        const struct planned_secondary_index *secondary = &plan->secondary_indexes[index];

        if (planned_secondary_index_is_fulltext(secondary) ||
            planned_secondary_index_is_spatial(secondary)) {
            continue;
        }
        rc = append_create_table_index_sql(
            string,
            secondary->is_unique,
            secondary->physical_name,
            physical_name
        );
        for (size_t part_index = 0U; rc == MYLITE_OK && part_index < secondary->part_count;
             ++part_index) {
            if (part_index != 0U) {
                rc = dynamic_string_append(string, ", ");
            }
            if (rc == MYLITE_OK) {
                rc = append_planned_secondary_key_part_sql(
                    string,
                    plan,
                    &secondary->parts[part_index]
                );
            }
        }
        if (rc == MYLITE_OK) {
            rc = append_create_table_index_sql_close(string);
        }
    }

    return rc;
}

static int append_create_table_index_sql(
    struct dynamic_string *string,
    bool is_unique,
    const char *index_physical_name,
    const char *table_physical_name
) {
    int rc = dynamic_string_append(string, "; CREATE ");

    if (rc == MYLITE_OK && is_unique) {
        rc = dynamic_string_append(string, "UNIQUE ");
    }
    if (rc == MYLITE_OK) {
        rc = dynamic_string_append(string, "INDEX ");
    }
    if (rc == MYLITE_OK) {
        rc = dynamic_string_append_quoted_identifier(string, index_physical_name);
    }
    if (rc == MYLITE_OK) {
        rc = dynamic_string_append(string, " ON ");
    }
    if (rc == MYLITE_OK) {
        rc = dynamic_string_append_quoted_identifier(string, table_physical_name);
    }
    if (rc == MYLITE_OK) {
        rc = dynamic_string_append(string, " (");
    }

    return rc;
}

static int append_create_table_index_sql_close(struct dynamic_string *string) {
    return dynamic_string_append_char(string, ')');
}

static int append_planned_key_part_sql(
    struct dynamic_string *string,
    const struct planned_column *column
) {
    int rc = dynamic_string_append_quoted_identifier(string, column->name);

    if (rc == MYLITE_OK && planned_column_is_char_or_varchar(column)) {
        rc = append_string_key_collation_sql(string);
    }

    return rc;
}

static int append_planned_secondary_key_part_sql(
    struct dynamic_string *string,
    const struct planned_create_table *plan,
    const struct planned_secondary_index_part *part
) {
    const struct planned_column *column = &plan->columns[part->column_index];
    char prefix_text[integer_text_capacity];
    int rc = MYLITE_OK;

    if (!part->has_prefix_length) {
        rc = append_planned_key_part_sql(string, column);
    } else {
        rc = dynamic_string_append(string, "substr(");
    }
    if (rc == MYLITE_OK && part->has_prefix_length) {
        rc = dynamic_string_append_quoted_identifier(string, column->name);
    }
    if (rc == MYLITE_OK && part->has_prefix_length) {
        int written = snprintf(prefix_text, sizeof(prefix_text), "%" PRId64, part->prefix_length);

        if (written < 0 || (size_t)written >= sizeof(prefix_text)) {
            return MYLITE_NOMEM;
        }
        rc = dynamic_string_append(string, ", 1, ");
    }
    if (rc == MYLITE_OK && part->has_prefix_length) {
        rc = dynamic_string_append(string, prefix_text);
    }
    if (rc == MYLITE_OK && part->has_prefix_length) {
        rc = dynamic_string_append_char(string, ')');
    }
    if (rc == MYLITE_OK && part->has_prefix_length && planned_column_is_string_family(column)) {
        rc = append_string_key_collation_sql(string);
    }
    if (rc == MYLITE_OK && part->sort_direction == MYLITE_CATALOG_INDEX_SORT_DIRECTION_DESC) {
        rc = dynamic_string_append(string, " DESC");
    }

    return rc;
}

static int append_loaded_key_part_sql(
    struct dynamic_string *string,
    const struct loaded_index_part *part,
    const char *qualifier
) {
    int rc = MYLITE_OK;

    if (part != NULL && part->index_column.has_prefix_length) {
        return append_loaded_prefix_key_part_sql(string, part, qualifier);
    }

    if (qualifier != NULL) {
        rc = dynamic_string_append_quoted_identifier(string, qualifier);
        if (rc == MYLITE_OK) {
            rc = dynamic_string_append_char(string, '.');
        }
    }
    if (rc == MYLITE_OK) {
        rc = dynamic_string_append_quoted_identifier(string, part->column.name);
    }
    if (rc == MYLITE_OK && column_descriptor_is_char_or_varchar(&part->column)) {
        rc = append_string_key_collation_sql(string);
    }

    return rc;
}

static int append_loaded_prefix_key_part_sql(
    struct dynamic_string *string,
    const struct loaded_index_part *part,
    const char *qualifier
) {
    char prefix_text[integer_text_capacity];
    int rc = MYLITE_OK;
    int written = 0;

    written =
        snprintf(prefix_text, sizeof(prefix_text), "%" PRId64, part->index_column.prefix_length);
    if (written < 0 || (size_t)written >= sizeof(prefix_text)) {
        return MYLITE_NOMEM;
    }

    rc = dynamic_string_append(string, "substr(");
    if (rc == MYLITE_OK && qualifier != NULL) {
        rc = dynamic_string_append_quoted_identifier(string, qualifier);
        if (rc == MYLITE_OK) {
            rc = dynamic_string_append_char(string, '.');
        }
    }
    if (rc == MYLITE_OK) {
        rc = dynamic_string_append_quoted_identifier(string, part->column.name);
    }
    if (rc == MYLITE_OK) {
        rc = dynamic_string_append(string, ", 1, ");
    }
    if (rc == MYLITE_OK) {
        rc = dynamic_string_append(string, prefix_text);
    }
    if (rc == MYLITE_OK) {
        rc = dynamic_string_append_char(string, ')');
    }
    if (rc == MYLITE_OK && column_descriptor_is_string_family(&part->column)) {
        rc = append_string_key_collation_sql(string);
    }

    return rc;
}

static int append_loaded_key_part_parameter_sql(
    struct dynamic_string *string,
    const struct loaded_index_part *part,
    size_t parameter_index
) {
    char prefix_text[integer_text_capacity];
    int rc = MYLITE_OK;
    int written = 0;

    if (part == NULL || !part->index_column.has_prefix_length) {
        return append_numbered_parameter(string, parameter_index);
    }

    written =
        snprintf(prefix_text, sizeof(prefix_text), "%" PRId64, part->index_column.prefix_length);
    if (written < 0 || (size_t)written >= sizeof(prefix_text)) {
        return MYLITE_NOMEM;
    }

    rc = dynamic_string_append(string, "substr(");
    if (rc == MYLITE_OK) {
        rc = append_numbered_parameter(string, parameter_index);
    }
    if (rc == MYLITE_OK) {
        rc = dynamic_string_append(string, ", 1, ");
    }
    if (rc == MYLITE_OK) {
        rc = dynamic_string_append(string, prefix_text);
    }
    if (rc == MYLITE_OK) {
        rc = dynamic_string_append_char(string, ')');
    }
    if (rc == MYLITE_OK && column_descriptor_is_string_family(&part->column)) {
        rc = append_string_key_collation_sql(string);
    }

    return rc;
}

static int append_string_key_collation_sql(struct dynamic_string *string) {
    int rc = dynamic_string_append(string, " COLLATE ");

    if (rc == MYLITE_OK) {
        rc = dynamic_string_append_quoted_identifier(string, string_key_collation_name);
    }

    return rc;
}

